/**
 * 负责规范玩家故障报告并按日次／阶段限流去重；输入是调用方上下文和原始报告字段，输出为拒绝、丢弃或接受标识。
 * 本服务实例独占三份去重／计数集合，实际报告记录归会话记录器，角色仅用作诊断元数据。
 * 只校验类别、严重程度和消息，不复验 actor/day/phase 的游戏许可，不提交动作或修改角色资源。
 * 直接报告记录及接受回调可传播失败；已经写入的记录和本地计数保留，不承诺事务回滚。
 */
import { toolFailure } from "@ai-werewolf-arena/game-text";
import { COMPONENT } from "../../../core/domain/components/names";
import { RoleComponent } from "../../../core/domain/components/role";
import { World } from "../../../core/domain/world";
import { safeRecordLogicOp } from "../../../recording/session_recorder";
import { getSessionRecorder } from "../../../recording/recording_context";

export type AgentBugCategory = "flow" | "rule" | "state" | "logging" | "other";
export type AgentBugSeverity = "low" | "medium" | "high" | "critical";

/** actor/day/phase/stage 由调用方给定；unknown 三字段先规范，身份元数据稍后从 World 查询。 */
export interface AgentBugReportInput {
  actorId: number;
  day: number;
  phase: string;
  stage: string;
  category: unknown;
  severity: unknown;
  message: unknown;
}

/** 无效报告是工具拒绝；已限流报告仍 ok=true，但 accepted=false 且没有新报告标识。 */
export type AgentBugReportResult =
  | { ok: false; error: string; message: string }
  | { ok: true; accepted: false; dropped: true; reason: string }
  | { ok: true; accepted: true; report_id: string };

export interface AgentBugReportServiceOptions {
  maxPerActorPerDay?: number;
  /** 记录及去重账本更新之后同步调用；回调失败不撤销已接受前缀。 */
  onAccepted?: (report: NormalizedAgentBugReport, reportId: string) => void;
}

/** 只替换类别、级别和 trim 后消息，其余上下文字段保持输入值；不代表验证了游戏状态。 */
export interface NormalizedAgentBugReport extends Omit<
  AgentBugReportInput,
  "category" | "severity" | "message"
> {
  category: AgentBugCategory;
  severity: AgentBugSeverity;
  message: string;
}

const CATEGORIES = new Set<AgentBugCategory>(["flow", "rule", "state", "logging", "other"]);
const SEVERITIES = new Set<AgentBugSeverity>(["low", "medium", "high", "critical"]);

/**
 * SDK／ACP 使用同一份报告处理实现；各实例保持自己的去重状态，不共享全局计数账本。
 */
export class AgentBugReportService {
  // 三类键分别限制 actor/day 总量、同阶段名额和规范消息；跨阶段相同消息仍占同日重复键。
  private readonly acceptedScopes = new Set<string>();
  private readonly acceptedMessages = new Set<string>();
  private readonly acceptedCountByActorDay = new Map<string, number>();
  private readonly maxPerActorPerDay: number;

  constructor(
    private readonly world: World,
    private readonly options: AgentBugReportServiceOptions = {},
  ) {
    this.maxPerActorPerDay = Math.max(1, options.maxPerActorPerDay ?? 3);
  }

  report(input: AgentBugReportInput): AgentBugReportResult {
    const parsed = this.normalize(input);
    if (!parsed.ok) {
      this.recordRejected(input, parsed.error);
      return toolFailure(this.world.locale, parsed.error);
    }
    const report = parsed.value;
    const actorDayKey = `${report.actorId}|${report.day}`;
    const scopeKey = `${actorDayKey}|${report.phase}|${report.stage}`;
    const messageKey = `${actorDayKey}|${report.category}|${report.severity}|${normalizeMessage(report.message)}`;
    const acceptedCount = this.acceptedCountByActorDay.get(actorDayKey) ?? 0;

    // 拒绝原因按总量→阶段→消息首命中；计数检查不会提前消耗后续名额。
    const droppedReason =
      acceptedCount >= this.maxPerActorPerDay
        ? "report_bug_actor_day_rate_limited"
        : this.acceptedScopes.has(scopeKey)
          ? "report_bug_scope_rate_limited"
          : this.acceptedMessages.has(messageKey)
            ? "report_bug_duplicate_message"
            : undefined;
    if (droppedReason) {
      safeRecordLogicOp({
        scope: "llm_action_provider",
        op: "report_bug_dropped",
        actorId: report.actorId,
        phase: report.phase,
        status: "fallback",
        reason: droppedReason,
        input: { day: report.day, stage: report.stage },
      });
      return { ok: true, accepted: false, dropped: true, reason: droppedReason };
    }

    // 限流通过后才查询角色并直接追加诊断记录；无记录器仍返回原占位标识，未作行动授权。
    const role = this.world.getComponent(report.actorId, COMPONENT.Role);
    const reportId =
      getSessionRecorder()?.recordDebugReport({
        timestampMs: Date.now(),
        day: report.day,
        phase: report.phase,
        stage: report.stage,
        actorId: report.actorId,
        actorRole: role?.role ?? "unknown",
        actorCamp: role?.camp ?? "unknown",
        category: report.category,
        severity: report.severity,
        message: report.message,
      }) ?? "rb-no-recorder";

    // 记录取得标识之后再依次消费三份名额；随后日志或回调失败仍保留已消费前缀。
    this.acceptedScopes.add(scopeKey);
    this.acceptedMessages.add(messageKey);
    this.acceptedCountByActorDay.set(actorDayKey, acceptedCount + 1);
    safeRecordLogicOp({
      scope: "llm_action_provider",
      op: "report_bug_recorded",
      actorId: report.actorId,
      phase: report.phase,
      status: "ok",
      output: {
        report_id: reportId,
        category: report.category,
        severity: report.severity,
      },
    });
    this.options.onAccepted?.(report, reportId);
    return { ok: true, accepted: true, report_id: reportId };
  }

  private normalize(
    input: AgentBugReportInput,
  ): { ok: true; value: NormalizedAgentBugReport } | { ok: false; error: string } {
    // 先完成类别／级别转换和消息trim，再按类别→级别→空消息→长度返回首错误；不吞转换异常。
    const category = String(input.category ?? "") as AgentBugCategory;
    const severity = String(input.severity ?? "") as AgentBugSeverity;
    const message = typeof input.message === "string" ? input.message.trim() : "";
    if (!CATEGORIES.has(category)) return { ok: false, error: "invalid_report_bug_category" };
    if (!SEVERITIES.has(severity)) return { ok: false, error: "invalid_report_bug_severity" };
    if (!message) return { ok: false, error: "invalid_report_bug_message_empty" };
    if (message.length > 300) return { ok: false, error: "invalid_report_bug_message_too_long" };
    return { ok: true, value: { ...input, category, severity, message } };
  }

  private recordRejected(input: AgentBugReportInput, reason: string): void {
    safeRecordLogicOp({
      scope: "llm_action_provider",
      op: "report_bug_rejected",
      actorId: input.actorId,
      phase: input.phase,
      status: "rejected",
      reason,
      input: {
        args: { category: input.category, severity: input.severity, message: input.message },
      },
    });
  }
}

/** 重复键统一大小写和空白，实际记录仍保留 trim 后的原消息；不改模型发言或游戏事件。 */
function normalizeMessage(message: string): string {
  return message.toLowerCase().replace(/\s+/g, " ").trim();
}

/**
 * 负责：从原配置与显式选项装配 World、角色组件、机制和真实游戏运行时。
 * 输入：BoardConfig、角色与随机源选项；输出：原初始化对象及同一参数和 RulePlan owner。
 * 先在原 deal fork 后验证支持范围并洗牌，再初始化实体；不读取模型认证或选择玩家动作。
 * 校验后的配置克隆在角色初始化前冻结，原 World、actor、RNG 和调用方均不冻结。
 * PhaseManager 创建规则计划，流水线、开局上下文和记录入口消费同一引用。
 */
import {
  createAliveComponent,
  createBadgeComponent,
  createCampComponent,
  createStatusMarksComponent,
  createVotingRightComponent,
} from "../game/observation/component-presentation";
import { installNobleBodyAuthority } from "../game/mechanisms/roles/noble_secret_body/authority";
import { installAnimalAuthority } from "../game/mechanisms/roles/animal_dream/authority";
import { buildSupportedRoleDeck } from "../rulesets/supported-role-deck";
import { BoardParameters, bindBoardParameters } from "../rulesets/board-parameters";
import type { RulePlan } from "../rulesets/rule-plan";
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { installRadiantEclipseBoard } from "../game/mechanisms/roles/radiant_eclipse/night_frame";
import { installMistRavenBoard } from "../game/mechanisms/roles/mist_raven/night_frame";
import { installScholarMentorBoard } from "../game/mechanisms/roles/scholar_mentor/night_frame";
import { installTimeConsortBoard } from "../game/mechanisms/roles/time_wolf_consort/night_frame";
import { installWolfSorcererBoard } from "../game/mechanisms/roles/wolf_sorcerer/night_frame";
import { installTricksterBoard } from "../game/mechanisms/roles/trickster/night_frame";
import { installOrderPrinceBoard } from "../game/mechanisms/roles/order_prince/authority";
import { installMagicianBoard } from "../game/mechanisms/roles/magician/night_frame";
import { installNightmareBoard } from "../game/mechanisms/roles/nightmare_shadow/night_frame";
import { installEvilKnightBoard } from "../game/mechanisms/roles/evil_knight/night_frame";
import { installDemonHunter } from "../game/mechanisms/roles/demon_hunter/authority";
import { WinConditionRegistry as PureWhiteWinRegistry } from "../game/mechanisms/registries/win_condition_registry";
import { createEliminationWinConditionSpecs } from "../game/mechanisms/win_conditions/default_specs";
import { installGhostBride } from "../game/mechanisms/roles/ghost_bride/authority";
import { installLonelyGirl } from "../game/mechanisms/roles/lonely_girl/lifecycle";
import { installWildChild } from "../game/mechanisms/roles/wild_child/lifecycle";
import { installInitialRoster } from "../core/domain/initial_roster";
import { installShapeshifterDeal } from "../game/mechanisms/roles/shapeshifter/deal";
import { installThiefDeal } from "../game/mechanisms/roles/thief/deal";
import { supportsWallRoles } from "../game/mechanisms/events/wall_notes/authority";
import { text } from "@ai-werewolf-arena/game-text";

import { COMPONENT } from "../core/domain/components/names";
import type { RoleComponent } from "../core/domain/components/role";
import { createRoleComponent } from "../game/observation/role-presentation";

import { createVictoryComponent } from "../core/domain/components/victory";
import { createIdentityComponent } from "../core/domain/entities/player";
import { BoardConfig, EntityId, Role } from "../core/domain/model";
import {
  getDefaultWinConditionRegistry,
  getDefaultRoleCatalog,
  assignInitialSheriff,
  createDefaultRoleRegistry,
} from "../game/mechanisms";
import { ConditionRegistry } from "../core/domain/registries/condition_registry";
import { DamageResolutionSystem } from "../core/domain/systems/damage_resolution_system";
import { World } from "../core/domain/world";
import { PhaseManager } from "../game/engine/phase_manager";
import { ToolGateway } from "../game/gateway/tool_gateway";
import { createRandom, shuffled, type RandomSource } from "../core/domain/random";
import type { Locale } from "@ai-werewolf-arena/game-contract";

/**
 * bootstrap 负责把“配置”装配成“可运行对局上下文”。
 * 这是服务层启动游戏引擎的唯一入口。
 */
export interface BootstrapResult {
  world: World;
  readonly boardConfig: ReadonlyBoardConfig;
  readonly parameters: BoardParameters;
  readonly rulePlan: RulePlan;
  phaseManager: PhaseManager;
  playerIds: EntityId[];
  random: RandomSource;
  dealMode: "random" | "fixed";
}

export interface BootstrapOptions {
  locale?: Locale;
  playerNames?: Readonly<Record<string, string>>;
  random?: RandomSource;
  /** 仅供 controller fixture：明确牌堆仍按原数量严格验证。 */
  fixedRoles?: readonly Role[];
  /** 显式离线因果测试输入，不是板子或模型参数。 */
  faultPlan?: unknown;
}

/**
 * 按板子配置完成一次完整引擎装配，返回可直接运行的上下文对象。
 */
export function bootstrapGame(
  config: BoardConfig,
  options: BootstrapOptions = {},
): BootstrapResult {
  const world = new World(options.locale);
  const random = options.random ?? createRandom();
  // 先完成实体与组件初始化，再创建系统与管理器，避免空引用。
  const initialized = createPlayers(world, config, options, random);
  const playerIds = initialized.playerIds;
  const parameters = initialized.parameters;
  const boardConfig = parameters.board;
  assignInitialSheriff(world, boardConfig, playerIds);

  const roleRegistry = createDefaultRoleRegistry();
  const damageResolutionSystem = new DamageResolutionSystem();
  const conditionRegistry = new ConditionRegistry(
    boardConfig.pureWhite || boardConfig.animalDream
      ? new PureWhiteWinRegistry(
          createEliminationWinConditionSpecs(
            boardConfig.pureWhite?.eliminationPriority ?? "awa_wolf_priority_v1",
          ),
        )
      : getDefaultWinConditionRegistry(),
  );
  const toolGateway = new ToolGateway();

  const phaseManager = new PhaseManager(
    world,
    boardConfig,
    toolGateway,
    roleRegistry,
    conditionRegistry,
    damageResolutionSystem,
    random,
    { faultPlan: options.faultPlan },
  );

  return Object.freeze({
    world,
    boardConfig,
    parameters,
    rulePlan: phaseManager.getRulePlan(),
    phaseManager,
    playerIds,
    random,
    dealMode: options.fixedRoles ? "fixed" : "random",
  });
}

function createPlayers(
  world: World,
  inputConfig: BoardConfig,
  options: BootstrapOptions,
  random: RandomSource,
): { playerIds: EntityId[]; parameters: BoardParameters } {
  const fixedRoles = options.fixedRoles;
  const dealRandom = random.fork("deal");
  const candidateParameters = BoardParameters.compile(inputConfig);
  const config = candidateParameters.board;
  const roles = buildRoleDeck(config, fixedRoles, dealRandom);
  const parameters = bindBoardParameters(world, candidateParameters);
  const ids: EntityId[] = [];
  const roleCatalog = getDefaultRoleCatalog();

  for (let seat = 1; seat <= config.boardSize; seat++) {
    const entityId = world.createEntity();
    const role = roles[seat - 1];
    const roleComp = createRoleComponent(role, roleCatalog.getCamp(role), world.locale);
    roleCatalog.applyRuntime(roleComp, { boardConfig: config, locale: world.locale, world });

    world.addComponent(
      entityId,
      COMPONENT.Identity,
      createIdentityComponent(
        entityId,
        seat,
        options.playerNames?.[String(seat)] ??
          text(world.locale, "common.player_name", { id: seat }),
      ),
    );
    world.addComponent(entityId, COMPONENT.Role, roleComp);
    world.addComponent(entityId, COMPONENT.Camp, createCampComponent(roleComp.camp, world.locale));
    const membership = roleCatalog.requireRuntime(role).initialVictoryAffiliations;
    world.addComponent(
      entityId,
      COMPONENT.Victory,
      createVictoryComponent(
        typeof membership === "function"
          ? membership(roleComp, { boardConfig: config, locale: world.locale })
          : (membership ?? [{ kind: "faction", faction: roleComp.camp }]),
      ),
    );
    world.addComponent(entityId, COMPONENT.Alive, createAliveComponent(true, world.locale));
    world.addComponent(entityId, COMPONENT.StatusMarks, createStatusMarksComponent(world.locale));
    world.addComponent(
      entityId,
      COMPONENT.VotingRight,
      createVotingRightComponent(1, true, world.locale),
    );
    world.addComponent(entityId, COMPONENT.Badge, createBadgeComponent(false, false, world.locale));
    ids.push(entityId);
  }

  if (config.roleSetups.some((row) => row.role === Role.Thief && row.count === 1))
    installThiefDeal(world, roles, ids);
  if (config.roleSetups.some((row) => row.role === Role.Shapeshifter && row.count === 1))
    installShapeshifterDeal(world, roles, ids);
  installInitialRoster(world);
  if (config.animalDream) installAnimalAuthority(world, config);
  if (roles.includes(Role.Alchemist) || roles.includes(Role.RavenClawWolf))
    installMistRavenBoard(world);
  if (config.radiantEclipse) installRadiantEclipseBoard(world);
  if (roles.includes(Role.DayScholar) || roles.includes(Role.NightMentor))
    installScholarMentorBoard(world);
  if (roles.includes(Role.TimeWolfConsort)) installTimeConsortBoard(world);
  if (roles.includes(Role.Trickster)) installTricksterBoard(world);
  if (roles.includes(Role.Magician)) installMagicianBoard(world);
  if (roles.includes(Role.WolfSorcerer)) installWolfSorcererBoard(world);
  if (roles.includes(Role.OrderPrince)) installOrderPrinceBoard(world);
  if (roles.includes(Role.EvilKnight)) installEvilKnightBoard(world);
  if (roles.includes(Role.NightmareShadow)) installNightmareBoard(world);
  if (config.nobleSecretBody)
    installNobleBodyAuthority(
      world,
      ids.find((id) => world.getComponent(id, COMPONENT.Role)?.role === Role.NightNoble)!,
      ids.find((id) => world.getComponent(id, COMPONENT.Role)?.role === Role.AwakenedIdiot)!,
    );
  if (roles.includes(Role.DemonHunter)) installDemonHunter(world, config);
  if (roles.includes(Role.GhostBride)) installGhostBride(world, config);
  installWildChild(world, config);
  installLonelyGirl(world, config);
  return { playerIds: ids, parameters };
}

function buildRoleDeck(
  config: ReadonlyBoardConfig,
  fixedRoles: readonly Role[] | undefined,
  random: RandomSource,
): Role[] {
  const deck = buildSupportedRoleDeck(config, fixedRoles, getDefaultRoleCatalog, supportsWallRoles);
  return fixedRoles ? deck : shuffled(deck, random);
}

/**
 * 负责把 Agent 已结束的一轮决策转为当前会话的玩家录制输入。输入为原请求、提示和选择结果，
 * 输出为原时间线字段；应用适配持有 World 与每位玩家的计数，AI 只调用记录入口。
 * 无录制作用域时立即返回；有作用域时先读取当前角色，再递增计数，随后读取日次和阶段，
 * 不缓存 actorId、不回滚已递增计数，原字段 getter 与录制失败前缀保持。
 * 接受工具或记录 finalAction 不表示领域付款、生效或判胜；会话聚合和文件持久化仍归记录器。
 */
import { COMPONENT } from "../core/domain/components/names";
import type { RoleComponent } from "../core/domain/components/role";
import type { ActionRequest, EntityId } from "@ai-werewolf-arena/game-contract";
import {
  getActionRequestDay,
  getActionRequestStage,
} from "../core/domain/action_request_context";
import type { World } from "../core/domain/world";
import { getSessionRecorder } from "../recording/recording_context";
import type { BuiltPlayerPrompt, PlayerRoundOutcome } from "../ai/agents/player/contracts";

/** 唯一拥有本适配实例的玩家计数；记录失败保留已递增前缀，不另建第二份计数账本。 */
export class PlayerRoundRecorder {
  // 在原字段位置创建 Map；多个玩家共享此适配实例时仍分别连续计数。
  private readonly roundCounters = new Map<EntityId, number>();

  constructor(private readonly world: World) {}

  record(request: ActionRequest, prompt: BuiltPlayerPrompt, outcome: PlayerRoundOutcome): void {
    const recorder = getSessionRecorder();
    if (!recorder) return;
    const role = this.world.getComponent(request.actorId, COMPONENT.Role);
    const round = (this.roundCounters.get(request.actorId) ?? 0) + 1;
    this.roundCounters.set(request.actorId, round);
    // 计数已更新才读取请求元数据，后续 getter／录制错误不恢复旧计数。
    const day = getActionRequestDay(request);
    const phase = String(request.phase);
    const stage = getActionRequestStage(request);
    recorder.recordPlayerRound({
      playerId: request.actorId,
      role: role?.role ?? "unknown",
      camp: role?.camp ?? "unknown",
      day,
      phase,
      stage,
      requestId: `${day}-${phase}-${request.actorId}-${round}`,
      timestampMs: Date.now(),
      llmRequestMessages: [{ role: "user", content: prompt.userPrompt }],
      promptSystem: prompt.systemPrompt,
      ...(round === 1
        ? {
            initialPromptSystem: prompt.systemPrompt,
            initialBoardInfo: prompt.boardInfoPrompt,
          }
        : {}),
      promptUserDelta: prompt.auditMetadata ?? [
        `context_window=${prompt.contextWindowStart}-${prompt.contextWindowEnd}/${prompt.contextWindowTotal};event_cursor=${prompt.eventCursorBefore}->${prompt.eventCursorAfter}`,
      ],
      retryTrace: outcome.retryTrace,
      thinkingText: outcome.thinkingText,
      actionMode: outcome.actionMode,
      toolCalls: outcome.toolCalls,
      finalAction: outcome.finalAction ?? null,
      fallback: outcome.fallback,
    });
  }
}

/**
 * 定义角色组件与不透明只读私有容器的数据结构。输入为角色与阵营；输出保持原组件和
 * 空记录引用。领域不查询语言、格式化提示、初始化机制槽或冻结演员；实际展示由游戏侧
 * 创建／Catalog 装配，读方不取得私有容器写权，原 role/camp 写权限仍由具体所有者负责。
 */
import { Camp, Role } from "@ai-werewolf-arena/game-contract";

export interface RoleComponent {
  role: Role;
  camp: Camp;
  readonly privateState: object;
}

/** 仅创建领域数据；机制初始化与展示绑定在实际游戏装配处执行。 */
export function createRoleComponent(role: Role, camp: Camp): RoleComponent {
  return { role, camp, privateState: {} };
}

/**
 * Owns the once-installed original role/camp roster for a World. Input is the dealt entity list;
 * output is an immutable identity entry by player ID. Later role conversion does not rewrite
 * this roster, and reads never fall back to a new identity.
 */
import { COMPONENT } from "./components/names";
import type { RoleComponent } from "./components/role";
import type { Role, Camp } from "./identity";
import type { World } from "./world";
const rosters = new WeakMap<World, ReadonlyMap<number, Readonly<{ role: Role; camp: Camp }>>>();
export function installInitialRoster(world: World): void {
  if (rosters.has(world)) throw new Error("initial_roster_already_installed");
  rosters.set(
    world,
    new Map(
      world.entityIds().map((id) => {
        const role = world.getComponent(id, COMPONENT.Role)!;
        return [id, Object.freeze({ role: role.role, camp: role.camp })];
      }),
    ),
  );
}
export function initialPlayerIdentity(
  world: World,
  id: number,
): Readonly<{ role: Role; camp: Camp }> | undefined {
  return rosters.get(world)?.get(id);
}

/**
 * 负责共用参与者的原生命、Role 与私有容器引用捕获和晚复验。输入为原 World／玩家 ID，
 * 输出保留原可写快照及当前性布尔值；不写 World、资源、阶段或领域许可。
 * 只复用原生命版本规则，Role 字段按原普通属性读取；getter／Proxy 可执行并按原时点抛错。
 * 不读取 Camp 组件、不校验枚举／JSON／完整槽、不建立 brand 或冻结快照；严格原体契约另有所有者。
 */
import { COMPONENT } from "./components/names";
import type { RoleComponent } from "./components/role";
import type { World } from "./world";
import { captureNightLife, livingNightLife, type NightLifeScope } from "./night_effects";

/** 保原可写顶层字段与组件引用；camp 是捕获的 Role.camp 值，不是 Camp 组件或独立行动权限。 */
export interface OriginalParticipant {
  life: NightLifeScope;
  role: RoleComponent;
  roleId: RoleComponent["role"];
  camp: RoleComponent["camp"];
  state: RoleComponent["privateState"];
}
/** 原生命先捕获，再查询 Role；仅两者存在才按 role→camp→privateState 读取，不复制或提前取字段。 */
export function captureOriginalParticipant(world: World, id: number): OriginalParticipant | null {
  const life = captureNightLife(world, id),
    role = world.getComponent(id, COMPONENT.Role);
  return life && role
    ? { life, role, roleId: role.role, camp: role.camp, state: role.privateState }
    : null;
}
/** 生命／版本先短路，再核同 Role 引用及原三个字段；不新增 descriptor、Camp 引用或状态内容检查。 */
export function sameOriginalParticipant(world: World, snapshot: OriginalParticipant): boolean {
  return (
    livingNightLife(world, snapshot.life) &&
    world.getComponent(snapshot.life.id, COMPONENT.Role) === snapshot.role &&
    snapshot.role.role === snapshot.roleId &&
    snapshot.role.camp === snapshot.camp &&
    snapshot.role.privateState === snapshot.state
  );
}

/**
 * 负责 mock、smoke 与规则测试的特权基线决策。输入为原 World、请求和角色目录，
 * 输出为按既定席位与角色策略选出的工具动作；可读取真实阵营，不作为玩家受限观察或生产模型回退。
 * 本模块拥有启发式选择，行动许可、付款、事实发布和最终规则结算仍由引擎及具体机制重检。
 * 无模型、网络或独立随机源；候选按原查询时点读取，异常保留已完成的读取与脚本前缀。
 */
import { roleInspectionPolicy } from "@ai-werewolf-arena/game-contract/role-inspection-policy";
import { scholarMentorBonusTargets } from "../mechanisms/roles/scholar_mentor/night_frame";
import { prohibitsLoversVote } from "../mechanisms/roles/cupid/relation";
import { text } from "@ai-werewolf-arena/game-text";
