/**
 * PhaseManager 是游戏引擎的时序中枢。
 * 负责串行驱动夜晚/白天/投票，并在每个阶段后执行死亡钩子与胜负裁决。
 */
export class PhaseManager {
  readonly #rulePlan: RulePlan;
  private readonly config: ReadonlyBoardConfig;
  private readonly events: GameEvent[] = [];
  private readonly eventRegistry: EventRegistry;
  private readonly nightPipeline: NightPipeline;
  private readonly dayPipeline: DayPipeline;
  private readonly votingPipeline: VotingPipeline;
  private readonly deathResolution: DeathResolution;
  private previousExile: ExileFeedback | null = null;
  // 修订号唯一归此实例；正常同阶段不推进，debug 撤销与真实变化仍可分别推进。
  private readonly phaseRevision = new PhaseRevisionClock();
  // 唯一待处理实例仍归经理字段；本族序列不保存镜像，旧读取也观察同一实例。
  private mistPending: ReturnType<typeof prepareMistDelayedNight> | null = null;
  private readonly nightFaultPlan?: NightFaultPlan;

  private state: RuntimeSnapshot = {
    day: 1,
    phase: Phase.Night,
    gameOver: false,
    result: null,
  };

  constructor(
    private readonly world: World,
    config: ReadonlyBoardConfig,
    private readonly toolGateway: ToolGateway,
    private readonly roleRegistry: RoleRegistry,
    private readonly conditionRegistry: ConditionRegistry,
    private readonly damageResolutionSystem: DamageResolutionSystem,
    private readonly random: RandomSource = createRandom(),
    options: { faultPlan?: unknown } = {},
  ) {
    const parameters = bindBoardParameters(world, config);
    config = parameters.board;
    this.#rulePlan = RulePlan.compile(parameters);
    this.config = config;
    installFragrantGameSetup(config, { world: () => world, events: () => this.events });
    if (options.faultPlan !== undefined) {
      if (demonHunterActorId(world) === null) throw new Error("fault_plan_demon_board_required");
      this.nightFaultPlan = new NightFaultPlan(world, options.faultPlan);
    }
    this.eventRegistry = new EventRegistry();
    this.deathResolution = new DeathResolution(
      world,
      this.events,
      toolGateway,
      this.eventRegistry,
      this.state,
      config,
    );
    this.nightPipeline = new NightPipeline({
      rulePlan: this.#rulePlan,
      world,
      toolGateway,
      damageResolutionSystem,
      events: this.events,
      random: random.fork("night"),
    });
    this.dayPipeline = new DayPipeline({
      world,
      roleRegistry,
      toolGateway,
      events: this.events,
    });
    this.votingPipeline = new VotingPipeline({
      world,
      roleRegistry,
      toolGateway,
      eventRegistry: this.eventRegistry,
      events: this.events,
    });
    // 仅上帝可见：开局完整牌面信息（玩家身份与阵营映射）。
    this.events.push({
      timestamp: Date.now(),
      type: "god_private_game_info",
      payload: {
        boardSize: this.config.boardSize,
        players: this.world.getAliveEntityIds().map((id) => {
          const identity = this.world.getComponent(id, COMPONENT.Identity);
          const role = this.world.getComponent(id, COMPONENT.Role);
          return {
            id,
            seat: identity?.seat ?? id,
            name: identity?.name ?? text(this.world.locale, "common.player_name", { id }),
            role: role?.role ?? "unknown",
            camp: role?.camp ?? "unknown",
          };
        }),
      },
    });
    // 仅发布原整副公共牌组；各运行引用晚读，前面的私密牌表与后续阶段广播顺序不变。
    publishInitialIdentityDeal({
      world: () => this.world,
      events: () => this.events,
      boardSize: () => this.config.boardSize,
    });
    // 初始阶段也写入上帝公开广播，确保首轮请求前玩家可见当前阶段。
    this.events.push({
      timestamp: Date.now(),
      type: "phase_changed",
      payload: {
        phase: Phase.Night,
        day: this.state.day,
      },
    });
    const initialSheriffId = findSheriffId(this.world);
    // 只派发原检查点；每个贡献仍在原参数位置读取 World、事件与当前日期。
    this.#rulePlan.wolfKnifeInheritance({
      world: () => this.world,
      events: () => this.events,
      day: () => this.state.day,
    });
    if (initialSheriffId !== null) {
      this.events.push({
        timestamp: Date.now(),
        type: "sheriff_elected",
        payload: {
          winnerId: initialSheriffId,
          source: "initial_configuration",
        },
      });
    }
  }

  /** 获取不可变的离线故障输入；它与板子参数、已记录的取消事实分别持有。 */
  getFaultPlan(): FaultPlan | undefined {
    return this.nightFaultPlan?.plan;
  }

  assertFaultPlanConsumed(): void {
    this.nightFaultPlan?.assertConsumed();
  }

  /** 脱离克隆当前运行状态和完整结果数据，调用方不能通过快照修改内部胜利成员。 */
  getSnapshot(): RuntimeSnapshot {
    return structuredClone(this.state);
  }

  /** 获取脱离克隆的累计事件；历史 audience 数组在副本中保持冻结。 */
  getEvents(): GameEvent[] {
    return this.events.map((event) => {
      const copy = structuredClone(event);
      if ("audience" in copy) Object.freeze(copy.audience);
      return copy;
    });
  }

  /**
   * 手动跳转阶段（主要用于中断流程控制）。
   */
  jumpTo(phase: Phase): void {
    if (
      this.config.mistRaven &&
      !this.state.gameOver &&
      this.pureWhiteStartedDays.has(this.state.day)
    )
      throw new Error("mist_phase_reentry");
    // 雾鸦周期登记先行；其余机制通过后才推进原阶段时钟，拒绝不改变时钟。
    const manager = this;
    this.#rulePlan.phaseJumpAdmission({
      get world() { return manager.world; },
      get state() { return manager.state; },
    });
    this.phaseRevision.advance();
    this.setPhase(phase);
  }

  private readonly pureWhiteStartedDays = new Set<number>();

  async runSingleCycle(
    actionProvider: ActionProvider,
    maxDays: number = 20,
  ): Promise<RuntimeSnapshot> {
    if (
      (this.config.animalDream ||
        this.config.fragrantPairSeer ||
        this.config.mistRaven ||
        this.config.pureWhite ||
        this.config.evilKnight ||
        this.config.magician) &&
      !this.state.gameOver
    ) {
      if (this.pureWhiteStartedDays.has(this.state.day))
        throw new Error(
          this.config.animalDream
            ? "animal_cycle_reentry"
            : this.config.fragrantPairSeer
              ? "fragrant_cycle_reentry"
              : this.config.mistRaven
                ? "mist_cycle_reentry"
                : this.config.magician
                  ? "magician_cycle_reentry"
                  : this.config.evilKnight
                    ? "evil_knight_cycle_reentry"
                    : "pure_white_cycle_reentry",
        );
      this.pureWhiteStartedDays.add(this.state.day);
    }
    const startedDay = this.state.day;
    const manager = this;
    const lifecycle = this.#rulePlan.createNightManagerLifecycle({
      get world() {
        return manager.world;
      },
      get config() {
        return manager.config;
      },
      abortMistPending() {
        manager.mistPending?.abort();
      },
    });
    let completed = false;
    try {
      const result = await this.runSingleCycleInternal(actionProvider, maxDays, lifecycle);
      completed = this.state.gameOver || this.state.day > startedDay;
      return result;
    } catch (error) {
      lifecycle.abortOnError();
      throw error;
    } finally {
      lifecycle.abortCycle(completed);
    }
  }

  private async runSingleCycleInternal(
    actionProvider: ActionProvider,
    maxDays: number = 20,
    lifecycle: NightManagerLifecycle,
  ): Promise<RuntimeSnapshot> {
    // 不收集状态快照：每个原谓词仍在原参数位置读取 World、gameOver 和日期。
    const manager = this;
    this.#rulePlan.cycleAdmission({
      get world() { return manager.world; },
      get state() { return manager.state; },
    });
    if (this.state.gameOver) {
      return this.getSnapshot();
    }
    if (demonHunterActorId(this.world) !== null) {
      const underlying = actionProvider;
      const assertReadable = () => this.assertDemonReadable();
      actionProvider = {
        getAction: async (request) => {
          assertReadable();
          const action = await underlying.getAction(request);
          assertReadable();
          return action;
        },
      };
    }

    if (this.state.day > maxDays) {
      this.sealResult(
        { winner: null, reason: "max_days_reached", outcome: { kind: "no_winner" } },
        this.#rulePlan.checkpoints.maxDays,
        Phase.Night,
      );
      return this.getSnapshot();
    }

    this.setPhase(Phase.Night);
    if (this.config.mistRaven) {
      this.mistPending?.abort();
      this.mistPending = null;
    }
    const nightDay = this.state.day,
      nightRevision = this.phaseRevision.current;
    const nightIsCurrent = () =>
      this.state.day === nightDay &&
      this.state.phase === Phase.Night &&
      !this.state.gameOver &&
      this.phaseRevision.current === nightRevision;
    const setupSequence = prepareGameSetup({
      world: () => this.world,
      toolGateway: () => this.toolGateway,
      events: () => this.events,
      config: () => this.config,
    }, actionProvider, nightDay, nightIsCurrent);
    let setupStep = setupSequence.next();
    // 只等待原窗口的 execute；四项都已就绪时不让出微任务，阶段当前性也不额外查询。
    while (!setupStep.done) setupStep = setupSequence.next(await setupStep.value);
    if (!setupStep.value) return this.getSnapshot();
    assertDemonOriginalRoster(this.world);
    // 夜前只捕获同一熊 frame；原 World／policy 读取保持晚读，不提前发表或授予许可。
    const bearFrame = captureDawnKnowledge({
      world: () => this.world,
      signalPolicy: () => this.config.bear?.signalPolicy,
    }, nightDay);
    const night = await this.nightPipeline.execute(this.config, actionProvider, this.state.day, {
      previousExile: this.previousExile,
      isCurrent: nightIsCurrent,
      lifecycleHandoff: lifecycle,
    });
    if (night.interrupted || !nightIsCurrent()) {
      lifecycle.abortSpecialNight(night, nightDay);
      return this.getSnapshot();
    }
    const ownsWedding = weddingSetup(this.world) !== null;
    const ownsDemon = demonHunterActorId(this.world) !== null;
    const ownsPureWhite = this.config.pureWhite !== undefined;
    const ownsEvilKnight = this.config.evilKnight !== undefined;
    if (ownsWedding || ownsDemon || ownsPureWhite || ownsEvilKnight) {
      try {
        const { deaths, sources, originalLives, sourceDamage, livingBeforeChain } = prepareSpecialNightDamage(
          {
            get world() { return manager.world; },
            get config() { return manager.config; },
            get events() { return manager.events; },
            get nightFaultPlan() { return manager.nightFaultPlan; },
            assertReadable() { manager.assertDemonReadable(); },
          },
          night,
          nightDay,
          ownsWedding,
          ownsDemon,
          lifecycle,
        );
        await this.deathResolution.resolve(
          deaths,
          sources,
          actionProvider,
          Phase.Night,
          Phase.Night,
          {},
          {
            nightOriginIds: deaths,
            isCurrent: nightIsCurrent,
            originalLives,
            poisonRoutes: damagePoisonRoutes(sourceDamage!),
            execution: { night: nightUnitOf(night), phaseRevision: nightRevision },
            // 在原夜枪检查点晚读结果查询；本族闭包保同一 Map 与原体／政策顺序，不重抓 World。
            blocksPassiveNightShot: (id) => night.blocksPassiveNightShot?.(id) ?? false,
          },
        );
        this.assertDemonReadable();
        if (!nightIsCurrent()) return this.getSnapshot();
        const expirySettlement = settleRedMoonExpiry({
          get world() { return manager.world; },
          get events() { return manager.events; },
          get registry() { return manager.conditionRegistry; },
          get config() { return manager.config; },
          get checkpoint() { return manager.#rulePlan.checkpoints.nightSettled; },
        }, ownsDemon, nightDay);
        const expiryStep = expirySettlement.next();
        let beforeExpiryResult = expiryStep.done ? expiryStep.value : null;
        if (!expiryStep.done) {
          const expiryActor = expiryStep.value;
          await this.deathResolution.resolve(
            [expiryActor],
            { [expiryActor]: [DeathCause.RedMoonExpiry] },
            actionProvider,
            Phase.Night,
            Phase.Night,
            {},
            { nightOriginIds: [expiryActor], isCurrent: nightIsCurrent, execution: { night: nightUnitOf(night), phaseRevision: nightRevision } },
          );
          this.assertDemonReadable();
          if (!nightIsCurrent()) return this.getSnapshot();
          // 只有原死亡等待、可读性及当前性均成功，才恢复到期提交和事实发布；失败不补跑。
          beforeExpiryResult = expirySettlement.next().value as WinDecision | null;
        }
        const completeDeaths = [
          ...deaths,
          ...[...livingBeforeChain]
            .filter(
              ([id, scope]) =>
                !deaths.includes(id) &&
                this.world.getComponent(id, COMPONENT.Alive) === scope.life &&
                !scope.life.alive &&
                aliveLifeVersion(scope.life) === scope.version! + 1,
            )
            .map(([id]) => id),
        ];
        this.emitNightResolved(completeDeaths);
        if (beforeExpiryResult) {
          this.sealResult(
            TERMINAL_VICTORY_POLICY.replaceFactionResult(this.world, beforeExpiryResult),
            this.#rulePlan.checkpoints.nightSettled,
            this.state.phase,
          );
          return this.getSnapshot();
        }
        if (this.checkAndSealResult(this.#rulePlan.checkpoints.nightSettled))
          return this.getSnapshot();
      } finally {
        lifecycle.abortSpecialNight(night, nightDay);
      }
    }
    const firstDaySheriffBeforeNightInfo =
      !ownsWedding &&
      !ownsDemon &&
      !ownsPureWhite &&
      !ownsEvilKnight &&
      this.state.day === 1 &&
      this.config.enableSheriff === true;

    this.setPhase(Phase.Day);
    const cycleDay = this.state.day,
      dayRevision = this.phaseRevision.current;
    const dayIsCurrent = () =>
      this.state.day === cycleDay &&
      this.state.phase === Phase.Day &&
      !this.state.gameOver &&
      this.phaseRevision.current === dayRevision;
    let nightSettled = ownsWedding || ownsDemon || ownsPureWhite || ownsEvilKnight;
    if (night.mistDelay) {
      this.mistPending = prepareMistDelayedNight({
        get world() { return manager.world; },
        get cycleDay() { return cycleDay; },
        get night() { return night; },
      });
    }
    const settleMist = async (alreadyClaimed = false, interrupted = false): Promise<boolean> => {
      if (nightSettled) return this.state.gameOver;
      const settlement = settleMistDelayedNight({
        get pending() { return manager.mistPending; },
        get world() { return manager.world; },
        get events() { return manager.events; },
        get toolGateway() { return manager.toolGateway; },
        get lifecycle() { return lifecycle; },
        get cycleDay() { return cycleDay; },
      }, actionProvider, dayIsCurrent, alreadyClaimed);
      // 两个协议位置固定：第一次只有原蛇 Promise，第二次交原伤害和同一 current 闭包。
      const healed = await (settlement.next().value as Promise<number | null>);
      const { damage, current } = settlement.next(healed).value as MistPreparedNightDamage;
      this.emitNightResolved(damage.deaths);
      await this.deathResolution.resolve(
        damage.deaths,
        damage.deathSources,
        actionProvider,
        Phase.Night,
        Phase.Day,
        {},
        {
          dreams: night.dreamFrame,
          nightOriginIds: damage.deaths,
          isCurrent: current,
          poisonRoutes: damagePoisonRoutes(damage),
          execution: { night: nightUnitOf(night), phaseRevision: dayRevision },
        },
      );
      // 仅真实死亡 resolve 成功后恢复完成段；抛错不 finish／正常 close，外层仍按原路径 abort。
      settlement.next();
      nightSettled = true;
      return this.checkAndSealResult(
        interrupted
          ? this.#rulePlan.checkpoints.dayInterrupted
          : this.#rulePlan.checkpoints.nightSettled,
      );
    };
    const settleNight = async (
      blast?: { deaths: number[]; sources: DeathSources },
      animalSkip?: object,
      skippedUnit?: ExileUnit,
    ) => {
      if (nightSettled) return this.state.gameOver;
      nightSettled = true;
      let sourceDamage: DamageResolutionResult;
      let originalLives: ReadonlyMap<EntityId, DeathOriginalLife> | undefined;
      const retainedSources: DeathSources = Object.fromEntries(
        (sourceDamage = night.damage).deaths.map((id) => [
          id,
          (night.damage.deathSources[id] ?? []).filter(
            (source) =>
              source !== DeathCause.FoxInspection ||
              night.foxInspections?.some(
                (claim) => claim.target.id === id && claim.isTargetCurrent(),
              ),
          ),
        ]),
      );
      const nightDeaths = night.damage.deaths.filter((id) => {
        const scope = (originalLives = night.deathLives).get(id);
        return (
          scope &&
          retainedSources[id]?.length &&
          this.world.getComponent(id, COMPONENT.Alive) === scope.life &&
          scope.life.alive &&
          scope.version !== undefined &&
          aliveLifeVersion(scope.life) === scope.version
        );
      });
      if (!this.config.fragrantPairSeer && !this.config.animalDream)
        this.emitNightResolved(nightDeaths);
      const sources: DeathSources = Object.fromEntries(
        nightDeaths.map((id) => [id, [...(retainedSources[id] ?? [])]]),
      );
      const deaths = [...nightDeaths];
      const deathPhases: Record<EntityId, Phase> = {};
      if (blast !== undefined) {
        for (const id of blast.deaths) {
          if (!deaths.includes(id)) deaths.push(id);
          sources[id] = [...new Set([...(sources[id] ?? []), ...(blast.sources[id] ?? [])])];
          deathPhases[id] = Phase.Day;
        }
      }
      try {
        await this.deathResolution.resolve(
          deaths,
          sources,
          actionProvider,
          Phase.Night,
          Phase.Day,
          deathPhases,
          {
            dreams: night.dreamFrame,
            nightOriginIds: nightDeaths,
            isCurrent: dayIsCurrent,
            originalLives,
            poisonRoutes: damagePoisonRoutes(sourceDamage!),
            execution: { night: nightUnitOf(night), exile: skippedUnit, phaseRevision: dayRevision },
            ...(animalSkip ? { animalUnit: animalSkip } : {}),
            ...(this.config.fragrantPairSeer || this.config.animalDream
              ? {
                  onInitialWaveCommitted: (
                    actualIds: readonly number[],
                    actualSources: DeathSources | undefined,
                    receipt: DeathCommitReceipt,
                  ) => {
                    const event = this.emitNightResolved(
                      this.config.animalDream
                        ? nightDeaths.filter(
                            (id) =>
                              actualIds.includes(id) &&
                              (retainedSources[id] ?? []).some((c) =>
                                (actualSources?.[id] ?? []).includes(c),
                              ),
                          )
                        : nightDeaths,
                    );
                    // 只关联真正的公开事件；不以凭证缺项更改原 Animal／双生 pending 筛选。
                    receipt.recordPublication(event, actualIds);
                    return event;
                  },
                }
              : {}),
          },
        );
        lifecycle.finishDay(cycleDay, dayIsCurrent);
      } finally {
        lifecycle.abortInner();
      }
      if (!dayIsCurrent()) return this.state.gameOver;
      if (animalSkip) {
        completeAndPublishAnimalExileUnit({
          world: () => this.world,
          events: () => this.events,
          day: () => cycleDay,
        }, () => animalSkip!);
      }
      // 原死亡波／清理和当前性之后，串行发表熊→Animal 知识→Beauty 通知，再进入原判胜。
      publishDawnKnowledge(bearFrame, {
        world: () => this.world,
        events: () => this.events,
        animalDream: () => this.config.animalDream,
      }, cycleDay, dayIsCurrent);
      return this.checkAndSealResult(
        blast !== undefined
          ? this.#rulePlan.checkpoints.dayInterrupted
          : this.#rulePlan.checkpoints.nightSettled,
      );
    };
    if (!night.mistDelay && !firstDaySheriffBeforeNightInfo && (await settleNight()))
      return this.getSnapshot();

    const dayResult = await this.dayPipeline.execute(this.config, actionProvider, {
      day: cycleDay,
      isCurrent: dayIsCurrent,
      commitSelfDestruct: async (choice, window) => {
        if (!dayIsCurrent()) return false;
        // 尚未发表的夜间信息继续保密；已注定死亡的白狼王不能用此技能吞掉自身死亡。
        if (
          !nightSettled &&
          choice.kind === "white_wolf_king" &&
          night.damage.deaths.includes(choice.actorId)
        )
          return false;
        const blast = commitSelfDestructSelection(
          this.world,
          choice,
          window,
          Phase.Day,
          this.events,
        );
        if (!blast) return false;
        const animalSkip = this.config.animalDream
          ? beginAnimalExileUnit(this.world, cycleDay, "skipped_day", dayIsCurrent)
          : undefined;
        const skippedUnit = openExileUnit(cycleDay, "skipped_day", animalSkip);
        if (!nightSettled && this.mistPending) {
          this.mistPending.claim(dayIsCurrent);
          await this.deathResolution.resolve(
            blast.deaths,
            blast.sources,
            actionProvider,
            Phase.Day,
            Phase.Day,
            {},
            { isCurrent: dayIsCurrent, execution: { exile: skippedUnit, phaseRevision: dayRevision } },
          );
          if (dayIsCurrent()) await settleMist(true, true);
        } else if (!nightSettled) await settleNight(blast, animalSkip, skippedUnit);
        else {
          await this.deathResolution.resolve(
            blast.deaths,
            blast.sources,
            actionProvider,
            Phase.Day,
            Phase.Day,
            {},
            { isCurrent: dayIsCurrent, execution: { exile: skippedUnit, phaseRevision: dayRevision }, ...(animalSkip ? { animalUnit: animalSkip } : {}) },
          );
          if (animalSkip) {
            completeAndPublishAnimalExileUnit({
              world: () => this.world,
              events: () => this.events,
              day: () => cycleDay,
            }, () => animalSkip!);
          }
        }
        return true;
      },
      ...(firstDaySheriffBeforeNightInfo && !night.mistDelay
        ? { afterSheriffElection: () => settleNight() }
        : {}),
      commitKnightDuel: async (choice) => {
        const settlement = settleKnightDay({
          get world() { return manager.world; },
          get events() { return manager.events; },
          get isCurrent() { return dayIsCurrent; },
          get nightSettled() { return nightSettled; },
          get dayRevision() { return dayRevision; },
          checkResult() { return manager.checkAndSealResult(manager.#rulePlan.checkpoints.dayInterrupted); },
        }, choice);
        const step = settlement.next();
        if (step.done) return step.value;
        // 只交原提案／元数据引用；DR callee在原参数前读取，deaths和sources不在yield时提前消费。
        const { duel, duelMetadata } = step.value;
        await this.deathResolution.resolve(
          duel.deaths,
          duel.sources,
          actionProvider,
          Phase.Day,
          Phase.Day,
          {},
          duelMetadata,
        );
        // DR抛错不恢复生成器，不补跑日裁决或退款；当前性、封盘、endsDay按原短路顺序恢复。
        return settlement.next().value as KnightDuelCommit;
      },
    });

    if (night.mistDelay && !nightSettled && dayIsCurrent()) await settleMist();

    if (this.state.gameOver || !dayIsCurrent()) return this.getSnapshot();
    if (dayResult.interrupted) {
      // 白天被自爆中断时直接结束当日并切到下一夜。
      if (
        this.state.gameOver ||
        this.checkAndSealResult(this.#rulePlan.checkpoints.dayInterrupted)
      ) {
        return this.getSnapshot();
      }
      this.state.day += 1;
      this.setPhase(Phase.Night);
      return this.getSnapshot();
    }

    this.setPhase(Phase.Voting);
    const votingRevision = this.phaseRevision.current;
    const votingIsCurrent = () =>
      this.state.day === cycleDay &&
      this.state.phase === Phase.Voting &&
      !this.state.gameOver &&
      this.phaseRevision.current === votingRevision;
    const votingResult = await this.votingPipeline.execute(this.config, actionProvider, {
      day: cycleDay,
      isCurrent: votingIsCurrent,
      commitSelfDestruct: async (choice) => {
        if (!votingIsCurrent()) return false;
        const blast = commitSelfDestructSelection(
          this.world,
          choice,
          ActionWindow.OnPreVote,
          Phase.Voting,
          this.events,
        );
        if (!blast) return false;
        const animalSkip = this.config.animalDream
          ? beginAnimalExileUnit(this.world, cycleDay, "skipped_day", votingIsCurrent)
          : undefined;
        const skippedUnit = openExileUnit(cycleDay, "skipped_day", animalSkip);
        await this.deathResolution.resolve(
          blast.deaths,
          blast.sources,
          actionProvider,
          Phase.Voting,
          Phase.Voting,
          {},
          { isCurrent: votingIsCurrent, execution: { exile: skippedUnit, phaseRevision: votingRevision }, ...(animalSkip ? { animalUnit: animalSkip } : {}) },
        );
        if (animalSkip) {
          completeAndPublishAnimalExileUnit({
            world: () => this.world,
            events: () => this.events,
            day: () => cycleDay,
          }, () => animalSkip!);
        }
        return true;
      },
    });

    if (!votingIsCurrent()) return this.getSnapshot();
    if (votingResult.interrupted) {
      // 投票前窗口发生自爆，同样跳过当日剩余流程。
      if (this.checkAndSealResult(this.#rulePlan.checkpoints.dayInterrupted)) {
        return this.getSnapshot();
      }
      this.state.day += 1;
      this.setPhase(Phase.Night);
      return this.getSnapshot();
    }

    let beautyCandidate: BeautyExileCandidate | null = null;
    if (votingResult.animalUnit) {
      const { sources, ids } = prepareAnimalExileDeaths(votingResult);
      await this.deathResolution.resolve(
        ids,
        sources,
        actionProvider,
        Phase.Voting,
        Phase.Voting,
        {},
        { isCurrent: votingIsCurrent, animalUnit: votingResult.animalUnit, execution: { exile: exileUnitOf(votingResult), phaseRevision: votingRevision } },
      );
      if (!votingIsCurrent()) return this.getSnapshot();
      completeAndPublishAnimalExileUnit({
        world: () => this.world,
        events: () => this.events,
        day: () => cycleDay,
      }, () => votingResult.animalUnit!);
      this.previousExile = captureAnimalExileFeedback(() => this.world, votingResult, sources, cycleDay);
    } else if (votingResult.removed.length > 0) {
      // 普通放逐在死亡波前捕获末狼／目标侧；动物分支不借此特殊胜利候选。
      const { target, candidate } = prepareBeautyExileVictory(votingResult, () => this.world);
      beautyCandidate = candidate;
      this.previousExile = captureOrdinaryExileFeedback(() => this.world, votingResult, target, cycleDay);
      const sources = prepareOrdinaryExileDeaths(votingResult);
      await this.deathResolution.resolve(
        votingResult.removed,
        sources,
        actionProvider,
        Phase.Voting,
        Phase.Voting,
        {},
        { isCurrent: votingIsCurrent, execution: { exile: exileUnitOf(votingResult), phaseRevision: votingRevision } },
      );
    }
    if (!votingIsCurrent()) return this.getSnapshot();
    // await 后先保原当前性守卫，再核整侧；查询不是封盘，已提交死亡不因失败退款。
    const beautyResult = resolveBeautyExileVictory(this.world, beautyCandidate);
    if (
      this.checkAndSealResult(
        this.#rulePlan.checkpoints.exileSettled,
        beautyExileVictoryOverrides(beautyResult),
      )
    ) {
      return this.getSnapshot();
    }

    await new WallNotesWindow(this.world, this.toolGateway, this.events).execute(
      this.config,
      new GameActionRequestFactory(this.world, this.events, cycleDay),
      actionProvider,
      cycleDay,
      votingIsCurrent,
      () => this.random.fork("wall_notes"),
    );
    if (!votingIsCurrent()) return this.getSnapshot();
    this.state.day += 1;
    return this.getSnapshot();
  }

  async runUntilGameOver(
    actionProvider: ActionProvider,
    maxDays: number = 20,
  ): Promise<RuntimeSnapshot> {
    while (!this.state.gameOver) {
      await this.runSingleCycle(actionProvider, maxDays);
    }
    return this.getSnapshot();
  }

  /** 流水线、开局上下文及归档编码共享的唯一执行计划。 */
  getRulePlan(): RulePlan {
    return this.#rulePlan;
  }

  /**
   * 检查胜负并在命中时封盘写入 game_over 事件。
   */
  private checkAndSealResult(
    checkpoint: VictoryCheckpoint,
    overrides: Partial<Record<WinCondition, WinDecision>> = {},
  ): boolean {
    if (this.state.gameOver) return true;
    const result = this.conditionRegistry.evaluateMany(
      this.world,
      TERMINAL_VICTORY_POLICY.conditions({ world: () => this.world, config: () => this.config }),
      checkpoint,
      overrides,
    );
    if (!result) return false;
    this.sealResult(TERMINAL_VICTORY_POLICY.replaceFactionResult(this.world, result), checkpoint, this.state.phase);
    return true;
  }

  private sealResult(decision: WinDecision, checkpoint: VictoryCheckpoint, phase: Phase): void {
    if (this.state.gameOver) return;
    this.assertFaultPlanConsumed();
    // 先核故障计划，再由规则组合核婚约分配与原成员／时点；任何拒绝都先于本经理的终态写入。
    const { winner, outcome, decidedAt } = TERMINAL_VICTORY_POLICY.validateCandidate(
      decision,
      checkpoint,
      phase,
      () => this.world,
      () => this.state.day,
    );
    this.state.result = { winner, reason: decision.reason, outcome, decidedAt };
    this.state.gameOver = true;
    this.setPhase(Phase.GameOver);
    this.events.push({
      timestamp: Date.now(),
      type: "game_over",
      payload: structuredClone(this.state.result),
    });
  }

  /** 只检验猎魔原体／夜状态和全体药印记可读性；失败原样拒绝，不发布夜报或恢复资源。 */
  private assertDemonReadable(): void {
    if (demonHunterActorId(this.world) === null) return;
    assertDemonNightReadable(this.world);
    if (!this.world.entityIds().every((id) => demonWitchMarksSafe(this.world, id)))
      throw new Error("demon_hunter_unreadable_marks");
  }

  /** 发布原“昨夜死亡／平安夜”公开事实；名单当时取副本，广播时点仍由阶段经理决定。 */
  private emitNightResolved(deaths: EntityId[]): GameEvent {
    const event: GameEvent = {
      timestamp: Date.now(),
      type: "night_resolved",
      payload: {
        deaths: [...deaths],
      },
    };
    this.events.push(event);
    return event;
  }

  /**
   * 调试接口：返回当前终局结果。
   */
  debugResult(): GameResult | null {
    return this.state.result === null ? null : structuredClone(this.state.result);
  }

  /**
   * 切换阶段并写入 `phase_changed` 事件。
   */
  private setPhase(phase: Phase): void {
    const previous = this.state.phase;
    this.state.phase = phase;
    if (previous === phase) {
      return;
    }
    this.phaseRevision.advance();
    this.world.closeDeathActions();
    const gameOverPayload =
      phase === Phase.GameOver && this.state.result
        ? {
            winner: this.state.result.winner,
            reason: this.state.result.reason,
            outcome: structuredClone(this.state.result.outcome),
            decidedAt: { ...this.state.result.decidedAt },
          }
        : {};
    this.events.push({
      timestamp: Date.now(),
      type: "phase_changed",
      payload: {
        phase,
        day: this.state.day,
        ...gameOverPayload,
      },
    });
  }
}

/**
 * 负责按当前角色和狼队权限核对广播受众。输入为 World 与受众身份；输出为狼队／角色可见性谓词。这些谓词只裁剪信息，不赋予玩家全知状态或行动权限。
 */
/** 文件说明：封装广播可见性判定逻辑。 */
import { COMPONENT } from "../../../core/domain/components/names";
import { RoleComponent } from "../../../core/domain/components/role";
import { Camp, EntityId, Role } from "../../../core/domain/model";
import { World } from "../../../core/domain/world";
import { getDefaultRoleCatalog } from "../roles/role-catalog-assembly";

/** 广播受众身份视图。 */
export interface AudienceIdentity {
  role?: string;
  camp?: Camp | string;
}

/** 广播可见性判定注册器。 */
export class VisibilityRegistry {
  private readonly roleCatalog = getDefaultRoleCatalog();

  isWolfPlayer(world: World, actorId: EntityId): boolean {
    const roleComp = world.getComponent(actorId, COMPONENT.Role);
    return roleComp?.camp === Camp.Wolf;
  }

  isWolfAudience(identity: AudienceIdentity): boolean {
    if (identity.camp === Camp.Wolf || identity.camp === Camp.Wolf.toString()) {
      return true;
    }
    if (typeof identity.role !== "string") {
      return false;
    }
    if (!this.isRole(identity.role)) {
      return false;
    }
    return this.roleCatalog.getCamp(identity.role) === Camp.Wolf;
  }

  private isRole(role: string): role is Role {
    return (Object.values(Role) as string[]).includes(role);
  }
}

let defaultRegistry: VisibilityRegistry | null = null;

/** 获取默认广播可见性注册器实例。 */
export function getDefaultVisibilityRegistry(): VisibilityRegistry {
  if (!defaultRegistry) {
    defaultRegistry = new VisibilityRegistry();
  }
  return defaultRegistry;
}

/**
 * 根据请求、角色和已注册目标规则生成可行动编号提示。输入为当前组件状态与候选上下文，
 * 输出为本地化提示；提示不授予行动权限，实际校验与提交仍由网关和具体机制负责。
 * 狼刀候选只消费公开目标查询，不取得狼人私有状态或狼刀提交权。
 */
import { nobleBodyChoiceTargets } from "../roles/noble_secret_body/authority";
import {
  shelterTargets,
  eclipseSwallowTargets,
  isRadiantEclipseBoard,
} from "../roles/radiant_eclipse/night_frame";
import { nightmareFearTargets } from "../roles/nightmare_shadow/ports";
import { magicianChoiceTargets } from "../roles/magician/night_frame";
import { bindWolfKnifeTargetQuery } from "../roles/wolf/ports";
import { prohibitsLoversVote } from "../roles/cupid/relation";
import { seerTargetAllowed } from "../roles/seer/ports";
import { guardTargetRepeated } from "../roles/guard/ports";
import { text } from "@ai-werewolf-arena/game-text";
import { Role, ToolName } from "../../../core/domain/model";
import { TargetHintContext, TargetHintRegistry } from "./contracts";
import { canBeExiled, canBeSheriff } from "../common/participation";
import { inspectionRepeats } from "@ai-werewolf-arena/game-contract/role-inspection-policy";
import { getRoleInspectionState } from "../roles/role_inspection/ports";
import { COMPONENT } from "../../../core/domain/components/names";
import type { RoleComponent } from "../../../core/domain/components/role";
import { findNightAbility } from "../roles/abilities";
import { luckyTargetAllowed } from "../roles/night_action_history";
import { getAwakenedState } from "../roles/awakened_hidden_wolf/state";

interface TargetRule {
  /** 只决定提示是否保留自身编号；当前板子的实际目标限制仍由机制复验。 */
  allowSelf: boolean;
}

/**
 * 默认 target_id 提示注册器：
 * - 以工具规则为基线；
 * - 再按角色规则覆盖，便于角色机制独立扩展。
 */
export class DefaultTargetHintRegistry implements TargetHintRegistry {
  private readonly toolRules: Partial<Record<ToolName, TargetRule>> = {
    fox_distract: { allowSelf: true },
    bind_fragrant_pair: { allowSelf: true },
    check_pair: { allowSelf: true },
    choose_servant: { allowSelf: false },
    protect_secret_body: { allowSelf: true },
    kill_vote: { allowSelf: false },
    fear: { allowSelf: false },
    swap_targets: { allowSelf: true },
    guard: { allowSelf: false },
    check_identity: { allowSelf: false },
    inspect_role: { allowSelf: false },
    inspect_night_identity: { allowSelf: false },
    mimic_role: { allowSelf: false },
    mechanical_inspect: { allowSelf: false },
    awakened_mimic: { allowSelf: false },
    awakened_poison: { allowSelf: true },
    awakened_guard: { allowSelf: true },
    awakened_attack: { allowSelf: true },
    bestow_ability: { allowSelf: false },
    choose_exemplar: { allowSelf: false },
    mechanical_poison: { allowSelf: true },
    mechanical_guard: { allowSelf: true },
    mechanical_attack: { allowSelf: true },
    use_potion: { allowSelf: false },
    vote: { allowSelf: false },
    shoot: { allowSelf: false },
    black_market_trade: { allowSelf: false },
    self_destruct_with_target: { allowSelf: false },
    duel: { allowSelf: false },
    dream: { allowSelf: false },
    charm: { allowSelf: false },
    vote_for_sheriff: { allowSelf: false },
    choose_badge_successor: { allowSelf: false },
  };

  private readonly roleOverrides: Partial<Record<Role, Partial<Record<ToolName, TargetRule>>>> = {
    [Role.FragrantPhantom]: { kill_vote: { allowSelf: true } },
    [Role.NightNoble]: { kill_vote: { allowSelf: true } },
    [Role.Wolf]: {
      // 狼人策略中可允许自刀，提示层保留自己编号避免“无效 self target”误判。
      kill_vote: { allowSelf: true },
    },
    [Role.WolfKing]: { kill_vote: { allowSelf: true } },
    [Role.NightmareShadow]: { kill_vote: { allowSelf: true } },
    [Role.WolfWitch]: { kill_vote: { allowSelf: true } },
    [Role.WhiteWolfKing]: { kill_vote: { allowSelf: true } },
    [Role.HiddenWolf]: { kill_vote: { allowSelf: true } },
    [Role.Gargoyle]: { kill_vote: { allowSelf: true } },
    [Role.MechanicalWolf]: { kill_vote: { allowSelf: true } },
    [Role.AwakenedHiddenWolf]: { kill_vote: { allowSelf: true } },
    [Role.Witch]: {
      // 女巫可自救，提示层需包含自己。
      use_potion: { allowSelf: true },
    },
    [Role.Guard]: {
      // 守卫是否可自守由板子机制决定；提示层默认放开，避免误导模型。
      guard: { allowSelf: true },
    },
  };

  buildActionableIdsHint(ctx: TargetHintContext): string | undefined {
    if (
      ctx.allowedTools.includes("choose_servant") ||
      ctx.allowedTools.includes("protect_secret_body")
    ) {
      const ids = nobleBodyChoiceTargets(
        ctx.world,
        ctx.day ?? 1,
        ctx.allowedTools.includes("choose_servant") ? "noble" : "body",
      );
      return ids.length
        ? text(
            ctx.world.locale,
            ctx.allowedTools.includes("protect_secret_body")
              ? "prompt.targets.self"
              : "prompt.targets.others",
            { ids: ids.join(", ") },
          )
        : text(ctx.world.locale, "prompt.targets.none");
    }
    if (ctx.allowedTools.includes("cast_shelter") || ctx.allowedTools.includes("swallow_skill")) {
      const ids = ctx.allowedTools.includes("cast_shelter")
        ? shelterTargets(ctx.world, ctx.day ?? 1, ctx.actorId, ctx.abilityId!)
        : eclipseSwallowTargets(ctx.world, ctx.day ?? 1);
      return ids.length
        ? text(ctx.world.locale, "prompt.targets.others", { ids: ids.join(", ") })
        : text(ctx.world.locale, "prompt.targets.none");
    }
    if (ctx.allowedTools.includes("modify_skill") || ctx.allowedTools.includes("bonus_action")) {
      const candidates = ctx.allowedTools.includes("modify_skill")
        ? ctx.modifierCandidates
        : ctx.modifierBonusCandidates;
      if (candidates === undefined) throw new Error("scholar_mentor_candidates_missing");
      const alive = new Set(ctx.world.getAliveEntityIds()),
        ids = [...new Set(candidates)].filter((id) => alive.has(id)).sort((a, b) => a - b);
      return ids.length
        ? text(
            ctx.world.locale,
            ids.includes(ctx.actorId) ? "prompt.targets.self" : "prompt.targets.others",
            { ids: ids.join(", ") },
          )
        : text(ctx.world.locale, "prompt.targets.none");
    }
    if (ctx.allowedTools.includes("challenge") && ctx.debateTargetId !== undefined)
      return text(ctx.world.locale, "prompt.targets.debate", { target: ctx.debateTargetId });
    if (ctx.allowedTools.includes("choose_lovers"))
      return text(ctx.world.locale, "prompt.targets.lovers", {
        ids: ctx.world.getAliveEntityIds().join(", "),
      });
    const targetTools = ctx.allowedTools.filter((tool) => this.getRule(ctx.actorRole, tool));
    if (targetTools.length === 0) {
      return undefined;
    }
    const radiantSelf =
      isRadiantEclipseBoard(ctx.world) &&
      (ctx.allowedTools.includes("use_potion") ||
        ctx.allowedTools.includes("check_identity") ||
        ctx.allowedTools.includes("kill_vote"));
    const allowSelf =
      radiantSelf || targetTools.some((tool) => this.getRule(ctx.actorRole, tool)?.allowSelf);
    const inspection = getRoleInspectionState(
      ctx.world.getComponent(ctx.actorId, COMPONENT.Role)!,
      ctx.abilityId,
    );
    const ownRole = ctx.world.getComponent(ctx.actorId, COMPONENT.Role);
    const awakenedGuard = getAwakenedState(ownRole)?.learned?.skill;
    const luckyAllowed = (tool: ToolName, id: number) => {
      const kind =
        tool === "check_identity"
          ? "seer_check"
          : tool === "guard"
            ? "guard"
            : tool === "use_potion"
              ? "potion"
              : null;
      if (!kind) return true;
      const ability = findNightAbility(ownRole, kind, ctx.abilityId);
      if (!ability) return true;
      // 普通女巫仍可救这个目标，即使其毒药目标因该行动者的历史记录而被限制。
      if (
        ability.kind === "potion" &&
        ability.activation !== "lucky" &&
        ability.activation !== "black_market" &&
        ability.state.heal > 0
      )
        return true;
      if (ability.kind === "seer_check" && !seerTargetAllowed(ability.state, ctx.actorId, id))
        return false;
      if (ability.kind === "guard" && guardTargetRepeated(ability, ctx.day ?? 1, id)) return false;
      return luckyTargetAllowed(
        ctx.world,
        ctx.actorId,
        ability,
        ctx.day ?? 1,
        kind === "seer_check" ? "check" : kind === "guard" ? "guard" : "poison",
        id,
      );
    };
    const ids = ctx.world
      .getAliveEntityIds()
      .filter((id) =>
        targetTools.some(
          (tool) =>
            (radiantSelf || this.getRule(ctx.actorRole, tool)?.allowSelf || id !== ctx.actorId) &&
            luckyAllowed(tool, id) &&
            (tool !== "fear" ||
              nightmareFearTargets(ctx.world, ctx.actorId, ctx.day ?? 1).includes(id)) &&
            (tool !== "swap_targets" ||
              magicianChoiceTargets(ctx.world, ctx.day ?? 1).includes(id)) &&
            (tool !== "kill_vote" || bindWolfKnifeTargetQuery(ctx.world).allows(id)) &&
            (tool !== "inspect_night_identity" ||
              ctx.actorRole !== Role.WolfWitch ||
              ctx.world.getComponent(id, COMPONENT.Role)?.camp !== "wolf") &&
            (tool !== "awakened_guard" ||
              awakenedGuard?.kind !== "guard" ||
              awakenedGuard.lastGuardDay !== (ctx.day ?? 1) - 1 ||
              awakenedGuard.lastTarget !== id) &&
            (tool !== "vote" ||
              ((ctx.exileCandidates === undefined || ctx.exileCandidates.includes(id)) &&
                canBeExiled(ctx.world, id, ctx.roleCatalog) &&
                !prohibitsLoversVote(ctx.world, ctx.actorId, id))) &&
            (tool !== "inspect_role" ||
              !inspection ||
              inspectionRepeats(inspection) ||
              !inspection.history.some((report) => report.targetId === id)) &&
            (tool !== "choose_badge_successor" ||
              (ctx.badgeCandidates?.includes(id) &&
                canBeSheriff(ctx.world, id, ctx.roleCatalog))) &&
            (tool !== "vote_for_sheriff" ||
              (ctx.sheriffCandidates?.includes(id) &&
                canBeSheriff(ctx.world, id, ctx.roleCatalog))),
        ),
      )
      .sort((a, b) => a - b);
    const potion = findNightAbility(ownRole, "potion", ctx.abilityId);
    if (
      targetTools.length === 1 &&
      targetTools[0] === "use_potion" &&
      potion?.activation === "lucky"
    ) {
      return text(ctx.world.locale, "prompt.targets.lucky_poison", {
        ids: ids.join(", ") || text(ctx.world.locale, "common.none"),
        actor: ctx.actorId,
      });
    }
    if (ids.length === 0) {
      return text(ctx.world.locale, "prompt.targets.none");
    }
    if (allowSelf) {
      return text(ctx.world.locale, "prompt.targets.self", { ids: ids.join(", ") });
    }
    return text(ctx.world.locale, "prompt.targets.others", { ids: ids.join(", ") });
  }

  private getRule(role: Role | undefined, tool: ToolName): TargetRule | undefined {
    const roleRule = role !== undefined ? this.roleOverrides[role]?.[tool] : undefined;
    return roleRule ?? this.toolRules[tool];
  }
}

let defaultTargetHintRegistry: TargetHintRegistry | null = null;

/** 获取默认 target_id 提示注册器。 */
export function getDefaultTargetHintRegistry(): TargetHintRegistry {
  if (!defaultTargetHintRegistry) {
    defaultTargetHintRegistry = new DefaultTargetHintRegistry();
  }
  return defaultTargetHintRegistry;
}

/**
 * 捕获原角色、生命、状态、来源及政策身份的夜能力 owner。输入为已选择实例与阶段当前性
 * 回调；输出为原体当前性和行动资格检查。替换原槽或政策仍撤销 scope，不写状态或付款。
 * isOwnerCurrent 保原已付效果复验，不因运行授权墓碑失效；仅 isEligible 在原复验后拒绝退休演员。
 * 查验政策身份字节由该状态族的唯一 codec 在原表达式位置生成，生命、id、来源及允许
 * 首次死亡的版本判断仍只在此 owner，不因 payload 合法而重新授权。
 */
import type { NightAbilityKind } from "@ai-werewolf-arena/game-contract";

import { captureRadiantTurn } from "./radiant_eclipse/night_frame";
import { isRoleExecutionRetired } from "../../../core/domain/role-execution-authority";
import { COMPONENT } from "../../../core/domain/components/names";

import { captureNightLife, livingNightLife } from "../../../core/domain/night_effects";
import type { World } from "../../../core/domain/world";
import type { EntityId } from "../../../core/domain/model";
import { activeNightAbility, type NightAbilityReadView } from "./abilities";
import { aliveLifeVersion } from "../../../core/domain/components/alive";

import { DREAMER_STATE_SLOT } from "./dreamer/ports";
import { SHELTER_STATE_SLOT } from "./radiant_eclipse/shelter-state-slot";
import { SEER_STATE_SLOT } from "./seer/ports";
import { GUARD_STATE_SLOT } from "./guard/ports";
import { WITCH_STATE_SLOT } from "./witch/ports";
import { ROLE_INSPECTION_STATE_SLOT } from "./role_inspection/ports";

/** 即使库存对象仍同一引用，政策编辑也会改变授权身份。 */
function policyIdentity(ability: NightAbilityReadView): string {
  switch (ability.kind) {
    case "pair_check":
      return JSON.stringify([ability.state.policy]);
    case "shelter":
      return SHELTER_STATE_SLOT.invalidations.policyIdentity(ability);
    case "seer_check":
      return SEER_STATE_SLOT.invalidations.policyIdentity(ability);
    case "potion":
      return WITCH_STATE_SLOT.invalidations.policyIdentity(ability);
    case "guard":
      return GUARD_STATE_SLOT.invalidations.policyIdentity(ability);
    case "role_check":
      return ROLE_INSPECTION_STATE_SLOT.checkpoint.policyIdentity(ability);
    case "dream":
      return DREAMER_STATE_SLOT.invalidations.policyIdentity(ability);
  }
}

/** 请求动作前先捕获；只读资格仍在实际提交时重检，不因捕获而冻结演员。 */
export function captureNightAbilityScope<K extends NightAbilityKind>(
  world: World,
  actorId: EntityId,
  ability: NightAbilityReadView<K>,
  day: number,
  phaseCurrent: () => boolean,
) {
  const role = world.getComponent(actorId, COMPONENT.Role),
    life = captureNightLife(world, actorId);
  if (!role || !life) return null;
  const radiantCurrent = captureRadiantTurn(world, actorId, ability, day);
  const roleKind = role.role,
    camp = role.camp,
    privateState = role.privateState;
  const state = ability.state,
    kind = ability.kind,
    activation = ability.activation,
    id = ability.id;
  const source = ability.source,
    sourceKind = source.kind,
    sourceOwner = source.kind === "native" ? source.role : source.actorId,
    sourceId = source.kind === "copy" || source.kind === "transfer" ? source.abilityId : undefined;
  const policy = policyIdentity(ability);
  const starts = ability.startsOnDay,
    expires = ability.expiresAfterDay,
    maxUses = ability.maxUses,
    disclosed = ability.sourceDisclosed;
  const ownerCurrent = (allowFirstDeath = false) =>
    phaseCurrent() &&
    world.getComponent(actorId, COMPONENT.Role) === role &&
    role.role === roleKind &&
    role.camp === camp &&
    role.privateState === privateState &&
    (livingNightLife(world, life) ||
      (allowFirstDeath &&
        world.getComponent(actorId, COMPONENT.Alive) === life.life &&
        !life.life.alive &&
        aliveLifeVersion(life.life) === life.version + 1)) &&
    ability.id === id &&
    ability.kind === kind &&
    ability.activation === activation &&
    ability.state === state &&
    policyIdentity(ability) === policy &&
    (
      (role.privateState as { readonly abilities?: unknown }).abilities as
        Readonly<Record<string, NightAbilityReadView>> | undefined
    )?.[id] === ability &&
    ability.source === source &&
    source.kind === sourceKind &&
    (source.kind === "native" ? source.role : source.actorId) === sourceOwner &&
    (source.kind === "copy" || source.kind === "transfer" ? source.abilityId : undefined) ===
      sourceId &&
    ability.startsOnDay === starts &&
    ability.expiresAfterDay === expires &&
    ability.maxUses === maxUses &&
    ability.sourceDisclosed === disclosed;
  return {
    role,
    life,
    state,
    isOwnerCurrent: ownerCurrent,
    isEligible: () =>
      radiantCurrent() &&
      ownerCurrent() &&
      // 原体仍可能服务已付效果；墓碑只阻止新的行动资格，不改 ownerCurrent 或资源数据。
      !isRoleExecutionRetired(role) &&
      activeNightAbility(role, kind, day, id) === ability,
  };
}

/**
 * 负责觉醒隐狼原激活学习枪贡献的装配。输入为原死亡波与晚查询；输出为含激活元数据复验的原枪击提案。
 * 捕获表每次 hook 独立创建；资源 owner 核原 state／learning／gun，不复制库存或复活已消费枪。
 * 查询函数在原 callee 点取得并裸调用；此装配不授许可、不标死或切换阶段，付款／失败由完整结算处理。
 * 在原有序死亡钩子时点只装配原读写贡献；许可与生命仍由结算复验，失败不补偿已付款库存。
 */
import { Role, permitsDeathShot } from "../../../../core/domain/model";
import type { DeathHook } from "../../hooks/hook_registry";
import { resolveNativeDeathShots } from "../native-death-shot-settlement";
import { getAwakenedState } from "./state";
import { createAwakenedGunReader } from "../native-death-gun-resources";

export const awakenedDeathHook: DeathHook = (world, ids, sources, choose, events, context) => {
  const readGun = createAwakenedGunReader({ get getAwakenedState() { return getAwakenedState; } });
  return resolveNativeDeathShots(
    world,
    ids,
    sources,
    choose,
    events,
    {
      role: Role.AwakenedHiddenWolf,
      state: readGun,
      permits: permitsDeathShot,
      shotEvent: (actorId, targetId) => ({
        timestamp: Date.now(),
        type: "player_shot",
        payload: { actorId, targetId },
      }),
    },
    context,
  );
};

/**
 * Checks and records Awakened Hidden Wolf knife inheritance from the actual surviving wolf
 * roster. Inputs are the World, night/day and original role state; outputs are eligibility or
 * the existing inheritance fact. No provisional death proposal grants the knife, and role/camp
 * identity is not rewritten.
 */
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Camp, Role, type GameEvent } from "../../../../core/domain/model";
import type { World } from "../../../../core/domain/world";
import { currentAwakenedNight } from "./night_scope";
import { awakenedKnifeReady, getAwakenedState, recordAwakenedInheritance } from "./state";

export function canAwakenedKnife(role: RoleComponent, world?: World): boolean {
  const state = getAwakenedState(role),
    night = world && currentAwakenedNight(world, role);
  if (
    !world ||
    role.role !== Role.AwakenedHiddenWolf ||
    role.camp !== Camp.Wolf ||
    !state ||
    night == null ||
    !awakenedKnifeReady(state, night)
  )
    return false;
  const wolves = world
    .getAliveEntityIds()
    .filter((id) => world.getComponent(id, COMPONENT.Role)?.camp === Camp.Wolf);
  return wolves.length === 1 && world.getComponent(wolves[0]!, COMPONENT.Role) === role;
}
/** Only assembly and completed actual death proposals create persistent inheritance. */
export function refreshAwakenedInheritance(world: World, day: number, events: GameEvent[]): void {
  const wolves = world
    .getAliveEntityIds()
    .filter((id) => world.getComponent(id, COMPONENT.Role)?.camp === Camp.Wolf);
  if (wolves.length !== 1) return;
  const actorId = wolves[0]!,
    role = world.getComponent(actorId, COMPONENT.Role)!,
    state = getAwakenedState(role);
  if (role.role !== Role.AwakenedHiddenWolf || !state || !recordAwakenedInheritance(state, day))
    return;
  events.push({
    timestamp: Date.now(),
    type: "awakened_inherited",
    payload: { actorId, day, firstKnifeNight: state.firstKnifeNight! },
  });
}

/**
 * Captures Awakened Hidden Wolf owner, mimic skill and mirror scopes for one real night. Inputs
 * are the original ability and role/life references; outputs are currentness checks and
 * night-commit bookkeeping. It never lets a new state, source or body inherit the old captured
 * permission.
 */
import type {
  AwakenedReadState as AwakenedState,
  AwakenedReadActiveSkill as AwakenedActiveSkill,
} from "@ai-werewolf-arena/game-contract";

import { aliveLifeVersion } from "../../../../core/domain/components/alive";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Camp, Role, type EntityId } from "../../../../core/domain/model";
import {
  captureNightLife,
  livingNightLife,
  type NightLifeScope,
} from "../../../../core/domain/night_effects";
import type { World } from "../../../../core/domain/world";
import { awakenedSkillForNight, getAwakenedState } from "./state";
import { findNightAbility, type NightAbilityReadView } from "../abilities";

export interface AwakenedOwnerScope {
  readonly world: World;
  readonly actorId: EntityId;
  readonly role: RoleComponent;
  readonly state: AwakenedState;
  readonly life: NightLifeScope;
  isCurrent(allowFirstDeath?: boolean): boolean;
}
export function captureAwakenedOwner(
  world: World,
  actorId: EntityId,
  phaseCurrent: () => boolean,
): AwakenedOwnerScope | null {
  const role = world.getComponent(actorId, COMPONENT.Role),
    state = getAwakenedState(role),
    life = captureNightLife(world, actorId);
  if (
    !phaseCurrent() ||
    !role ||
    role.role !== Role.AwakenedHiddenWolf ||
    role.camp !== Camp.Wolf ||
    !state ||
    !life
  )
    return null;
  const privateState = role.privateState;
  return {
    world,
    actorId,
    role,
    state,
    life,
    isCurrent: (allowFirstDeath = false) => {
      const original =
        world.getComponent(actorId, COMPONENT.Alive) === life.life &&
        aliveLifeVersion(life.life) ===
          life.version + (allowFirstDeath && !life.life.alive ? 1 : 0);
      return (
        phaseCurrent() &&
        world.getComponent(actorId, COMPONENT.Role) === role &&
        role.role === Role.AwakenedHiddenWolf &&
        role.camp === Camp.Wolf &&
        role.privateState === privateState &&
        getAwakenedState(role) === state &&
        original &&
        (allowFirstDeath || life.life.alive)
      );
    },
  };
}
/** Bind paid facts without reading a closed slot or spent bottle/knife. */
export function bindAwakenedSkill(
  owner: AwakenedOwnerScope,
  day: number,
): { readonly skill: AwakenedActiveSkill; isCurrent(allowFirstDeath?: boolean): boolean } | null {
  const learned = owner.state.learned,
    skill = awakenedSkillForNight(owner.state, day);
  if (
    !owner.isCurrent() ||
    !learned ||
    !skill ||
    learned.activationNight === null ||
    learned.activeFromNight === null
  )
    return null;
  const { targetId, role, day: learnedDay, activationNight, activeFromNight } = learned,
    kind = skill.kind;
  return {
    skill,
    isCurrent: (allowFirstDeath = false) =>
      owner.isCurrent(allowFirstDeath) &&
      owner.state.learned === learned &&
      learned.skill === skill &&
      skill.kind === kind &&
      learned.targetId === targetId &&
      learned.role === role &&
      learned.day === learnedDay &&
      learned.activationNight === activationNight &&
      learned.activeFromNight === activeFromNight,
  };
}
/** Only the Aw-owned native Mirror depends on its learning; independent gifts/copies do not. */
export function captureAwakenedMirrorScope(
  world: World,
  actorId: EntityId,
  ability: NightAbilityReadView<"role_check">,
  day: number,
  phaseCurrent: () => boolean,
): (() => boolean) | null {
  const owner = captureAwakenedOwner(world, actorId, phaseCurrent),
    learned = owner?.state.learned,
    skill = learned?.skill;
  if (
    !owner ||
    currentAwakenedNight(world, owner.role) !== day ||
    !learned ||
    learned.role !== Role.MirrorGirl ||
    learned.activationNight === null ||
    learned.activeFromNight === null ||
    day < learned.activeFromNight ||
    skill?.kind !== "inspection" ||
    skill.abilityId !== ability.id
  )
    return null;
  const { targetId, role, day: learnedDay, activationNight, activeFromNight } = learned,
    abilityId = skill.abilityId;
  return () =>
    owner.isCurrent() &&
    currentAwakenedNight(world, owner.role) === day &&
    owner.state.learned === learned &&
    learned.skill === skill &&
    skill.kind === "inspection" &&
    skill.abilityId === abilityId &&
    learned.targetId === targetId &&
    learned.role === role &&
    learned.day === learnedDay &&
    learned.activationNight === activationNight &&
    learned.activeFromNight === activeFromNight &&
    findNightAbility(owner.role, "role_check", abilityId) === ability;
}
const nights = new WeakMap<
  World,
  { day: number; owners: Map<RoleComponent, AwakenedOwnerScope> }
>();
const committed = new WeakMap<World, Set<number>>();
export function beginAwakenedNight(
  world: World,
  day: number,
  owners: readonly AwakenedOwnerScope[],
): void {
  if (hasAwakenedNightCommit(world, day)) throw new Error("awakened_night_reentry_after_commit");
  if (nights.get(world)?.day === day) throw new Error("awakened_night_reentry_after_commit");
  if ((nights.get(world)?.day ?? day) > day) throw new Error("awakened_night_clock_regressed");
  const currentOwners = owners.filter((owner) => owner.world === world && owner.isCurrent());
  nights.set(world, { day, owners: new Map(currentOwners.map((owner) => [owner.role, owner])) });
  // Establishing this night's original-body authority is itself a committed prefix,
  // including nights with only an inherited base knife or no copied active skill.
  if (currentOwners.length) recordAwakenedNightCommit(world, day);
}
export function currentAwakenedNight(world: World, role: RoleComponent): number | null {
  const night = nights.get(world),
    owner = night?.owners.get(role);
  return night && owner?.isCurrent() && livingNightLife(world, owner.life) ? night.day : null;
}
export function recordAwakenedNightCommit(world: World, day: number): void {
  const days = committed.get(world) ?? new Set<number>();
  days.add(day);
  committed.set(world, days);
}
export function hasAwakenedNightCommit(world: World, day: number): boolean {
  return committed.get(world)?.has(day) ?? false;
}

/**
 * 负责觉醒隐狼开夜、学习、技能、额外刀和激活阶段。
 * 输入为原 native/copy scope 与已验证工具；输出为原已付事实及有来源的盾、刀和原毒 intent。
 * 复用原捕获 life/day/目标，保留付款位置以及允许首次死亡的 paid callback。
 * 不以新来源数据替代资格、库存或重试规则，不恢复撤销的原 owner，不改变阶段优先级或归档。
 */
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Phase, StatusMark, type EntityId, type ToolName } from "../../../../core/domain/model";
import {
  captureNightLife,
  livingNightLife,
  awakenedNightIntent,
  originalPoisonIntent,
} from "../../../../core/domain/night_effects";
import type { NightStageContext, NightStageHandler } from "../../stages/night/contracts";
import { allNightAbilities, findNightAbility, retiredNightAbilityIds } from "../abilities";
import { installNativeAbility } from "../ability_changes";
import { setNightAbilityStartDay } from "../abilities";
import { canAwakenedKnife } from "./inheritance";
import {
  beginAwakenedNight,
  bindAwakenedSkill,
  captureAwakenedOwner,
  currentAwakenedNight,
  recordAwakenedNightCommit,
} from "./night_scope";
import {
  activateAwakenedLearning,
  awakenedSkillForNight,
  canAwakenedExtraKnife,
  canAwakenedMimic,
  chooseAwakenedAttack,
  chooseAwakenedGuard,
  closeAwakenedMimic,
  learnAwakenedRole,
  skipAwakenedSkill,
  useAwakenedPoison,
} from "./state";

function owners(ctx: NightStageContext, day: number, opening = false) {
  return ctx.world.getAliveEntityIds().flatMap((id) => {
    const owner = captureAwakenedOwner(
      ctx.world,
      id,
      () => ctx.isCurrent() && ctx.currentDay() === day,
    );
    return owner && (opening || currentAwakenedNight(ctx.world, owner.role) === day) ? [owner] : [];
  });
}
const targets = (ctx: NightStageContext, actorId: EntityId, excludeSelf: boolean) =>
  new Map(
    ctx.world
      .getAliveEntityIds()
      .filter((id) => !excludeSelf || id !== actorId)
      .map((id) => [id, captureNightLife(ctx.world, id)!] as const),
  );
const effects = (ctx: NightStageContext) =>
  (ctx.state.awakenedEffects ??= { shields: [], attacks: [] });
const retry = (attempt: number) => (attempt ? { retry_attempt: attempt, retry_max: 2 } : {});

const openingStage: NightStageHandler = {
  id: "awakened_opening",
  priority: 250,
  async execute(ctx) {
    const day = ctx.currentDay();
    beginAwakenedNight(ctx.world, day, owners(ctx, day, true));
  },
};
const mimicStage: NightStageHandler = {
  id: "awakened_mimic",
  priority: 580,
  async execute(ctx) {
    const day = ctx.currentDay();
    for (const owner of owners(ctx, day)) {
      if (!canAwakenedMimic(owner.state, day)) continue;
      let completed = false;
      for (let attempt = 0; attempt < 3; attempt++) {
        if (!owner.isCurrent() || !canAwakenedMimic(owner.state, day)) break;
        const candidates = targets(ctx, owner.actorId, true);
        const roles = new Map(
          [...candidates.keys()].map((id) => {
            const component = ctx.world.getComponent(id, COMPONENT.Role)!;
            return [id, { component, role: component.role, camp: component.camp }] as const;
          }),
        );
        const action = candidates.size
          ? await ctx.actionProvider.getAction(
              ctx.makeRequest(owner.actorId, ["awakened_mimic"], {
                stage: "awakened_mimic",
                requiresAction: false,
                action_failure_policy: "error",
                allow_fallback: false,
                ...retry(attempt),
              }),
            )
          : null;
        if (!owner.isCurrent() || !canAwakenedMimic(owner.state, day)) break;
        if (action === null) {
          closeAwakenedMimic(owner.state, day);
          recordAwakenedNightCommit(ctx.world, day);
          ctx.events.push({
            timestamp: Date.now(),
            type: "awakened_mimic_skipped",
            payload: { actorId: owner.actorId, day },
          });
          completed = true;
          break;
        }
        if (action.name !== "awakened_mimic") continue;
        const valid = ctx.toolGateway.validateAndSanitize(ctx.world, owner.actorId, action, {
          phase: Phase.Night,
          day,
        });
        if (
          !owner.isCurrent() ||
          !canAwakenedMimic(owner.state, day) ||
          !valid.ok ||
          valid.sanitizedCall?.name !== "awakened_mimic"
        )
          continue;
        const targetId = valid.sanitizedCall.args.target_id,
          target = candidates.get(targetId),
          origin = roles.get(targetId);
        if (
          !target ||
          !livingNightLife(ctx.world, target) ||
          !origin ||
          ctx.world.getComponent(targetId, COMPONENT.Role) !== origin.component ||
          origin.component.role !== origin.role ||
          origin.component.camp !== origin.camp
        )
          continue;
        if (!learnAwakenedRole(owner.state, targetId, origin.role, day)) continue;
        recordAwakenedNightCommit(ctx.world, day);
        ctx.events.push({
          timestamp: Date.now(),
          type: "awakened_mimicked",
          payload: { actorId: owner.actorId, day, targetId, role: owner.state.learned!.role },
        });
        completed = true;
        break;
      }
      if (!completed && owner.isCurrent() && canAwakenedMimic(owner.state, day)) {
        if (targets(ctx, owner.actorId, true).size)
          throw new Error("awakened_mimic_valid_action_missing");
        closeAwakenedMimic(owner.state, day);
        recordAwakenedNightCommit(ctx.world, day);
        ctx.events.push({
          timestamp: Date.now(),
          type: "awakened_mimic_skipped",
          payload: { actorId: owner.actorId, day },
        });
      }
    }
  },
};

const skillStage: NightStageHandler = {
  id: "awakened_skill",
  priority: 650,
  async execute(ctx) {
    const day = ctx.currentDay();
    for (const owner of owners(ctx, day)) {
      const bound = bindAwakenedSkill(owner, day),
        skill = bound?.skill;
      if (!bound || !skill || skill.kind === "wolf") continue;
      const tool: ToolName = skill.kind === "poison" ? "awakened_poison" : "awakened_guard";
      const current = () => bound.isCurrent() && awakenedSkillForNight(owner.state, day) === skill;
      let completed = false;
      for (let attempt = 0; attempt < 3; attempt++) {
        if (!current()) break;
        const candidates = targets(ctx, owner.actorId, false);
        const action = await ctx.actionProvider.getAction(
          ctx.makeRequest(owner.actorId, [tool], {
            stage: "awakened_skill",
            requiresAction: false,
            action_failure_policy: "error",
            allow_fallback: false,
            ...retry(attempt),
          }),
        );
        if (!current()) break;
        if (action === null) {
          if (!skipAwakenedSkill(owner.state, day)) break;
          recordAwakenedNightCommit(ctx.world, day);
          ctx.events.push({
            timestamp: Date.now(),
            type: "awakened_skill_skipped",
            payload: { actorId: owner.actorId, day },
          });
          completed = true;
          break;
        }
        if (action.name !== tool) continue;
        const valid = ctx.toolGateway.validateAndSanitize(ctx.world, owner.actorId, action, {
          phase: Phase.Night,
          day,
        });
        if (!current() || !valid.ok || !valid.sanitizedCall) continue;
        const call = valid.sanitizedCall;
        if (call.name !== "awakened_poison" && call.name !== "awakened_guard") continue;
        const targetId = call.args.target_id,
          target = targetId === null ? null : candidates.get(targetId);
        if (targetId !== null && (!target || !livingNightLife(ctx.world, target))) continue;
        if (call.name === "awakened_poison" && skill.kind === "poison" && target) {
          if (!useAwakenedPoison(owner.state, day)) break;
          (ctx.state.poisonClaims ??= []).push(
            originalPoisonIntent(
              {
                source: owner.life,
                target,
                isCurrent: () => bound.isCurrent(true),
              },
              {
                family: "awakened",
                day,
                stage: "awakened_skill",
                actorLife: owner.life,
                requestedTargetId: targetId,
                abilityId: "learned:awakened",
              },
            ),
          );
          ctx.ensureMarks(target.id).add(StatusMark.PoisonMark);
          ctx.events.push({
            timestamp: Date.now(),
            type: "awakened_poison_used",
            payload: { actorId: owner.actorId, day, targetId: target.id },
          });
        } else if (call.name === "awakened_guard" && skill.kind === "guard") {
          if (!chooseAwakenedGuard(owner.state, targetId, day)) continue;
          if (target)
            effects(ctx).shields.push(
              awakenedNightIntent(
                "awakened-shield",
                {
                  actorId: owner.actorId,
                  target,
                  isCurrent: () => bound.isCurrent(true),
                },
                {
                  family: "awakened",
                  day,
                  stage: "awakened_skill",
                  actorLife: owner.life,
                  requestedTargetId: targetId,
                  abilityId: "learned:awakened",
                },
              ),
            );
          ctx.events.push({
            timestamp: Date.now(),
            type: "awakened_guard_chosen",
            payload: { actorId: owner.actorId, day, targetId },
          });
        } else continue;
        recordAwakenedNightCommit(ctx.world, day);
        completed = true;
        break;
      }
      if (!completed && current()) throw new Error("awakened_skill_valid_action_missing");
    }
  },
};

const attackStage: NightStageHandler = {
  id: "awakened_attack",
  priority: 660,
  async execute(ctx) {
    const day = ctx.currentDay();
    for (const owner of owners(ctx, day)) {
      const bound = bindAwakenedSkill(owner, day);
      if (bound?.skill.kind !== "wolf") continue;
      const effectCurrent = () => bound.isCurrent() && canAwakenedKnife(owner.role, ctx.world);
      const current = () => effectCurrent() && canAwakenedExtraKnife(owner.state, day);
      if (!current()) continue;
      let completed = false;
      for (let attempt = 0; attempt < 3; attempt++) {
        if (!current()) break;
        const candidates = targets(ctx, owner.actorId, false);
        const action = await ctx.actionProvider.getAction(
          ctx.makeRequest(owner.actorId, ["awakened_attack"], {
            stage: "awakened_attack",
            requiresAction: false,
            action_failure_policy: "error",
            allow_fallback: false,
            ...retry(attempt),
          }),
        );
        if (!current()) break;
        let targetId: number | null = null;
        if (action !== null) {
          if (action.name !== "awakened_attack") continue;
          const valid = ctx.toolGateway.validateAndSanitize(ctx.world, owner.actorId, action, {
            phase: Phase.Night,
            day,
          });
          if (!current() || !valid.ok || valid.sanitizedCall?.name !== "awakened_attack") continue;
          targetId = valid.sanitizedCall.args.target_id;
        }
        const target = targetId === null ? null : candidates.get(targetId);
        if (targetId !== null && (!target || !livingNightLife(ctx.world, target))) continue;
        if (!chooseAwakenedAttack(owner.state, targetId, day)) break;
        if (target)
          effects(ctx).attacks.push(
            awakenedNightIntent(
              "awakened-attack",
              { actorId: owner.actorId, target, isCurrent: effectCurrent },
              {
                family: "awakened",
                day,
                stage: "awakened_attack",
                actorLife: owner.life,
                requestedTargetId: targetId,
                abilityId: "learned:awakened",
              },
            ),
          );
        recordAwakenedNightCommit(ctx.world, day);
        ctx.events.push({
          timestamp: Date.now(),
          type: "awakened_attack_chosen",
          payload: { actorId: owner.actorId, day, targetId },
        });
        completed = true;
        break;
      }
      if (!completed && current()) throw new Error("awakened_attack_valid_action_missing");
    }
  },
};

const activationStage: NightStageHandler = {
  id: "awakened_activation",
  priority: 900,
  async execute(ctx) {
    const day = ctx.currentDay();
    for (const owner of owners(ctx, day)) {
      const learned = owner.state.learned;
      if (!learned || learned.activationNight !== null || !owner.isCurrent()) continue;
      let abilityId: string | undefined;
      if (learned.skill.kind === "inspection") {
        if (
          allNightAbilities(owner.role).some(
            (ability) => ability.kind === "role_check" && ability.source.kind === "native",
          ) ||
          retiredNightAbilityIds(owner.role).some((id) => id.startsWith("native:role_check"))
        )
          throw new Error("awakened_mirror_native_binding_conflict");
        installNativeAbility(owner.role, "role_check", {
          policy: "mirror",
          lastTarget: null,
          lastDay: null,
          history: [],
        });
        const ability = findNightAbility(owner.role, "role_check")!;
        setNightAbilityStartDay(ability, day + 1);
        abilityId = ability.id;
      }
      if (
        !owner.isCurrent() ||
        owner.state.learned !== learned ||
        !activateAwakenedLearning(owner.state, day, abilityId)
      )
        throw new Error("awakened_activation_commit_invalid");
      recordAwakenedNightCommit(ctx.world, day);
      ctx.events.push({
        timestamp: Date.now(),
        type: "awakened_ready",
        payload: {
          actorId: owner.actorId,
          activationNight: day,
          activeFromNight: day + 1,
          role: learned.role,
        },
      });
    }
  },
};

export const AWAKENED_NIGHT_STAGES = [
  openingStage,
  mimicStage,
  skillStage,
  attackStage,
  activationStage,
];

/**
 * 负责 觉醒隐狼 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
