  runtime: {
    ...ORDINARY_WOLF_CONTRIBUTIONS.runtime,
    canSelfDestruct: false,
    init: (role) => {
      if (!getAwakenedState(role)) setAwakenedState(role, freshAwakenedState());
    },
    wolfTeam: (role, world) => ({
      recognizedByPack: false,
      recognizes: "none",
      canChat: false,
      canVoteForKill: canAwakenedKnife(role, world),
    }),
    inspectionLabels: (role) => ({
      camp: Camp.Wolf,
      role: getAwakenedState(role)?.learned?.role ?? Role.AwakenedHiddenWolf,
    }),
    configuration: {
      schema: z.strictObject({}),
      defaults: {},
      apply: (config) => config,
      serialize: () => ({}),
    },
    possibleNightAbilities: ["role_check"],
    toolSpecs: [
      ...ORDINARY_WOLF_CONTRIBUTIONS.runtime.toolSpecs!.filter((spec) => spec.name === "kill_vote"),
      ...AWAKENED_TOOL_SPECS,
      ROLE_INSPECTION_TOOL,
      ...DEATH_SHOT_TOOL_SPECS,
    ],
    nightStages: [...AWAKENED_NIGHT_STAGES, ...ORDINARY_WOLF_CONTRIBUTIONS.runtime.nightStages!],
    validationRules: {
      ...ORDINARY_WOLF_CONTRIBUTIONS.runtime.validationRules,
      ...AWAKENED_VALIDATION_RULES,
      inspect_role: validateRoleInspection,
      shoot: (ctx) => {
        const learned = getAwakenedState(ctx.role)?.learned,
          gun = learned?.skill;
        return validateDeathShot(
          ctx,
          ctx.role.role === Role.AwakenedHiddenWolf &&
            ctx.role.camp === Camp.Wolf &&
            learned?.role === Role.Hunter &&
            learned.activationNight != null &&
            gun?.kind === "hunter" &&
            gun.armed &&
            gun.canShoot,
        );
      },
    },
    deathHook: awakenedDeathHook,
    llmRepair: {
      coerce: {
        ...ORDINARY_WOLF_CONTRIBUTIONS.runtime.llmRepair?.coerce,
        ...DEATH_SHOT_REPAIR.coerce,
        ...Object.fromEntries(
          [...AWAKENED_TOOL_NAMES, "inspect_role"].map((name) => [
            name,
            (args: Record<string, unknown>) => {
              if (args.target_id === null && ["awakened_guard", "awakened_attack"].includes(name))
                return { target_id: null };
              const target = numberOrNull(args.target_id);
              return target === null ? null : { target_id: target };
            },
          ]),
        ),
      },
    },
    baselineAction: (role, request, pick, byCamp, locale, world) => {
      if (request.allowedTools.includes("awakened_mimic")) {
        const target = pick();
        return target === null ? null : { name: "awakened_mimic", args: { target_id: target } };
      }
      if (request.allowedTools.includes("awakened_poison")) {
        const target = byCamp("good");
        return target === null ? null : { name: "awakened_poison", args: { target_id: target } };
      }
      if (request.allowedTools.includes("awakened_guard"))
        return { name: "awakened_guard", args: { target_id: null } };
      if (request.allowedTools.includes("awakened_attack"))
        return { name: "awakened_attack", args: { target_id: byCamp("good") } };
      if (request.allowedTools.includes("inspect_role")) {
        const ability = findNightAbility(role, "role_check", request.context.ability_id),
          target =
            world && ability
              ? roleInspectionTargets(world, request.actorId, ability.state)[0]
              : undefined;
        return target === undefined ? null : { name: "inspect_role", args: { target_id: target } };
      }
      if (request.allowedTools.includes("shoot"))
        return { name: "shoot", args: { target_id: byCamp("good") } };
      return ORDINARY_WOLF_CONTRIBUTIONS.runtime.baselineAction!(role, request, pick, byCamp, locale, world);
    },
  },
  presentation: nativeRolePresentation("awakened_hidden_wolf"),
};

/**
 * 负责觉醒隐狼的工具资格校验贡献。输入为原工具参数、角色状态及可信窗口，输出原规则拒绝或通过。
 * 当前原体、学习／盾／刀资格仍归实际机制，本校验不执行学习、消费库存或提交死亡。
 */
import { AWAKENED_TOOL_NAMES } from "./tool_names";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { Camp, Phase, Role } from "../../../../core/domain/model";
import { isAliveTarget, type ToolRule, type ToolRuleMap } from "../../validation/contracts";
import { canAwakenedKnife } from "./inheritance";
import { currentAwakenedNight } from "./night_scope";
import {
  awakenedSkillForNight,
  canAwakenedExtraKnife,
  canAwakenedMimic,
  getAwakenedState,
} from "./state";

const validateAwakened: ToolRule = ({ world, actorId, role, phase, day, toolCall }) => {
  const state = getAwakenedState(role);
  if (
    role.role !== Role.AwakenedHiddenWolf ||
    role.camp !== Camp.Wolf ||
    !state ||
    day === undefined ||
    currentAwakenedNight(world, role) !== day
  )
    return { code: RuleError.AwakenedUnavailable };
  if (phase !== Phase.Night) return { code: RuleError.AbilityPhase };
  if (toolCall.name === "awakened_mimic") {
    if (!canAwakenedMimic(state, day)) return { code: RuleError.AwakenedUnavailable };
    return toolCall.args.target_id !== actorId && isAliveTarget(world, toolCall.args.target_id)
      ? null
      : { code: RuleError.AwakenedTarget };
  }
  const skill = awakenedSkillForNight(state, day);
  if (toolCall.name === "awakened_attack") {
    if (!canAwakenedKnife(role, world) || !canAwakenedExtraKnife(state, day))
      return { code: RuleError.AwakenedUnavailable };
    return toolCall.args.target_id === null || isAliveTarget(world, toolCall.args.target_id)
      ? null
      : { code: RuleError.AwakenedTarget };
  }
  if (toolCall.name === "awakened_poison" && skill?.kind === "poison")
    return isAliveTarget(world, toolCall.args.target_id)
      ? null
      : { code: RuleError.AwakenedTarget };
  if (toolCall.name === "awakened_guard" && skill?.kind === "guard") {
    if (toolCall.args.target_id !== null && !isAliveTarget(world, toolCall.args.target_id))
      return { code: RuleError.AwakenedTarget };
    if (
      toolCall.args.target_id !== null &&
      skill.lastTarget === toolCall.args.target_id &&
      skill.lastGuardDay === day - 1
    )
      return { code: RuleError.AwakenedGuardRepeat };
    return null;
  }
  return { code: RuleError.AwakenedUnavailable };
};
export { AWAKENED_TOOL_NAMES } from "./tool_names";
export const AWAKENED_VALIDATION_RULES: ToolRuleMap = Object.fromEntries(
  AWAKENED_TOOL_NAMES.map((name) => [name, validateAwakened]),
);

/**
 * 负责熊的夜间采样 frame 与延迟到天亮的发布。输入为原相邻玩家和采样吼声；只有匹配原 frame 时才产生历史与天亮事件。不重复发布同一夜，不以复活或替换相邻身体继续旧采样；关闭和失败保持原前缀。
 */
import {
  recordBearRoar,
  bearDataField as ownData,
  bearDataArrayAppendable as appendable,
  bearHistoryUnpublished as unpublishedHistory,
  recordDawnBearRoar,
} from "./state";

import type { BearReadState as BearState } from "@ai-werewolf-arena/game-contract";

import {
  AliveComponent,
  aliveLifeVersion,
  aliveLifeDescriptor,
} from "../../../../core/domain/components/alive";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import type { IdentityComponent } from "../../../../core/domain/entities/player";
import { Camp, Role, type GameEvent, type EntityId } from "../../../../core/domain/model";
import type { World } from "../../../../core/domain/world";
import { RoleCatalog } from "../catalog";
import { getDefaultRoleCatalog } from "../role-catalog-assembly";
import { getBearState } from "./state";
import { BEAR_SIGNAL_POLICIES, type BearSignalPolicy } from "@ai-werewolf-arena/game-contract";
import {
  captureOriginalPlayer,
  originalPlayerSameLife,
  type OriginalPlayerScope,
} from "../original_player_scope";
import type { CampComponent } from "../../../../core/domain/components/camp";
/** 同一 World／夜号的黎明发表状态：checking 只允许当前尝试，重入会撤销它；
 * 成功后 published，未完成则 finally 置 revoked。清空原 state.history 不恢复这一原发布许可。 */
const dawnPublications = new WeakMap<
  World,
  Map<number, { status: "checking" | "published" | "revoked" }>
>();
const now = Date.now.bind(Date);

function sampleRoar(world: World, actorId: EntityId, catalog: RoleCatalog): boolean {
  const ring = world
      .getAliveEntityIds()
      .sort(
        (a, b) =>
          (world.getComponent(a, COMPONENT.Identity)?.seat ?? a) -
            (world.getComponent(b, COMPONENT.Identity)?.seat ?? b) || a - b,
      ),
    index = ring.indexOf(actorId),
    neighbors =
      index < 0 || ring.length < 2
        ? []
        : [
            ...new Set([
              ring[(index + ring.length - 1) % ring.length],
              ring[(index + 1) % ring.length],
            ]),
          ];
  return neighbors.some((id) => {
    const target = world.getComponent(id, COMPONENT.Role);
    return (
      target?.camp === Camp.Wolf &&
      (catalog.runtime(target.role)?.detectableByBear?.(world, target) ?? true)
    );
  });
}

/** 快照由 manager 持有，不放在玩家 component 或 DTO 中。 */
export class BearNightFrame {
  /** 保留原 World、Role、state、Alive／Camp 与名单的实例引用及生命版本，不克隆为玩家 DTO。
   * 默认政策捕获夜初吼声；显式黎明政策保留原体名单和 catalog，在真正发表时才重新采样并复验。 */
  private constructor(
    private readonly owner: World,
    private readonly day: number,
    private readonly actorId: EntityId,
    private readonly role: RoleComponent,
    private readonly state: BearState,
    private readonly life: AliveComponent,
    private readonly lifeVersion: number,
    private readonly wasAlive: boolean,
    private readonly sampledRoar: boolean,
    private readonly signalPolicy: BearSignalPolicy,
    private readonly catalog: RoleCatalog,
    private readonly originals: readonly OriginalPlayerScope[],
    private readonly camp: CampComponent | undefined,
  ) {}

  static capture(
    world: World,
    day: number,
    catalog: RoleCatalog = getDefaultRoleCatalog(),
    signalPolicy: BearSignalPolicy = "awa_night_open_v1",
  ): BearNightFrame | null {
    if (!BEAR_SIGNAL_POLICIES.includes(signalPolicy)) throw Error("bear_signal_policy_invalid");
    const bears = world
      .entityIds()
      .filter((id) => world.getComponent(id, COMPONENT.Role)?.role === Role.Bear);
    if (bears.length > 1) throw new Error("bear_count_exceeds_limit");
    const actorId = bears[0];
    if (actorId === undefined) return null;
    const role = world.getComponent(actorId, COMPONENT.Role)!,
      state = getBearState(role),
      life = world.getComponent(actorId, COMPONENT.Alive),
      version = life && aliveLifeVersion(life);
    if (role.camp !== Camp.Good || !state || !life || version === undefined) return null;
    const originals =
        signalPolicy === "netease_dawn_live_v1"
          ? world.getAliveEntityIds().map((id) => captureOriginalPlayer(world, id))
          : [],
      camp = world.getComponent(actorId, COMPONENT.Camp);
    if (
      originals.some((p) => p === null) ||
      (signalPolicy === "netease_dawn_live_v1" && camp?.camp !== Camp.Good)
    )
      return null;
    const roared =
      signalPolicy === "awa_night_open_v1" ? sampleRoar(world, actorId, catalog) : false;
    return new BearNightFrame(
      world,
      day,
      actorId,
      role,
      state,
      life,
      version,
      life.alive,
      roared,
      signalPolicy,
      catalog,
      originals as OriginalPlayerScope[],
      camp,
    );
  }

  /** 完整夜死亡波后、该波判胜前发表。 */
  publish(world: World, events: GameEvent[], isCurrent: () => boolean): void {
    if (this.signalPolicy === "netease_dawn_live_v1") {
      this.publishDawn(world, events, isCurrent);
      return;
    }
    if (
      world !== this.owner ||
      !isCurrent() ||
      world.getComponent(this.actorId, COMPONENT.Role) !== this.role ||
      this.role.role !== Role.Bear ||
      this.role.camp !== Camp.Good ||
      getBearState(this.role) !== this.state ||
      world.getComponent(this.actorId, COMPONENT.Alive) !== this.life ||
      aliveLifeVersion(this.life) !==
        this.lifeVersion + (this.wasAlive && !this.life.alive ? 1 : 0) ||
      this.state.history.some((report) => report.day === this.day)
    )
      return;
    const report = { day: this.day, roared: this.life.alive && this.wasAlive && this.sampledRoar };
    recordBearRoar(this.state, report);
    events.push({ timestamp: Date.now(), type: "bear_roared", payload: { ...report } });
  }
  private dawnBodyCurrent(world: World): boolean {
    const factory = aliveLifeDescriptor(this.life);
    if (!factory) return false;
    const actual = Object.getOwnPropertyDescriptor(this.life, "alive"),
      history = ownData(this.state, "history");
    return (
      actual?.get === factory.get &&
      actual?.set === factory.set &&
      world.getComponent(this.actorId, COMPONENT.Role) === this.role &&
      ownData(this.role, "role") === Role.Bear &&
      ownData(this.role, "camp") === Camp.Good &&
      ownData(ownData(this.role, "privateState"), "bear") === this.state &&
      world.getComponent(this.actorId, COMPONENT.Alive) === this.life &&
      aliveLifeVersion(this.life) ===
        this.lifeVersion + (this.wasAlive && !this.life.alive ? 1 : 0) &&
      world.getComponent(this.actorId, COMPONENT.Camp) === this.camp &&
      ownData(this.camp, "camp") === Camp.Good &&
      this.originals.every((p) => originalPlayerSameLife(world, p, true)) &&
      world.getAliveEntityIds().every((id) => this.originals.some((p) => p.id === id)) &&
      unpublishedHistory(history, this.day)
    );
  }
  private publishDawn(world: World, events: GameEvent[], isCurrent: () => boolean): void {
    if (world !== this.owner) return;
    let publications = dawnPublications.get(world);
    if (!publications) {
      publications = new Map();
      dawnPublications.set(world, publications);
    }
    const prior = publications.get(this.day);
    if (prior) {
      if (prior.status === "checking") prior.status = "revoked";
      return;
    }
    const lease: { status: "checking" | "published" | "revoked" } = { status: "checking" };
    publications.set(this.day, lease);
    try {
      if (!isCurrent() || !this.dawnBodyCurrent(world)) return;
      const before = this.originals.map((p) => ({
          p,
          version: aliveLifeVersion(p.life),
          identity: world.getComponent(p.id, COMPONENT.Identity),
          seat: ownData(world.getComponent(p.id, COMPONENT.Identity), "seat"),
        })),
        sampled =
          this.life.alive && this.wasAlive ? sampleRoar(world, this.actorId, this.catalog) : false;
      if (
        !isCurrent() ||
        lease.status !== "checking" ||
        !this.dawnBodyCurrent(world) ||
        before.some(
          ({ p, version, identity, seat }) =>
            aliveLifeVersion(p.life) !== version ||
            world.getComponent(p.id, COMPONENT.Identity) !== identity ||
            ownData(identity, "seat") !== seat,
        )
      )
        return;
      const history = ownData(this.state, "history");
      if (history === events || !appendable(history) || !appendable(events)) return;
      const report = { day: this.day, roared: this.life.alive && this.wasAlive && sampled },
        event: GameEvent = { timestamp: now(), type: "bear_roared", payload: { ...report } };
      // 两个原受控数组按事件→历史写入；原生 defineProperty 不执行数组元素 setter。
      // 这不是事务：第二次写抛错时第一事件保留，finally 只撤销尚 checking 的发布状态，不回滚数组。
      Object.defineProperty(events, String(events.length), {
        value: event,
        enumerable: true,
        writable: true,
        configurable: true,
      });
      recordDawnBearRoar(history, report);
      lease.status = "published";
    } finally {
      if (lease.status === "checking") lease.status = "revoked";
    }
  }
}

/**
 * 负责黑市商人在后置受赠行动之前的交易阶段。输入为当前商人库存与已验证的技能／收货选择；
 * 输出为独立受赠能力或赠枪、反噬提案和跳过／提交事实。已付效果仍绑定原生命，不转给替换商人。
 */
import { closeBlackMarketTrade, recordBlackMarketTrade } from "./state";

import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Camp, Role, Phase, WitchSelfHealRule } from "../../../../core/domain/model";
import { aliveLifeVersion } from "../../../../core/domain/components/alive";
import { captureNightLife, livingNightLife } from "../../../../core/domain/night_effects";
import type { World } from "../../../../core/domain/world";
import type { NightStageHandler } from "../../stages/night/contracts";
import { grantNightAbility } from "../night-ability-grants";
import { grantDeathGun } from "../death_abilities";
import { recipientAbilityStage } from "../recipient_ability_stage";
import { canBlackMarketTrade, getBlackMarketState } from "./state";
const committed = new WeakMap<World, Set<number>>();
export function hasBlackMarketNightCommit(world: World, day: number): boolean {
  return committed.get(world)?.has(day) ?? false;
}
function recordCommit(world: World, day: number): void {
  const days = committed.get(world) ?? new Set<number>();
  days.add(day);
  committed.set(world, days);
}
export const BLACK_MARKET_RECIPIENT_STAGE = recipientAbilityStage("black_market", 140);
export const BLACK_MARKET_TRADE_STAGE: NightStageHandler = {
  id: "black_market_merchant",
  priority: 130,
  async execute(ctx) {
    const day = ctx.currentDay();
    for (const actorId of ctx.getAliveByRole(Role.BlackMarketMerchant)) {
      const role = ctx.world.getComponent(actorId, COMPONENT.Role)!,
        state = getBlackMarketState(role),
        life = captureNightLife(ctx.world, actorId);
      if (!state || !life || role.camp !== Camp.Good) continue;
      const privateState = role.privateState;
      const ownerCurrent = (paid = false) =>
        ctx.isCurrent() &&
        ctx.currentDay() === day &&
        ctx.world.getComponent(actorId, COMPONENT.Role) === role &&
        role.role === Role.BlackMarketMerchant &&
        role.camp === Camp.Good &&
        role.privateState === privateState &&
        getBlackMarketState(role) === state &&
        (livingNightLife(ctx.world, life) ||
          (paid &&
            ctx.world.getComponent(actorId, COMPONENT.Alive) === life.life &&
            !life.life.alive &&
            aliveLifeVersion(life.life) === life.version + 1));
      const current = () => ownerCurrent() && canBlackMarketTrade(state, day);
      if (!current()) continue;
      const skip = () => {
        closeBlackMarketTrade(state, day);
        recordCommit(ctx.world, day);
        ctx.events.push({
          timestamp: Date.now(),
          type: "black_market_trade_skipped",
          payload: { actorId, day },
        });
      };
      let completed = false;
      for (let attempt = 0; attempt < 3; attempt++) {
        if (!current()) break;
        const targets = new Map(
          ctx.world
            .getAliveEntityIds()
            .filter((id) => id !== actorId)
            .map((id) => {
              const targetRole = ctx.world.getComponent(id, COMPONENT.Role)!;
              return [
                id,
                {
                  life: captureNightLife(ctx.world, id)!,
                  role: targetRole,
                  kind: targetRole.role,
                  camp: targetRole.camp,
                  privateState: targetRole.privateState,
                },
              ] as const;
            }),
        );
        const action = targets.size
          ? await ctx.actionProvider.getAction(
              ctx.makeRequest(actorId, ["black_market_trade"], {
                stage: "black_market_merchant",
                requiresAction: false,
                action_failure_policy: "error",
                allow_fallback: false,
                ...(attempt ? { retry_attempt: attempt, retry_max: 2 } : {}),
              }),
            )
          : null;
        if (!current()) break;
        if (action === null) {
          skip();
          completed = true;
          break;
        }
        if (action.name !== "black_market_trade") continue;
        const validated = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
          phase: Phase.Night,
          day,
        });
        if (!current() || !validated.ok || validated.sanitizedCall?.name !== "black_market_trade")
          continue;
        const { target_id: targetId, skill } = validated.sanitizedCall.args,
          target = targets.get(targetId);
        if (
          !target ||
          !livingNightLife(ctx.world, target.life) ||
          ctx.world.getComponent(targetId, COMPONENT.Role) !== target.role ||
          target.role.role !== target.kind ||
          target.role.camp !== target.camp ||
          target.role.privateState !== target.privateState
        )
          continue;
        if (target.camp !== Camp.Good && target.camp !== Camp.Wolf)
          throw new Error("black_market_target_camp_unsupported");
        const failed = target.camp === Camp.Wolf;
        if (!failed) {
          if (skill === "gun") grantDeathGun(ctx.world, actorId, targetId, day, ctx.events);
          else {
            const base = {
              id: "gift:black-market",
              activation: "black_market" as const,
              source: { kind: "gift" as const, actorId },
              sourceDisclosed: false,
              startsOnDay: day + 1,
              maxUses: 1,
            };
            if (skill === "check")
              grantNightAbility(
                ctx.world,
                targetId,
                {
                  ...base,
                  kind: "seer_check",
                  state: { lastTarget: null, lastIsWerewolf: null, lastResult: null, history: [] },
                },
                ctx.events,
              );
            else
              grantNightAbility(
                ctx.world,
                targetId,
                {
                  ...base,
                  kind: "potion",
                  state: {
                    heal: 0,
                    poison: 1,
                    selfHealRule: WitchSelfHealRule.Disabled,
                    canSelfHeal: false,
                    healUsedThisNight: false,
                    poisonUsedThisNight: false,
                  },
                },
                ctx.events,
              );
          }
        }
        recordBlackMarketTrade(state, day, targetId, skill);
        recordCommit(ctx.world, day);
        const choice = state.choice!;
        if (failed)
          (ctx.state.blackMarketBacklashes ??= []).push({
            target: life,
            isCurrent: () =>
              ownerCurrent(true) &&
              state.choice === choice &&
              choice.day === day &&
              choice.targetId === targetId &&
              choice.skill === skill,
          });
        ctx.events.push({
          timestamp: Date.now(),
          type: "black_market_trade_committed",
          payload: { actorId, day, targetId, skill },
        });
        ctx.events.push({
          timestamp: Date.now(),
          type: "black_market_trade_resolved",
          payload: { actorId, day, targetId, skill, outcome: failed ? "backlash" : "granted" },
        });
        completed = true;
        break;
      }
      if (!completed && current()) {
        if (ctx.world.getAliveEntityIds().some((id) => id !== actorId))
          throw new Error("black_market_valid_action_missing");
        skip();
      }
    }
  },
};

/**
 * 负责 黑市商人 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { z } from "zod";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { text, roleName } from "@ai-werewolf-arena/game-text";
import { Camp, Role, Phase } from "../../../../core/domain/model";
import type { NativeRoleContributions } from "../contracts";
import { isAliveTarget } from "../../validation/contracts";
import { numberOrNull } from "../../llm/helpers";
import {
  getBlackMarketState,
  freshBlackMarketState,
  setBlackMarketState,
  projectBlackMarketState,
  canBlackMarketTrade,
} from "./state";
import { BLACK_MARKET_TRADE_STAGE, BLACK_MARKET_RECIPIENT_STAGE } from "./night_stage";
export const BLACK_MARKET_MERCHANT_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    role: Role.BlackMarketMerchant,
    camp: Camp.Good,
    goodSide: "god",
    maxCount: 1,
    label: roleName("black_market_merchant"),
    skillBrief: text("zh-CN", "role.black_market_merchant.brief"),
    supportedBoardRoles: [
      Role.BlackMarketMerchant,
      Role.Wolf,
      Role.WolfKing,
      Role.HiddenWolf,
      Role.Seer,
      Role.Witch,
      Role.Guard,
      Role.Hunter,
      Role.Dreamer,
      Role.Villager,
    ],
  },
  runtime: {
    init: (role) => {
      if (!getBlackMarketState(role)) setBlackMarketState(role, freshBlackMarketState());
    },
    configuration: {
      schema: z.strictObject({}),
      defaults: {},
      apply: (config) => config,
      serialize: () => ({}),
    },
    nightStages: [BLACK_MARKET_TRADE_STAGE, BLACK_MARKET_RECIPIENT_STAGE],
    possibleNightAbilities: ["seer_check", "potion"],
    possibleDeathAbilities: ["gun"],
    toolSpecs: [
      {
        name: "black_market_trade",
        parameters: {
          type: "object",
          properties: {
            target_id: { type: "integer", minimum: 1 },
            skill: { type: "string", enum: ["check", "poison", "gun"] },
          },
          required: ["target_id", "skill"],
          additionalProperties: false,
        },
        argHint: 'black_market_trade args: {"target_id":number,"skill":"check"|"poison"|"gun"}',
        userPromptHintKey: "action.black_market_trade.hint",
      },
    ],
    validationRules: {
      black_market_trade: ({ world, actorId, role, day, phase, toolCall }) => {
        const state = getBlackMarketState(role);
        if (
          role.role !== Role.BlackMarketMerchant ||
          role.camp !== Camp.Good ||
          !state ||
          day === undefined ||
          !canBlackMarketTrade(state, day)
        )
          return { code: RuleError.MerchantUnavailable };
        if (phase !== Phase.Night) return { code: RuleError.AbilityPhase };
        if (toolCall.name !== "black_market_trade") return { code: RuleError.ToolMismatch };
        if (!["check", "poison", "gun"].includes(toolCall.args.skill))
          return { code: RuleError.BlackMarketSkill };
        if (
          !Number.isSafeInteger(toolCall.args.target_id) ||
          toolCall.args.target_id === actorId ||
          !isAliveTarget(world, toolCall.args.target_id)
        )
          return { code: RuleError.MerchantTarget };
        return null;
      },
    },
    llmRepair: {
      coerce: {
        black_market_trade: (args) => {
          const target = numberOrNull(args.target_id);
          return target === null ? null : { target_id: target, skill: args.skill };
        },
      },
    },
    baselineAction: (_role, request, pick) => {
      if (!request.allowedTools.includes("black_market_trade")) return null;
      const target = pick();
      return target === null
        ? null
        : { name: "black_market_trade", args: { target_id: target, skill: "check" } };
    },
  },
  presentation: nativeRolePresentation("black_market_merchant"),
};

/**
 * 管理角色资料、运行和展示的独立查询与有序注册。内建输入已经由实际组合根分开登记，
 * 自定义 flat 输入保留原对象，输出为原贡献引用与晚执行的展示绑定；查询不复制字段、提前求值 getter 或改变回调 receiver。
 * 初始化仍先于默认语言读取，展示才按当前 role 查具体贡献；Catalog 不导入捕获程序。
 * 资料、运行贡献和原文不能相互授予权限，原重复／缺失角色错误前缀保持不变。
 */
import type { Locale } from "@ai-werewolf-arena/game-contract";
import { Camp, type Role, type NativeRolePresentationId } from "@ai-werewolf-arena/game-contract";
import { roleName, text, type MessageKey } from "@ai-werewolf-arena/game-text";
import type { RoleComponent } from "../../../core/domain/components/role";
import type { World } from "../../../core/domain/world";
import { bindRolePresentation } from "../../observation/role-presentation";
import type {
  RoleContributions,
  RoleInitContext,
  RoleInitializationComponent,
  RoleMetadata,
  RoleProfile,
  RoleRuntimeContribution,
} from "./contracts";

export type NativeRoleRenderer = (
  id: NativeRolePresentationId,
  role: RoleComponent,
  locale: Locale,
  world?: World,
) => string;

/** 内建运行必须显式提供展示装配；自定义数组保持既有 flat 用户输入协议。 */
export type RoleCatalogInput =
  | readonly RoleProfile[]
  | { contributions: readonly RoleContributions[]; renderNative: NativeRoleRenderer };

type Entry =
  | { kind: "custom-profile"; profile: RoleProfile }
  | { kind: "contributions"; contributions: RoleContributions; renderNative: NativeRoleRenderer };

export class RoleCatalog {
  private readonly byRole = new Map<Role, Entry>();

  constructor(
    input: RoleCatalogInput,
    private readonly builtinMetadata: readonly RoleMetadata[],
  ) {
    // 输入形态由调用者明确选择；不为识别新协议而探测用户 profile 的新字段或 descriptor。
    if (Array.isArray(input)) {
      for (const profile of input) {
        if (this.byRole.has(profile.role))
          throw new Error(`role_profile_duplicate: ${profile.role}`);
        this.byRole.set(profile.role, { kind: "custom-profile", profile });
      }
    } else {
      const native = input as Exclude<RoleCatalogInput, readonly RoleProfile[]>;
      for (const contributions of native.contributions) {
        if (this.byRole.has(contributions.metadata.role))
          throw new Error(`role_profile_duplicate: ${contributions.metadata.role}`);
        this.byRole.set(contributions.metadata.role, {
          kind: "contributions",
          contributions,
          renderNative: native.renderNative,
        });
      }
    }
  }

  metadata(role: Role): RoleMetadata | undefined {
    const entry = this.byRole.get(role);
    return entry?.kind === "custom-profile" ? entry.profile : entry?.contributions.metadata;
  }

  runtime(role: Role): RoleRuntimeContribution | undefined {
    const entry = this.byRole.get(role);
    return entry?.kind === "custom-profile" ? entry.profile : entry?.contributions.runtime;
  }

  allMetadata(): RoleMetadata[] {
    return Array.from(this.byRole.values(), (entry) =>
      entry.kind === "custom-profile" ? entry.profile : entry.contributions.metadata,
    );
  }

  allRuntime(): { role: Role; metadata: RoleMetadata; runtime: RoleRuntimeContribution }[] {
    return Array.from(this.byRole, ([role, entry]) => ({
      role,
      metadata: entry.kind === "custom-profile" ? entry.profile : entry.contributions.metadata,
      runtime: entry.kind === "custom-profile" ? entry.profile : entry.contributions.runtime,
    }));
  }

  requireMetadata(role: Role): RoleMetadata {
    const entry = this.requireEntry(role);
    return entry.kind === "custom-profile" ? entry.profile : entry.contributions.metadata;
  }

  requireRuntime(role: Role): RoleRuntimeContribution {
    const entry = this.requireEntry(role);
    return entry.kind === "custom-profile" ? entry.profile : entry.contributions.runtime;
  }

  participation(role: RoleComponent): {
    canVote: boolean;
    canBeExiled: boolean;
    canBeSheriff: boolean;
  } {
    const runtime = this.runtime(role.role);
    if (!runtime) return { canVote: false, canBeExiled: false, canBeSheriff: false };
    return typeof runtime.participation === "function"
      ? { ...runtime.participation(role) }
      : { ...(runtime.participation ?? { canVote: true, canBeExiled: true, canBeSheriff: true }) };
  }

  getCamp(role: Role): Camp {
    return this.requireMetadata(role).camp ?? Camp.Good;
  }

  label(role: Role, locale: Locale = "zh-CN"): string {
    const metadata = this.metadata(role);
    const builtIn = this.builtinMetadata.find((entry) => entry.role === role);
    // 显式用户原文继续绕过内建翻译；仅等于原内建文字时采用原翻译策略。
    if (metadata && (!builtIn || metadata.label !== builtIn.label)) return metadata.label;
    return roleName(role, locale);
  }

  skillBrief(role: Role, locale: Locale = "zh-CN"): string {
    const metadata = this.metadata(role);
    if (!metadata) return role;
    const builtIn = this.builtinMetadata.find((entry) => entry.role === role);
    if (!builtIn || metadata.skillBrief !== builtIn.skillBrief) return metadata.skillBrief;
    return text(locale, `role.${role}.brief` as MessageKey);
  }

  applyRuntime(roleComp: RoleComponent, ctx: RoleInitContext = {}): void {
    const entry = this.requireEntry(roleComp.role);
    const runtime = entry.kind === "custom-profile" ? entry.profile : entry.contributions.runtime;
    runtime.init?.(roleComp as RoleInitializationComponent, ctx);
    const defaultLocale = ctx.locale ?? "zh-CN";
    bindRolePresentation(roleComp, (locale = defaultLocale) => {
      const active = this.requireEntry(roleComp.role);
      if (active.kind === "custom-profile") {
        // 保留原两次方法 getter、profile receiver 及随后 ctx.world 求值的完整失败前缀。
        return active.profile.renderPrompt
          ? active.profile.renderPrompt(roleComp, locale, ctx.world)
          : text(locale, "role.generic.state", {
              role: this.label(active.profile.role, locale),
            });
      }
      const presentation = active.contributions.presentation;
      if (presentation.kind === "native")
        return active.renderNative(presentation.id, roleComp, locale, ctx.world);
      return presentation.renderPrompt
        ? presentation.renderPrompt(roleComp, locale, ctx.world)
        : text(locale, "role.generic.state", {
            role: this.label(active.contributions.metadata.role, locale),
          });
    });
  }

  private requireEntry(role: Role): Entry {
    const entry = this.byRole.get(role);
    if (!entry) throw new Error(`role_profile_not_registered: ${role}`);
    return entry;
  }
}

/**
 * 负责定义角色资料、运行贡献及展示贡献的独立装配契约。资料只有身份、公开名称和组合约束，
 * 运行贡献拥有原初始化、许可、工具、阶段与 hook，展示声明只标识原生捕获或受信任原文。
 * 三者不相互授权或复制状态；自定义 flat profile 是明确支持的输入，Catalog 保留其原对象、
 * getter、receiver 与读取时点，不在接入时摊平或调用展示。初始化仍仅获得原容器写权。
 */
import type { NightAbilityKind } from "@ai-werewolf-arena/game-contract";

import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import type { Locale } from "@ai-werewolf-arena/game-contract";
import type { VictoryAffiliation } from "@ai-werewolf-arena/game-contract";
import type { InspectionCamp, RoleId } from "@ai-werewolf-arena/game-contract";
import { RoleComponent } from "../../../core/domain/components/role";
import { ActionRequest, BoardConfig, Camp, Role, ToolCall } from "../../../core/domain/model";
import type { ToolSpec, StageDirectiveRule } from "../contracts";
import type { ToolRepairPack } from "../llm/contracts";
import type { NightStageHandler } from "../stages/night/contracts";
import type { ToolRuleMap } from "../validation/contracts";
import type { DeathHook, VotedOutHook } from "../hooks/hook_registry";
import type { z } from "zod";
import type { World } from "../../../core/domain/world";

/** 角色初始化上下文。 */
export interface RoleInitContext {
  locale?: Locale;
  boardConfig?: ReadonlyBoardConfig;
  world?: World;
}

/** 仅初始化可写原扩展键和替换容器；不向普通读方公开可写角色 API。 */
export type RoleInitializationComponent = Omit<RoleComponent, "privateState"> & {
  privateState: Record<string, unknown>;
};

/** 阵营归属本身不授予知识、狼聊或刀权。 */
export interface WolfTeamPermissions {
  readonly recognizedByPack: boolean;
  readonly recognizes: "pack" | "all" | "none" | readonly Role[];
  readonly canChat: boolean;
  readonly canVoteForKill: boolean;
}

/** 不携带执行回调的角色资料；注册资料本身不授予角色运行支持。 */
export interface RoleMetadata {
  role: Role;
  camp?: Camp;
  label: string;
  skillBrief: string;
  goodSide?: "god" | "villager";
  /** 声明角色数量限制；未声明的角色保持原数量政策。 */
  maxCount?: number;
  /** 具备有限学习规则的角色贡献组合白名单。 */
  supportedBoardRoles?: readonly Role[];
  /** 有限来源目标；公开解析与内部初始化均拒绝不兼容目标。 */
  supportedWinConditions?: readonly import("../../../core/domain/identity").WinCondition[];
}

/** 具体机制的运行贡献；其原函数引用、资源所有权及失败前缀不由资料或展示改变。 */
export interface RoleRuntimeContribution {
  /** 熊的被动感知独立于主动查验标签和刀权。 */
  detectableByBear?: (world: World, role: RoleComponent) => boolean;
  initialVictoryAffiliations?:
    | readonly VictoryAffiliation[]
    | ((role: RoleComponent, ctx: RoleInitContext) => readonly VictoryAffiliation[]);
  /** 公开参与限制；秘密免疫仍属于结算 hook。 */
  participation?:
    | { canVote: boolean; canBeExiled: boolean; canBeSheriff: boolean }
    | ((role: RoleComponent) => { canVote: boolean; canBeExiled: boolean; canBeSheriff: boolean });
  wolfTeam?: WolfTeamPermissions | ((role: RoleComponent, world?: World) => WolfTeamPermissions);
  /** 特定时点获知队友的角色，显式保留其已有知识。 */
  knownTeammates?: (role: RoleComponent, world: World) => readonly number[];
  /** 显式公开自爆资格，独立于阵营及刀权。 */
  canSelfDestruct?: boolean | ((role: RoleComponent) => boolean);
  inspectionLabels?:
    | { camp?: InspectionCamp; role?: RoleId }
    | ((role: RoleComponent) => { camp?: InspectionCamp; role?: RoleId });
  configuration?: {
    schema: z.ZodType;
    defaults: Readonly<Record<string, unknown>>;
    apply: (config: BoardConfig, value: unknown) => BoardConfig;
    /** 仅从已解析板子序列化本角色的公开参数。 */
    serialize: (config: BoardConfig) => unknown;
  };
  init?: (roleComp: RoleInitializationComponent, ctx: RoleInitContext) => void;
  toolSpecs?: ToolSpec[];
  stageDirectives?: StageDirectiveRule[];
  validationRules?: ToolRuleMap;
  nightStages?: NightStageHandler[];
  possibleNightAbilities?: readonly NightAbilityKind[];
  possibleDeathAbilities?: readonly "gun"[];
  llmRepair?: ToolRepairPack;
  votedOutHook?: VotedOutHook;
  deathHook?: DeathHook;
  baselineAction?: (
    roleComp: RoleComponent,
    request: ActionRequest,
    pickAliveNotSelf: () => number | null,
    pickAliveByCamp: (camp: "good" | "wolf" | "third_party") => number | null,
    locale?: Locale,
    world?: World,
  ) => ToolCall | null;
}

/** 展示贡献不拥有运行状态；原生只声明捕获 ID，自定义方法保留实际贡献对象作为 receiver。 */
export type RolePresentationContribution =
  | {
      readonly kind: "native";
      readonly id: import("@ai-werewolf-arena/game-contract").NativeRolePresentationId;
    }
  | { readonly kind: "custom"; renderPrompt?: RoleProfile["renderPrompt"] };

/** 实际组合根分别登记这三份贡献，禁止把它们再次摊平成一个内建 profile。 */
export interface RoleContributions {
  metadata: RoleMetadata;
  runtime: RoleRuntimeContribution;
  presentation: RolePresentationContribution;
}

/** 明确支持的用户 flat 输入；读取与调用仍针对原对象，不经复制或强制规范化。 */
export interface RoleProfile extends RoleMetadata, RoleRuntimeContribution {
  renderPrompt?: (roleComp: RoleComponent, locale?: Locale, world?: World) => string;
}

/** 内建 55 个角色均有原生展示声明，不能被宽化为可缺失原生 ID 的自定义分支。 */
export interface NativeRoleContributions extends RoleContributions {
  presentation: Extract<RolePresentationContribution, { kind: "native" }>;
}

/**
 * 负责丘比特首夜恋人选择的请求、await 复验、关系绑定、成员归属与事实发布。
 * 输入为原夜上下文和经网关验证的配对；输出是同一关系记录及原事件，数据库存／选择写入由本族槽负责。
 * 原角色、容器、生命与双方 Victory 在等待前后复验；最终同步段依次绑定关系、消费选择、安装归属再发布。
 * 同步段不是事务：字段、组件或事件失败保留先完成的前缀，不退款或重新使用旧请求，殉情与判胜另有 owner。
 */
import { COMPONENT } from "../../../../core/domain/components/names";

import {
  createVictoryComponent,
  type VictoryComponent,
} from "../../../../core/domain/components/victory";
import type { LoversComponent } from "../../../../core/domain/components/lovers";
import { Camp, Phase, Role } from "../../../../core/domain/model";
import { captureNightLife, livingNightLife } from "../../../../core/domain/night_effects";
import type { NightStageHandler } from "../../stages/night/contracts";
import { getCupidState, commitCupidChoice } from "./state-slot";
import { bindLovers, hasCupidNightCommit } from "./relation";

export const CUPID_STAGE: NightStageHandler = {
  id: "cupid",
  priority: 80,
  async execute(ctx) {
    const day = ctx.currentDay();
    if (day !== 1) return;
    if (hasCupidNightCommit(ctx.world, day)) throw new Error("cupid_night_reentry_after_commit");
    for (const actorId of ctx.getAliveByRole(Role.Cupid)) {
      const role = ctx.world.getComponent(actorId, COMPONENT.Role)!,
        state = getCupidState(role),
        life = captureNightLife(ctx.world, actorId),
        victory = ctx.world.getComponent(actorId, COMPONENT.Victory);
      if (!state || !life || !victory || role.camp !== Camp.Good) continue;
      const privateState = role.privateState,
        policy = state.policy,
        affiliations = victory.affiliations,
        membership = JSON.stringify(affiliations);
      const current = () =>
        ctx.isCurrent() &&
        ctx.currentDay() === day &&
        ctx.world.getComponent(actorId, COMPONENT.Role) === role &&
        role.role === Role.Cupid &&
        role.camp === Camp.Good &&
        role.privateState === privateState &&
        getCupidState(role) === state &&
        state.policy === policy &&
        state.remaining === 1 &&
        state.choice === null &&
        livingNightLife(ctx.world, life) &&
        ctx.world.getComponent(actorId, COMPONENT.Victory) === victory &&
        victory.affiliations === affiliations &&
        JSON.stringify(affiliations) === membership &&
        !hasCupidNightCommit(ctx.world, day);
      if (!current()) continue;
      let completed = false;
      for (let attempt = 0; attempt < 3; attempt++) {
        if (!current()) break;
        const targets = new Map(
          ctx.world.getAliveEntityIds().map((id) => {
            const targetRole = ctx.world.getComponent(id, COMPONENT.Role)!,
              targetVictory = ctx.world.getComponent(id, COMPONENT.Victory)!;
            return [
              id,
              {
                life: captureNightLife(ctx.world, id)!,
                role: targetRole,
                kind: targetRole.role,
                camp: targetRole.camp,
                privateState: targetRole.privateState,
                victory: targetVictory,
                affiliations: targetVictory.affiliations,
                membership: JSON.stringify(targetVictory.affiliations),
              },
            ] as const;
          }),
        );
        if (targets.size < 2) throw new Error("cupid_valid_action_missing");
        const request = ctx.makeRequest(actorId, ["choose_lovers"], {
          stage: "cupid",
          requiresAction: true,
          allow_fallback: false,
          action_failure_policy: "error",
          ...(attempt ? { retry_attempt: attempt, retry_max: 2 } : {}),
        });
        if (!current()) break;
        const action = await ctx.actionProvider.getAction(request);
        if (!current()) break;
        if (action?.name !== "choose_lovers") continue;
        const valid = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
          phase: Phase.Night,
          day,
        });
        if (!current() || !valid.ok || valid.sanitizedCall?.name !== "choose_lovers") continue;
        const pairIds: [number, number] = [
          valid.sanitizedCall.args.first_id,
          valid.sanitizedCall.args.second_id,
        ];
        const selected = pairIds.map((id) => targets.get(id));
        if (
          selected.some(
            (target, index) =>
              !target ||
              !livingNightLife(ctx.world, target.life) ||
              ctx.world.getComponent(pairIds[index]!, COMPONENT.Role) !== target.role ||
              target.role.role !== target.kind ||
              target.role.camp !== target.camp ||
              target.role.privateState !== target.privateState ||
              (target.camp !== Camp.Good && target.camp !== Camp.Wolf) ||
              ctx.world.getComponent(pairIds[index]!, COMPONENT.Victory) !== target.victory ||
              target.victory.affiliations !== target.affiliations ||
              JSON.stringify(target.affiliations) !== target.membership,
          )
        )
          continue;
        const first = selected[0]!,
          second = selected[1]!,
          mixed = first.camp !== second.camp;
        const record: LoversComponent = Object.freeze({
          actorId,
          day: 1,
          policy,
          pairIds: Object.freeze(pairIds),
          pairCamps: Object.freeze([first.camp, second.camp]) as LoversComponent["pairCamps"],
          groupId: "cupid_lovers",
          mixed,
        });
        const memberIds = new Set(pairIds);
        if (policy === "netease_2017_cupid_follows_lovers_v1") memberIds.add(actorId);
        // 最后授权后不再 await；关系先绑定，选择随后付款，再逐成员安装归属。失败不撤回已完成的前缀。
        bindLovers(ctx.world, record, [first.life, second.life]);
        commitCupidChoice(state, pairIds);
        for (const id of memberIds)
          ctx.world.addComponent(
            id,
            COMPONENT.Victory,
            createVictoryComponent([
              mixed
                ? { kind: "relationship", groupId: record.groupId }
                : { kind: "faction", faction: first.camp },
            ]),
          );
        ctx.events.push({
          timestamp: Date.now(),
          type: "cupid_lovers_chosen",
          payload: { actorId, day: 1, pairIds: [...pairIds] },
        });
        for (const id of pairIds)
          ctx.events.push({
            timestamp: Date.now(),
            type: "lover_recognized",
            payload: { actorId: id, partnerId: pairIds.find((target) => target !== id)! },
          });
        ctx.events.push({
          timestamp: Date.now(),
          type: "cupid_relation_resolved",
          payload: record,
        });
        completed = true;
        break;
      }
      if (!completed && current()) throw new Error("cupid_valid_action_missing");
    }
  },
};

/**
 * 负责 丘比特 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { z } from "zod";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { text, roleName } from "@ai-werewolf-arena/game-text";
import { CUPID_POLICIES } from "../../../../core/domain/board";
import { Camp, Role, Phase, WinCondition } from "../../../../core/domain/model";
import type { NativeRoleContributions } from "../contracts";
import { isAliveTarget } from "../../validation/contracts";
import { numberOrNull } from "../../llm/helpers";
import { getCupidState, projectCupidState, installCupidState } from "./state-slot";
import { hasCupidNightCommit } from "./relation";
import { CUPID_STAGE } from "./night_stage";
const parameters = z.strictObject({
  policy: z.enum(CUPID_POLICIES).default("netease_2017_cupid_follows_lovers_v1"),
});
export const CUPID_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    role: Role.Cupid,
    camp: Camp.Good,
    goodSide: "god",
    maxCount: 1,
    label: roleName("cupid"),
    skillBrief: text("zh-CN", "role.cupid.brief"),
    supportedWinConditions: [WinCondition.SlaughterCity],
    supportedBoardRoles: [
      Role.Cupid,
      Role.Wolf,
      Role.WolfKing,
      Role.WhiteWolfKing,
      Role.Seer,
      Role.Witch,
      Role.Guard,
      Role.Hunter,
      Role.Idiot,
      Role.Villager,
      Role.Knight,
      Role.Dreamer,
      Role.WolfBeauty,
    ],
  },
  runtime: {
    init: installCupidState,
    configuration: {
      schema: parameters,
      defaults: { policy: "netease_2017_cupid_follows_lovers_v1" },
      apply: (config, value) => ({ ...config, cupid: parameters.parse(value) }),
      serialize: (config) => parameters.parse(config.cupid ?? {}),
    },
    nightStages: [CUPID_STAGE],
    toolSpecs: [
      {
        name: "choose_lovers",
        parameters: {
          type: "object",
          properties: { first_id: { type: "integer" }, second_id: { type: "integer" } },
          required: ["first_id", "second_id"],
          additionalProperties: false,
        },
        argHint: 'choose_lovers args: {"first_id":number,"second_id":number}',
        userPromptHintKey: "action.choose_lovers.hint",
      },
    ],
    validationRules: {
      choose_lovers: ({ world, role, day, phase, toolCall }) => {
        const state = getCupidState(role);
        if (
          role.role !== Role.Cupid ||
          role.camp !== Camp.Good ||
          !state ||
          state.remaining !== 1 ||
          state.choice !== null ||
          day !== 1 ||
          hasCupidNightCommit(world, day)
        )
          return { code: RuleError.CupidUnavailable };
        if (phase !== Phase.Night) return { code: RuleError.AbilityPhase };
        if (toolCall.name !== "choose_lovers") return { code: RuleError.ToolMismatch };
        const { first_id, second_id } = toolCall.args;
        if (
          !Number.isSafeInteger(first_id) ||
          !Number.isSafeInteger(second_id) ||
          first_id === second_id ||
          !isAliveTarget(world, first_id) ||
          !isAliveTarget(world, second_id)
        )
          return { code: RuleError.CupidTarget };
        return null;
      },
    },
    baselineAction: (_role, request, _other, _camp, _locale, world) => {
      if (!request.allowedTools.includes("choose_lovers") || !world) return null;
      const ids = world.getAliveEntityIds();
      return ids.length < 2
        ? null
        : { name: "choose_lovers", args: { first_id: ids[0]!, second_id: ids[1]! } };
    },
    llmRepair: {
      coerce: {
        choose_lovers: (args) => {
          const first = numberOrNull(args.first_id),
            second = numberOrNull(args.second_id);
          return first === null || second === null ? null : { first_id: first, second_id: second };
        },
      },
    },
  },
  presentation: nativeRolePresentation("cupid"),
};

/**
 * 负责丘比特完整选择数据的原初始化、同槽读取、玩家投影与库存／选择写入。
 * 输入是原初始化角色及上下文，或已获准提交的原状态和配对编号；输出保留原槽引用与独立玩家选择视图。
 * 初始化先查原槽，先求值赋值左值的容器，再读取政策并安装；提交先消费剩余次数，再复制配对数组并写选择，失败不回滚。
 * 本槽不新增 live schema、深冻结或档案编码；关系、生命、Victory、窗口和许可仍由原夜阶段／关系 owner 持有。
 */
import type { CupidReadState, CupidState } from "@ai-werewolf-arena/game-contract";
import { playerDataField } from "../player-state-data";

import type { RoleComponent } from "../../../../core/domain/components/role";
import type { RoleInitializationComponent, RoleInitContext } from "../contracts";
export function getCupidState(role: RoleComponent | undefined): CupidReadState | undefined {
  return (role as { readonly privateState: { readonly cupid?: unknown } } | undefined)?.privateState
    .cupid as CupidReadState | undefined;
}
export function projectCupidState(
  state: CupidReadState,
): import("@ai-werewolf-arena/game-contract/player-state-views").PlayerCupidState {
  const policy = playerDataField(state, "policy"),
    choice = playerDataField(state, "choice"),
    pair = playerDataField(choice, "pairIds");
  // 数组用自己的数据属性读取；共用对象读取器本来拒绝数组，不能因此执行外来编号访问器。
  const pairField = (key: string): unknown => {
    if (!Array.isArray(pair)) return undefined;
    const field = Object.getOwnPropertyDescriptor(pair, key);
    return field && Object.hasOwn(field, "value") ? field.value : undefined;
  };
  const first = pairField("0"),
    second = pairField("1");
  const positive = (id: unknown): id is number =>
    typeof id === "number" && Number.isSafeInteger(id) && id > 0;
  return {
    policy: policy === "lui_meme_lovers_only_v1" ? policy : "netease_2017_cupid_follows_lovers_v1",
    remaining: playerDataField(state, "remaining") === 1 ? 1 : 0,
    choice:
      playerDataField(choice, "day") === 1 &&
      Array.isArray(pair) &&
      pairField("length") === 2 &&
      positive(first) &&
      positive(second) &&
      first !== second
        ? { day: 1, pairIds: [first, second] }
        : null,
  };
}

/** 原完整初始化：槽不存在时才建初态，不提前读取政策或把整个私有容器复制／冻结。 */
export function installCupidState(role: RoleInitializationComponent, ctx: RoleInitContext): void {
  if (!getCupidState(role))
    role.privateState.cupid = {
      policy: ctx.boardConfig?.cupid?.policy ?? "netease_2017_cupid_follows_lovers_v1",
      remaining: 1,
      choice: null,
    };
}

/** 调用前关系已由原 owner 绑定；次数写入后的配对复制或 choice setter 失败不撤回已绑定关系或补发事实。 */
export function commitCupidChoice(state: CupidReadState, pairIds: [number, number]): void {
  (state as Pick<CupidState, "remaining">).remaining = 0;
  (state as Pick<CupidState, "choice">).choice = { day: 1, pairIds: [...pairIds] };
}

/**
 * Derives Cupid city victory from the current relation and surviving affiliations. Inputs are
 * the original lovers record and living World roster; output is the Cupid victory decision when its
 * predicate holds. It never changes the lovers relation or eliminates a player.
 */
import {
  COMPONENT,
  Camp,
  type World,
  type RoleComponent,
  type WinDecision,
} from "../../../../core/domain";
import { victoryDecision } from "../../win_conditions/results";
import { loversRecord, livingOriginalLovers } from "./relation";
/** A finite City-only sourced board contribution, evaluated after complete death chains. */
export function cupidCityDecision(world: World): { decision: WinDecision | null } | null {
  const record = loversRecord(world);
  if (!record) return null;
  const group = new Set<number>(record.pairIds);
  const follows = record.policy === "netease_2017_cupid_follows_lovers_v1";
  if (follows) group.add(record.actorId);
  const alive = world.getAliveEntityIds();
  if (record.mixed && livingOriginalLovers(world) && alive.every((id) => group.has(id)))
    return {
      decision: victoryDecision(
        world,
        { kind: "relationship", groupId: record.groupId },
        "cupid_lovers_only_survivors",
      ),
    };
  let wolves = 0,
    good = 0;
  for (const id of alive) {
    const role = world.getComponent(id, COMPONENT.Role);
    if (role?.camp === Camp.Wolf) wolves++;
    if (
      role?.camp === Camp.Good &&
      !(follows && id === record.actorId && (record.mixed || record.pairCamps[0] === Camp.Wolf))
    )
      good++;
  }
  return {
    decision:
      wolves === 0
        ? victoryDecision(world, { kind: "faction", faction: Camp.Good }, "all_wolves_eliminated")
        : good === 0
          ? victoryDecision(world, { kind: "faction", faction: Camp.Wolf }, "all_good_eliminated")
          : null,
  };
}

/**
 * Captures inspection target identity and commits sourced Fox inspection claims. Inputs are
 * original target life/role references and owner-current checks; outputs preserve inspection
 * bookkeeping and delayed lethal claims. Knowledge publication does not itself mark the Fox
 * dead.
 */
import { COMPONENT, Role, Camp, type RoleComponent, type World } from "../../../../core/domain";
import { livingNightLife, type NightLifeScope } from "../../../../core/domain/night_effects";
import type { NightStageState } from "../../stages/night/contracts";
const committed = new WeakMap<World, Set<number>>();
export function hasFoxInspectionNightCommit(world: World, day: number): boolean {
  return committed.get(world)?.has(day) ?? false;
}
/** Snapshot before await; a new identity cannot acquire an old pending inspection. */
export function captureInspectionIdentity(world: World, target: NightLifeScope) {
  const role = world.getComponent(target.id, COMPONENT.Role);
  const kind = role?.role,
    camp = role?.camp,
    state = role?.privateState;
  return {
    role,
    isCurrent: () =>
      livingNightLife(world, target) &&
      world.getComponent(target.id, COMPONENT.Role) === role &&
      role?.role === kind &&
      role?.camp === camp &&
      role?.privateState === state,
  };
}
/** Only committed Seer-kind actions call this; read-only and role inspection never do. */
export function commitFoxInspection(
  world: World,
  state: NightStageState,
  target: NightLifeScope,
  day: number,
  ownerCurrent: () => boolean,
): void {
  const identity = captureInspectionIdentity(world, target);
  if (identity.role?.role !== Role.CursedFox || identity.role.camp !== Camp.ThirdParty) return;
  (state.foxInspections ??= []).push({
    target,
    isTargetCurrent: identity.isCurrent,
    isCurrent: () => ownerCurrent() && identity.isCurrent(),
  });
  const days = committed.get(world) ?? new Set<number>();
  days.add(day);
  committed.set(world, days);
}

/**
 * Replaces an existing result with Fox victory only at the configured final predicate. Inputs
 * are the World and existing faction victory decision; output preserves the appropriate Fox result data. It
 * does not run night inspections or resolve damage during result projection.
 */
import {
  COMPONENT,
  Role,
  Camp,
  type World,
  type WinDecision,
  type RoleComponent,
} from "../../../../core/domain";
import { victoryDecision } from "../../win_conditions/results";
import { CURSED_FOX_GOAL } from "./profile";
export function replaceWithFoxVictory(world: World, decision: WinDecision): WinDecision {
  if (
    decision.outcome.kind !== "victory" ||
    decision.outcome.primary.kind !== "faction" ||
    ![Camp.Good, Camp.Wolf].includes(decision.outcome.primary.faction as Camp)
  )
    return decision;
  const fox = world.getAliveEntityIds().find((id) => {
    const role = world.getComponent(id, COMPONENT.Role);
    return role?.role === Role.CursedFox && role.camp === Camp.ThirdParty;
  });
  return fox === undefined
    ? decision
    : victoryDecision(
        world,
        { kind: "individual", goalId: CURSED_FOX_GOAL, playerId: fox },
        "cursed_fox_survived_faction_elimination",
      );
}

/**
 * 负责赠枪实例的授予、武装、转移、首次死亡收尾以及原体授权。
 * 输入为所属 World、原角色／生命／库存实例和明确业务夜时点；输出为同引用只读实例、
 * 捕获资格和原资源事实。owners/counters 是原唯一状态，不复制为第二份实例仓库。
 * 仅写 deathAbilities、retiredDeathAbilityIds 及本枪资源；不执行死亡、枪目标选择或录制 I/O。
 * 已付前缀和原 getter／提交顺序保持，替身或复活不能重新获得首次死亡枪权。
 * F05a 将永久退休拒绝放在新执行入口；已消费提案的纯原体／来源／生命及 capture.isCurrent 不含此判断。
 */
import type { DeathGun, DeathGunReadView } from "@ai-werewolf-arena/game-contract";
import { COMPONENT } from "../../../core/domain/components/names";
import type { RoleComponent } from "../../../core/domain/components/role";
import { isRoleExecutionRetired } from "../../../core/domain/role-execution-authority";
import { Camp, type EntityId, type GameEvent } from "../../../core/domain/model";
import { aliveLifeVersion, type AliveComponent } from "../../../core/domain/components/alive";
import type { World } from "../../../core/domain/world";
import { projectDeathGun } from "./player_state";

// 原体证明捕获原 World、角色、private 容器、生命版本及来源；相同字符串 ID 不构成授权。
interface GunOwner {
  world: World;
  actorId: number;
  role: RoleComponent;
  roleKind: RoleComponent["role"];
  camp: Camp;
  privateState: RoleComponent["privateState"];
  life: AliveComponent;
  version: number;
  id: string;
  source: DeathGunReadView["source"];
  sourceKind: DeathGun["source"]["kind"];
  sourceActor: number;
  sourceId?: string;
  grantedNight: number;
  armedOnNight: number | null;
}

// 两个原 WeakMap 随实际 owner 整体迁移；计数只在成功安装后推进，不查询 RNG 或时钟。
const owners = new WeakMap<DeathGunReadView, GunOwner>(),
  counters = new WeakMap<World, number>();

export function allDeathGuns(role: RoleComponent | undefined): DeathGunReadView[] {
  return Object.values(
    ((role as { readonly privateState: { readonly deathAbilities?: unknown } } | undefined)
      ?.privateState.deathAbilities ?? {}) as Readonly<Record<string, DeathGunReadView>>,
  ).sort((a, b) => a.id.localeCompare(b.id));
}

export function findDeathGun(
  role: RoleComponent | undefined,
  id: string,
): DeathGunReadView | undefined {
  return allDeathGuns(role).find((gun) => gun.id === id);
}

function bind(world: World, actorId: number, gun: DeathGun, sourceRole: RoleComponent): void {
  const role = world.getComponent(actorId, COMPONENT.Role),
    life = world.getComponent(actorId, COMPONENT.Alive),
    version = life && aliveLifeVersion(life);
  if (!role || role.camp !== Camp.Good || !life?.alive || version === undefined)
    throw new Error("death_ability_owner_invalid");
  // 这是新赠枪绑定入口；只否决退休演员，原体／已付提案复验仍由不含墓碑的 ownerCurrent 执行。
  if (isRoleExecutionRetired(role) || isRoleExecutionRetired(sourceRole))
    throw new Error("death_ability_owner_invalid");
  owners.set(gun, {
    world,
    actorId,
    role,
    roleKind: role.role,
    camp: role.camp,
    privateState: role.privateState,
    life,
    version,
    id: gun.id,
    source: gun.source,
    sourceKind: gun.source.kind,
    sourceActor: gun.source.actorId,
    ...(gun.source.kind === "transfer" ? { sourceId: gun.source.abilityId } : {}),
    grantedNight: gun.grantedNight,
    armedOnNight: gun.armedOnNight,
  });
}

export function deathGunOwnerCurrent(
  world: World,
  actorId: number,
  gun: DeathGunReadView,
  onDeath = false,
): boolean {
  const owner = owners.get(gun);
  if (!owner || owner.world !== world || owner.actorId !== actorId) return false;
  const version = aliveLifeVersion(owner.life);
  return (
    gun.id === owner.id &&
    gun.kind === "gun" &&
    gun.source === owner.source &&
    gun.source.kind === owner.sourceKind &&
    gun.source.actorId === owner.sourceActor &&
    (gun.source.kind === "gift" || gun.source.abilityId === owner.sourceId) &&
    gun.sourceDisclosed === false &&
    gun.grantedNight === owner.grantedNight &&
    gun.armedOnNight === owner.armedOnNight &&
    world.getComponent(actorId, COMPONENT.Role) === owner.role &&
    owner.role.role === owner.roleKind &&
    owner.role.camp === owner.camp &&
    owner.role.privateState === owner.privateState &&
    findDeathGun(owner.role, gun.id) === gun &&
    world.getComponent(actorId, COMPONENT.Alive) === owner.life &&
    (onDeath
      ? !owner.life.alive && version === owner.version + 1
      : owner.life.alive && version === owner.version)
  );
}

function emit(
  events: GameEvent[],
  actorId: number,
  gun: Pick<
    DeathGunReadView,
    "id" | "grantedNight" | "armedOnNight" | "remaining" | "disabled" | "deathExpired"
  >,
  operation: "granted" | "armed" | "disabled" | "enabled" | "transferred_out",
  abilityId = gun.id,
): void {
  events.push({
    timestamp: Date.now(),
    type: "death_ability_changed",
    payload: {
      actorId,
      abilityId,
      operation,
      grantedNight: gun.grantedNight,
      armedOnNight: gun.armedOnNight,
      remaining: gun.remaining,
      disabled: gun.disabled,
      deathExpired: gun.deathExpired,
    },
  });
}

/** 安装原体证明后写入目标库存，再推进计数并发表授予事实；发布失败保留此前写入，不回滚安装。 */
export function grantDeathGun(
  world: World,
  fromId: EntityId,
  toId: EntityId,
  night: number,
  events: GameEvent[],
): DeathGunReadView {
  const from = world.getComponent(fromId, COMPONENT.Role),
    to = world.getComponent(toId, COMPONENT.Role);
  if (
    fromId === toId ||
    !from ||
    from.camp !== Camp.Good ||
    !world.getComponent(fromId, COMPONENT.Alive)?.alive ||
    !to ||
    to.camp !== Camp.Good ||
    !world.getComponent(toId, COMPONENT.Alive)?.alive ||
    !Number.isSafeInteger(night) ||
    night < 1
  )
    throw new Error("death_ability_grant_invalid");
  if (isRoleExecutionRetired(from) || isRoleExecutionRetired(to))
    throw new Error("death_ability_grant_invalid");
  if (allDeathGuns(to).length) throw new Error("death_ability_gun_already_owned");
  const next = (counters.get(world) ?? 0) + 1,
    id = `gift-gun:${next}`;
  if (
    (
      (to.privateState as { readonly retiredDeathAbilityIds?: unknown }).retiredDeathAbilityIds as
        string[] | undefined
    )?.includes(id)
  )
    throw new Error("death_ability_id_retired");
  const gun: DeathGun = {
    id,
    kind: "gun",
    source: { kind: "gift", actorId: fromId },
    sourceDisclosed: false,
    grantedNight: night,
    armedOnNight: null,
    remaining: 1,
    disabled: false,
    deathExpired: false,
  };
  bind(world, toId, gun, from);
  // bind 的原 privateState getter 后再核捕获双端；失败不安装枪、不推进计数，不回滚已建立证明。
  if (isRoleExecutionRetired(from) || isRoleExecutionRetired(to))
    throw new Error("death_ability_grant_invalid");
  const stored = ((
    to.privateState as { deathAbilities?: Record<string, DeathGun> }
  ).deathAbilities ??= {}) as Record<string, DeathGun>;
  // 目标库存 getter 仍在原点；它导致双端退休时，保字典前缀但不装入新枪。
  if (isRoleExecutionRetired(from) || isRoleExecutionRetired(to))
    throw new Error("death_ability_grant_invalid");
  stored[id] = gun;
  counters.set(world, next);
  emit(events, toId, gun, "granted");
  return gun;
}

// 武装先核原 owner 与库存，随后依次写枪的 armedOnNight、证明中的同值，最后发布事实。
export function armDeathGun(
  world: World,
  actorId: number,
  gun: DeathGunReadView,
  night: number,
  events: GameEvent[],
): void {
  if (!Number.isSafeInteger(night) || night < gun.grantedNight)
    throw new Error("death_ability_activation_invalid");
  if (
    !deathGunOwnerCurrent(world, actorId, gun) ||
    gun.armedOnNight !== null ||
    gun.disabled ||
    gun.deathExpired ||
    gun.remaining === 0
  )
    return;
  // 武装是新执行入口；单独查退休，不污染可供已付 pending 提案使用的纯原体谓词。
  if (isRoleExecutionRetired(owners.get(gun)!.role)) return;
  (gun as { armedOnNight: number | null }).armedOnNight = night;
  owners.get(gun)!.armedOnNight = night;
  emit(events, actorId, gun, "armed");
}

export function activeDeathGun(
  world: World,
  actorId: number,
  id: string,
  day: number,
  onDeath = false,
): DeathGunReadView | undefined {
  const gun = findDeathGun(world.getComponent(actorId, COMPONENT.Role), id);
  return gun &&
    deathGunOwnerCurrent(world, actorId, gun, onDeath) &&
    gun.armedOnNight !== null &&
    gun.armedOnNight <= day &&
    gun.remaining === 1 &&
    !gun.disabled &&
    !gun.deathExpired &&
    !isRoleExecutionRetired(owners.get(gun)!.role)
    ? gun
    : undefined;
}

/** 捕获的是原枪／来源字段并延迟核资格，不创建行动许可；剩弹、武装与当前性仍在实际查询时复核。 */
export function captureDeathGun(
  world: World,
  actorId: number,
  gun: DeathGunReadView,
  day: number,
  current: () => boolean,
) {
  const id = gun.id,
    kind = gun.kind,
    source = gun.source,
    sourceKind = source.kind,
    sourceActor = source.actorId,
    sourceId = source.kind === "transfer" ? source.abilityId : undefined;
  const disclosed = gun.sourceDisclosed,
    granted = gun.grantedNight,
    armed = gun.armedOnNight;
  const disabled = gun.disabled,
    expired = gun.deathExpired;
  const isCurrent = () =>
    current() &&
    gun.id === id &&
    gun.kind === kind &&
    gun.source === source &&
    gun.source.kind === sourceKind &&
    gun.source.actorId === sourceActor &&
    (gun.source.kind === "gift" || gun.source.abilityId === sourceId) &&
    gun.sourceDisclosed === disclosed &&
    gun.grantedNight === granted &&
    gun.armedOnNight === armed &&
    gun.disabled === disabled &&
    gun.deathExpired === expired &&
    deathGunOwnerCurrent(world, actorId, gun, true);
  return {
    isCurrent,
    isEligible: () => isCurrent() && activeDeathGun(world, actorId, id, day, true) === gun,
  };
}

// 死亡回调前捕获原枪及发布字段；首次死亡的 version+1 保持枪权，不能提前永久到期。
export function firstDeathGuns(
  world: World,
  actorId: number,
): Array<{
  actorId: number;
  gun: DeathGunReadView;
  id: string;
  grantedNight: number;
  armedOnNight: number | null;
}> {
  return allDeathGuns(world.getComponent(actorId, COMPONENT.Role))
    .filter((gun) => !gun.deathExpired && deathGunOwnerCurrent(world, actorId, gun, true))
    .map((gun) => ({
      actorId,
      gun,
      id: gun.id,
      grantedNight: gun.grantedNight,
      armedOnNight: gun.armedOnNight,
    }));
}

// 外层收尾逐枪依次清剩弹、禁用、标永久到期；事实只用先前捕获字段，失败不回滚已写前缀。
export function finishDeathGuns(
  rows: ReturnType<typeof firstDeathGuns>,
  events: GameEvent[],
): void {
  for (const { actorId, gun, id, grantedNight, armedOnNight } of rows) {
    if (gun.deathExpired) continue;
    (gun as { remaining: 0 | 1 }).remaining = 0;
    (gun as { disabled: boolean }).disabled = true;
    (gun as { deathExpired: boolean }).deathExpired = true;
    emit(
      events,
      actorId,
      { id, grantedNight, armedOnNight, remaining: 0, disabled: true, deathExpired: true },
      "disabled",
      id,
    );
  }
}

export function setDeathGunEnabled(
  world: World,
  actorId: number,
  id: string,
  enabled: boolean,
  events: GameEvent[],
): void {
  const gun = findDeathGun(world.getComponent(actorId, COMPONENT.Role), id);
  if (!gun || !deathGunOwnerCurrent(world, actorId, gun))
    throw new Error("death_ability_instance_unavailable");
  if (enabled && gun.deathExpired) throw new Error("death_ability_expired");
  if (gun.disabled === !enabled) return;
  (gun as { disabled: boolean }).disabled = !enabled;
  emit(events, actorId, gun, enabled ? "enabled" : "disabled");
}

// 先建立接收者新证明／库存，再删源实例、登记退休 ID，最后源转出→目标授予；不直接搬旧对象。
export function transferDeathGun(
  world: World,
  fromId: number,
  toId: number,
  id: string,
  events: GameEvent[],
): DeathGunReadView {
  const source = world.getComponent(fromId, COMPONENT.Role),
    target = world.getComponent(toId, COMPONENT.Role),
    gun = findDeathGun(source, id);
  if (
    !gun ||
    fromId === toId ||
    !deathGunOwnerCurrent(world, fromId, gun) ||
    !target ||
    target.camp !== Camp.Good ||
    !world.getComponent(toId, COMPONENT.Alive)?.alive ||
    allDeathGuns(target).length ||
    (
      (target.privateState as { readonly retiredDeathAbilityIds?: unknown })
        .retiredDeathAbilityIds as string[] | undefined
    )?.includes(id)
  )
    throw new Error("death_ability_transfer_invalid");
  if (isRoleExecutionRetired(source!) || isRoleExecutionRetired(target))
    throw new Error("death_ability_transfer_invalid");
  const received: DeathGun = {
    ...projectDeathGun(gun),
    source: { kind: "transfer", actorId: fromId, abilityId: id },
  };
  delete (received as DeathGun & { status?: string }).status;
  bind(world, toId, received, source!);
  // 复制／绑定的原 getter 后才到目标库存写点；退休双端只拒新转移，不否定已消费枪的原体证明。
  if (isRoleExecutionRetired(source!) || isRoleExecutionRetired(target))
    throw new Error("death_ability_transfer_invalid");
  const targetStored = (
    ((target.privateState as { deathAbilities?: Record<string, DeathGun> }).deathAbilities ??=
      {}) as Record<string, DeathGun>
  );
  // 原目标容器已求值；只在实际实例写入前复验，不回滚此前证明或空字典。
  if (isRoleExecutionRetired(source!) || isRoleExecutionRetired(target))
    throw new Error("death_ability_transfer_invalid");
  targetStored[id] = received;
  delete (
    (source!.privateState as { readonly deathAbilities?: unknown }).deathAbilities as Record<
      string,
      DeathGun
    >
  )[id];
  (
    ((source!.privateState as { retiredDeathAbilityIds?: string[] }).retiredDeathAbilityIds ??=
      []) as string[]
  ).push(id);
  emit(events, fromId, gun, "transferred_out");
  emit(events, toId, received, "granted");
  return received;
}

// 枪目标、生命与行动许可由调用者复核；这里只将原枪剩弹写为 0，不新增授权、复检或事实。
export function consumeDeathGunShot(gun: DeathGunReadView): void {
  (gun as { remaining: 0 | 1 }).remaining = 0;
}

/**
 * 负责 杠精 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { z } from "zod";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { text, roleName } from "@ai-werewolf-arena/game-text";
import {
  COMPONENT,
  Role,
  Camp,
  Phase,
  DEBATER_POLICIES,
  type RoleComponent,
} from "../../../../core/domain";
import type { NativeRoleContributions } from "../contracts";
import { numberOrNull } from "../../llm/helpers";
import { getDebaterState, projectDebaterState, initializeDebaterState } from "./state";
import { debateAuthority, hasDebateCommit } from "./authority";
import { sameOriginalParticipant as sameDebateParticipant } from "../../../../core/domain/original-participant";
const parameters = z.strictObject({
  policy: z.enum(DEBATER_POLICIES).default("awa_melbourne_2026_speech_gap_v1"),
});
export const DEBATER_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    role: Role.Debater,
    camp: Camp.Good,
    goodSide: "god",
    maxCount: 1,
    label: roleName("debater"),
    skillBrief: text("zh-CN", "role.debater.brief"),
    supportedBoardRoles: [
      Role.Debater,
      Role.Wolf,
      Role.Villager,
      Role.Seer,
      Role.Witch,
      Role.Hunter,
      Role.Guard,
      Role.Idiot,
      Role.WolfKing,
      Role.WhiteWolfKing,
      Role.Knight,
    ],
  },
  runtime: {
    init: initializeDebaterState,
    configuration: {
      schema: parameters,
      defaults: { policy: "awa_melbourne_2026_speech_gap_v1" },
      apply: (config, value) => ({ ...config, debater: parameters.parse(value) }),
      serialize: (config) => parameters.parse(config.debater ?? {}),
    },
    toolSpecs: [
      {
        name: "challenge",
        parameters: {
          type: "object",
          properties: { target_id: { type: "integer" } },
          required: ["target_id"],
          additionalProperties: false,
        },
        argHint: 'challenge args: {"target_id":number}',
        userPromptHintKey: "action.challenge.hint",
      },
    ],
    validationRules: {
      challenge: ({ world, actorId, day, phase, toolCall, debateId }) => {
        const a = debateAuthority(world, debateId),
          role = world.getComponent(actorId, COMPONENT.Role),
          state = getDebaterState(role);
        if (toolCall.name !== "challenge") return { code: RuleError.ToolMismatch };
        if (
          role?.role !== Role.Debater ||
          role.camp !== Camp.Good ||
          !a ||
          a.stage !== "challenge" ||
          a.actorId !== actorId ||
          a.day !== day ||
          phase !== Phase.Day ||
          !state ||
          state.remaining !== 1 ||
          state.choice !== null ||
          hasDebateCommit(world, actorId)
        )
          return { code: RuleError.DebateUnavailable };
        if (
          toolCall.args.target_id !== a.targetId ||
          actorId === a.targetId ||
          !a.participants.has(actorId) ||
          !a.participants.has(a.targetId) ||
          !sameDebateParticipant(world, a.participants.get(actorId)!) ||
          !sameDebateParticipant(world, a.participants.get(a.targetId)!)
        )
          return { code: RuleError.DebateTarget };
        return null;
      },
    },
    baselineAction: (_role, request) =>
      request.allowedTools.includes("challenge") && request.context.debate_target_id !== undefined
        ? { name: "challenge", args: { target_id: request.context.debate_target_id } }
        : null,
    llmRepair: {
      coerce: {
        challenge: (args) => {
          const target = numberOrNull(args.target_id);
          return target === null ? null : { target_id: target };
        },
      },
    },
  },
  presentation: nativeRolePresentation("debater"),
};

/**
 * 负责杠精选择数据槽的初始化、描述符读取、库存消耗、选择保存与玩家投影。
 * 输入为原角色／上下文或已由窗口接受的状态和选择；输出保留同一 live 槽、选择引用与独立玩家数据。
 * 初始化先求值赋值左值的容器，再读取政策；读取排除字段访问器但不新增完整 live schema 或 Proxy 零 trap 保证。
 * 窗口拥有原体、辩论提交、局部 choice 与关闭；本族命令仅写原字段，付款或保存失败不撤回此前提交。
 * 玩家投影不替代许可或档案编码，readonly 类型不冻结库存；没有镜像、JSON 身份或新的撤销政策。
 */
import type { DebaterReadState, DebaterState } from "@ai-werewolf-arena/game-contract";
import type { RoleComponent } from "../../../../core/domain/components/role";

import { playerDataField } from "../player-state-data";
import type { RoleInitializationComponent, RoleInitContext } from "../contracts";
export function getDebaterState(role: RoleComponent | undefined): DebaterReadState | undefined {
  return playerDataField(playerDataField(role, "privateState"), "debater") as
    DebaterReadState | undefined;
}
/** 提交标记只使玩家视图的 remaining 归零；不写原槽，选择仅在日期与编号为正整数时输出。 */
export function projectDebaterState(state: DebaterReadState, committed = false) {
  const choice = playerDataField(state, "choice"),
    day = playerDataField(choice, "day"),
    targetId = playerDataField(choice, "targetId");
  return {
    policy: "awa_melbourne_2026_speech_gap_v1" as const,
    remaining:
      !committed && playerDataField(state, "remaining") === 1 ? (1 as const) : (0 as const),
    choice:
      typeof day === "number" &&
      Number.isSafeInteger(day) &&
      day > 0 &&
      typeof targetId === "number" &&
      Number.isSafeInteger(targetId) &&
      targetId > 0
        ? { day, targetId }
        : null,
  };
}

/** 原初始化完整正文：仅槽不存在时安装；政策 getter 或赋值失败照原表达式传播。 */
export function initializeDebaterState(role: RoleInitializationComponent, ctx: RoleInitContext): void {
  if (!getDebaterState(role))
    role.privateState.debater = {
      policy: ctx.boardConfig?.debater?.policy ?? "awa_melbourne_2026_speech_gap_v1",
      remaining: 1,
      choice: null,
    };
}

/** 原辩论提交已记账；只消费捕获状态，不再读取角色或在后续 choice 写入失败时退款。 */
export function consumeDebaterChallenge(state: DebaterReadState): void {
  (state as Pick<DebaterState, "remaining">).remaining = 0;
}

/** 接收窗口已创建的同一 choice 引用；不复制数据、不设置窗口局部值或提交 accepted 标记。 */
export function recordDebaterChoice(state: DebaterReadState, choice: DebaterReadState["choice"]): void {
  (state as Pick<DebaterState, "choice">).choice = choice;
}

/**
 * 负责在原预定发言之前开启辩论机会，并通过本族权威结算公开发言、密封投票和处罚。
 * 输入为当前日次、原参与者、请求构造端口、Provider 与网关；输出辩论事实及是否跳过原发言。
 * Provider 等待之后仍复验原体、生命、库存与警徽；请求构造不授权行动，付款和关闭保持本族原顺序。
 * 本窗口不发布局部匿名票统计；最后复验后同步提交结果、生命绑定处罚和需要的警徽移交。
 */
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import {
  COMPONENT,
  Role,
  Camp,
  Phase,
  type World,
  type ActionProvider,
  type GameEvent,
  type BadgeComponent,
  type VotingRightComponent,
} from "../../../../core/domain";
import { ToolGateway } from "../../../gateway/tool_gateway";
import type { ActionRequestConstructionPort } from "../../../../core/domain/actions";
import { commitSheriffBadgeChoice, badgeSuccessorEligible } from "../../sheriff/badge";
import { getDebaterState, consumeDebaterChallenge, recordDebaterChoice } from "./state";
import {
  openDebate,
  closeDebate,
  hasDebateCommit,
  commitDebate,
  blockDebateVote,
  nextDebateId,
  hasActiveDebate,
  type DebateAuthority,
} from "./authority";
import {
  captureOriginalParticipant as captureDebateParticipant,
  sameOriginalParticipant as sameDebateParticipant,
} from "../../../../core/domain/original-participant";
/** 有限 AWA 适配：原一次预定发言之前依次进行两次公开陈述，再收集密封匿名票。 */
export class DebaterWindow {
  constructor(
    private readonly world: World,
    private readonly gateway: ToolGateway,
    private readonly events: GameEvent[],
  ) {}
  async execute(
    config: ReadonlyBoardConfig,
    requests: ActionRequestConstructionPort,
    provider: ActionProvider,
    targetId: number,
    day: number,
    isCurrent: () => boolean,
  ): Promise<{ skipSpeech: boolean }> {
    if (hasActiveDebate(this.world)) throw new Error("debate_window_reentry");
    const empty = { skipSpeech: false };
    if (!isCurrent()) return empty;
    const actorId = this.world.getEntityIdsByRole(Role.Debater).find((id) => {
      const role = this.world.getComponent(id, COMPONENT.Role),
        state = getDebaterState(role);
      return (
        id !== targetId &&
        role?.camp === Camp.Good &&
        this.world.getAliveEntityIds().includes(id) &&
        state?.remaining === 1 &&
        state.choice === null &&
        !hasDebateCommit(this.world, id)
      );
    });
    if (actorId === undefined) return empty;
    let participants = new Map(
        this.world.getAliveEntityIds().flatMap((id) => {
          const p = captureDebateParticipant(this.world, id);
          return p ? [[id, p] as const] : [];
        }),
      ),
      actor = participants.get(actorId),
      target = participants.get(targetId);
    if (!actor || !target) return empty;
    const state = getDebaterState(actor.role)!,
      policy = state.policy;
    if (policy !== "awa_melbourne_2026_speech_gap_v1") return empty;
    const badgeSnapshot = (id: number) => {
      const badge = this.world.getComponent(id, COMPONENT.Badge),
        vote = this.world.getComponent(id, COMPONENT.VotingRight);
      return {
        id,
        badge,
        vote,
        isSheriff: badge?.isSheriff,
        destroyed: badge?.destroyed,
        weight: badge?.voteWeight,
        handoff: badge?.handoffPolicy,
        canVote: vote?.canVote,
        voteWeight: vote?.weight,
      };
    };
    const badges = [badgeSnapshot(actorId), badgeSnapshot(targetId)];
    const sameBadges = () =>
      badges.every(
        (b) =>
          this.world.getComponent(b.id, COMPONENT.Badge) === b.badge &&
          this.world.getComponent(b.id, COMPONENT.VotingRight) === b.vote &&
          b.badge?.isSheriff === b.isSheriff &&
          b.badge?.destroyed === b.destroyed &&
          b.badge?.voteWeight === b.weight &&
          b.badge?.handoffPolicy === b.handoff &&
          b.vote?.canVote === b.canVote &&
          b.vote?.weight === b.voteWeight,
      );
    const authority: DebateAuthority = {
      id: nextDebateId(this.world, day, actorId, targetId),
      day,
      actorId,
      targetId,
      stage: "challenge",
      participants,
    };
    // accepted 仅在两字段写完后置真；choice 保原对象身份，供等待后的状态复验。
    let accepted = false,
      choice: typeof state.choice = null;
    const current = () =>
      isCurrent() &&
      sameDebateParticipant(this.world, actor) &&
      sameDebateParticipant(this.world, target) &&
      getDebaterState(actor.role) === state &&
      state.policy === policy &&
      state.remaining === (accepted ? 0 : 1) &&
      state.choice === choice &&
      (choice === null || (choice.day === day && choice.targetId === targetId)) &&
      hasDebateCommit(this.world, actorId) === accepted &&
      sameBadges();
    const extras = {
      debate_id: authority.id,
      debate_actor_id: actorId,
      debate_target_id: targetId,
      allow_fallback: false,
    };
    const canceled = () => {
      if (isCurrent())
        this.events.push({
          timestamp: Date.now(),
          type: "debate_canceled",
          payload: { actorId, targetId, day, reason: "scope_changed" },
        });
      return empty;
    };
    openDebate(this.world, authority);
    try {
      const request = requests.create({
        actorId,
        phase: Phase.Day,
        allowedTools: ["challenge"],
        stage: "debate_challenge",
        requiresAction: false,
        summary: { key: "request.summary.debate_challenge", parameters: { target: targetId } },
        context: extras,
      });
      if (!current()) return empty;
      const action = await provider.getAction(request);
      if (!current() || action?.name !== "challenge") return empty;
      const checked = this.gateway.validateAndSanitize(this.world, actorId, action, {
        phase: Phase.Day,
        day,
        debateId: authority.id,
      });
      if (!checked.ok || !current()) return empty;
      participants = new Map(
        this.world.getAliveEntityIds().flatMap((id) => {
          const p = captureDebateParticipant(this.world, id);
          return p ? [[id, p] as const] : [];
        }),
      );
      authority.participants = participants;
      // 提交账本先于库存；局部 choice 在保存槽之前创建，setter 失败时不回滚这些前缀。
      commitDebate(this.world, actorId);
      consumeDebaterChallenge(state);
      choice = { day, targetId };
      recordDebaterChoice(state, choice);
      accepted = true;
      this.events.push(
        { timestamp: Date.now(), type: "debater_revealed", payload: { actorId, day } },
        { timestamp: Date.now(), type: "debate_started", payload: { actorId, targetId, day } },
      );
      authority.stage = "speech";
      for (const speaker of [actorId, targetId]) {
        if (!current()) return canceled();
        const speechRequest = requests.create({
          actorId: speaker,
          phase: Phase.Day,
          allowedTools: ["speak"],
          stage: "debate_speech",
          requiresAction: true,
          summary: { key: "request.summary.debate_speech" },
          context: extras,
        });
        if (!current()) return canceled();
        const speech = await provider.getAction(speechRequest);
        if (!current()) return canceled();
        if (speech?.name !== "speak") continue;
        const valid = this.gateway.validateAndSanitize(this.world, speaker, speech, {
          phase: Phase.Day,
          day,
        });
        if (!current()) return canceled();
        if (valid.ok && valid.sanitizedCall?.name === "speak")
          this.events.push({
            timestamp: Date.now(),
            type: "debate_speech",
            payload: { actorId: speaker, text: valid.sanitizedCall.args.text },
          });
      }
      authority.stage = "ballot";
      // 调用任何 Provider 之前构造完整票轮；中间统计或单人票不会提前发布。
      const ballotRequests = [...participants.keys()].map((voterId) => ({
        voterId,
        request: requests.create({
          actorId: voterId,
          phase: Phase.Day,
          allowedTools: ["debate_vote"],
          stage: "debate_ballot",
          requiresAction: true,
          summary: { key: "request.summary.debate_ballot" },
          context: extras,
        }),
      }));
      if (!current()) return canceled();
      const replies = await Promise.all(
        ballotRequests.map(async ({ voterId, request }) => ({
          voterId,
          call:
            current() && sameDebateParticipant(this.world, participants.get(voterId)!)
              ? await provider.getAction(request)
              : null,
        })),
      );
      if (!current()) return canceled();
      const ballots = replies.map(({ voterId, call }) => {
        const p = participants.get(voterId)!;
        if (!sameDebateParticipant(this.world, p) || call?.name !== "debate_vote")
          return { voterId, support: null };
        const checked = this.gateway.validateAndSanitize(this.world, voterId, call, {
          phase: Phase.Day,
          day,
          debateId: authority.id,
        });
        return {
          voterId,
          support:
            checked.ok &&
            checked.sanitizedCall?.name === "debate_vote" &&
            sameDebateParticipant(this.world, p)
              ? checked.sanitizedCall.args.support
              : null,
        };
      });
      if (!current()) return canceled();
      // 已收票再次逐人复验，另一位玩家的校验可能撤销其原体资格。
      for (const ballot of ballots)
        if (!sameDebateParticipant(this.world, participants.get(ballot.voterId)!))
          ballot.support = null;
      const eligibleCount = participants.size,
        supports = ballots.filter((b) => b.support === true).length,
        rejects = ballots.filter((b) => b.support === false).length,
        abstentions = eligibleCount - supports - rejects,
        success = supports > eligibleCount / 2,
        blockedId = success ? targetId : actorId;
      const targetBadge = this.world.getComponent(targetId, COMPONENT.Badge),
        needsBadge = success && targetBadge?.isSheriff === true && !targetBadge.destroyed;
      if (needsBadge && !badgeSuccessorEligible(this.world, targetId, actorId)) return canceled();
      if (!current()) return canceled();
      // 最后复验之后同步提交结果、绑定原生命的处罚以及需要的警徽移交。
      if (needsBadge)
        commitSheriffBadgeChoice(this.world, targetId, "debate", this.events, actorId);
      blockDebateVote(this.world, blockedId, actorId, day);
      this.events.push(
        {
          timestamp: Date.now(),
          type: "debate_ballots_recorded",
          payload: { actorId, targetId, day, eligibleCount, ballots },
        },
        {
          timestamp: Date.now(),
          type: "debate_resolved",
          payload: {
            actorId,
            targetId,
            day,
            eligibleCount,
            supports,
            rejects,
            abstentions,
            success,
            blockedId,
          },
        },
      );
      return { skipSpeech: success };
    } finally {
      closeDebate(this.world, authority);
    }
