  const writable = () =>
    [
      ...["heal", "poison", "canSelfHeal", "healUsedThisNight", "poisonUsedThisNight"].map(
        (key) => [originalState, key] as const,
      ),
      [ability, "uses"] as const,
      [ability, "lastUsedDay"] as const,
