    !role ||
    !campComponent ||
    !life ||
    !victory ||
    !aliveDescriptor ||
    !actualDescriptor ||
    actualDescriptor.get !== aliveDescriptor.get ||
    actualDescriptor.set !== aliveDescriptor.set ||
    version === undefined ||
    !life.alive ||
    typeof kind !== "string" ||
    !Object.values(Camp).includes(camp as Camp) ||
    data(campComponent, "camp") !== camp ||
    !state ||
    typeof state !== "object" ||
    !Array.isArray(affiliations) ||
