    keys.length === others.length &&
    keys.every(
      (k) =>
        others.includes(k) &&
        fields[k] &&
        Object.hasOwn(fields[k], "value") &&
        fields[k]!.value === a.fields[k]!.value,
    ) &&
    requestData(target) === a.json
