      }
      const chosen = slot === null ? null : scope.cards[slot].card;
      const catalog = getDefaultRoleCatalog();
      const newRole = chosen
        ? createRoleComponent(chosen.role, catalog.getCamp(chosen.role), this.world.locale)
        : null;
      if (newRole)
        catalog.applyRuntime(newRole, {
          boardConfig: config,
          locale: this.world.locale,
          world: this.world,
        });
      const newCamp = newRole ? createCampComponent(newRole.camp, this.world.locale) : null;
      const newVictory = newRole
        ? createVictoryComponent([{ kind: "faction", faction: newRole.camp }])
        : null;
      if (!sameInitialIdentityScope(scope) || delivery.current() !== true) {
        status = "cancelled";
        return false;
      }
      // 物理交换与身份安装之间没有 await、Provider 回调或事件发表。
      if (chosen && slot !== null && newRole && newCamp && newVictory) {
        if (this.kind === "shapeshifter") {
          consumeShapeshifterState(state, slot);
        }
        selectInitialIdentityCard(this.world, actorId, slot);
        // 一旦候选身份开始安装，该核心段失败就永久撤销候选的执行授权；不在 catch 查询 World 或退休旧演员。
        try {
          this.world.addComponent(actorId, COMPONENT.Role, newRole);
          this.world.addComponent(actorId, COMPONENT.Camp, newCamp);
          this.world.addComponent(actorId, COMPONENT.Victory, newVictory);
        } catch (error) {
          retireRoleExecution(newRole);
          throw error;
        }
      } else {
        consumeRetainedInitialIdentityState(state);
        selectInitialIdentityCard(this.world, actorId, null);
      }
      status = "complete";
      closeInitialIdentitySetup(this.world, status);
      scopes.delete(this.world);
      // 物理换牌、全部组件安装与原关闭成功后才落 true；事实／通知晚抛不能再结算 false。
      delivery.complete();
      const data = {
        actorId,
        day: 1 as const,
        role: newRole?.role ?? initialIdentityRole(this.kind),
        camp: newRole?.camp ?? Camp.Good,
      };
      this.events.push(
        this.kind === "shapeshifter"
          ? {
              timestamp: Date.now(),
              type: "shapeshifter_identity_chosen",
              payload: {
                ...data,
                slot: slot!,
                policy: "awa_netease_shapeshifter_two_extra_villagers_v1",
              },
            }
          : {
              timestamp: Date.now(),
              type: "thief_identity_chosen",
              payload: { ...data, slot, policy: "lui_meme_thief_two_extra_villagers_v1" },
            },
      );
      return true;
    } catch (error) {
      failed = true;
      throw error;
    } finally {
      try {
      if (this.kind === "shapeshifter" && status !== "complete") {
        const original =
          scopes.get(this.world)?.state ??
          this.world
            .entityIds()
            .map((id) =>
              getInitialIdentityState(this.world.getComponent(id, COMPONENT.Role), this.kind),
            )
            .find(Boolean);
        cancelShapeshifterState(original);
      }
      scopes.delete(this.world);
      closeInitialIdentitySetup(this.world, status);
      } catch (error) {
        // 原 finally 的清理错误仍按旧 JS 优先于 body 错误；新 false 通知不得覆盖它。
        failed = true;
        throw error;
      } finally {
        if (failed) { try { delivery?.close(); } catch { /* 已有原错误时只完成关闭，保该错误。 */ } }
        else delivery?.close();
      }
    }
  }
}

/**
 * 负责按当前目标角色和运行查验标签形成披露结果。输入为目标编号及阵营／身份／组合查验类型；输出为对应结果或 null。结果不授予行动权限，披露标签可以不同于真实角色和阵营。
 */
import type { InspectionKind, InspectionResult } from "@ai-werewolf-arena/game-contract";
import { COMPONENT } from "../../../core/domain/components/names";
import type { RoleComponent } from "../../../core/domain/components/role";
import type { EntityId } from "../../../core/domain/model";
import type { World } from "../../../core/domain/world";
import type { RoleCatalog } from "./catalog";

/** 只读规则投影，调用此查询不等于取得行动许可。 */
export function resolveInspection<K extends InspectionKind>(
  world: World,
  targetId: EntityId,
  kind: K,
  catalog: RoleCatalog,
): Extract<InspectionResult, { kind: K }> | null {
  const target = world.getComponent(targetId, COMPONENT.Role);
  if (!target) return null;
  const definition = catalog.runtime(target.role)?.inspectionLabels;
  const labels = typeof definition === "function" ? definition(target) : definition;
  const camp = labels?.camp ?? target.camp,
    role = labels?.role ?? target.role;
  const result: InspectionResult =
    kind === "camp" ? { kind, camp } : kind === "role" ? { kind, role } : { kind, camp, role };
  return result as Extract<InspectionResult, { kind: K }>;
}

/**
 * 负责骑士决斗的本族资源消耗、公共事实和死亡提案。输入为原 World、所选编号、阶段与事件数组；
 * 输出为命中／未中提案或 null。按原序核角色、库存、双方存活和目标真实阵营，不以查验伪装代替阵营。
 * 先消费已读取的库存，再发表公共事件，后项失败保已写前缀；不标死、不推进日期或恢复资源。
 * 请求／窗口的原体复验仍由调用方持有，本函数不另建租约或缓存。
 */
import {
  Role,
  Camp,
  Phase,
  DeathCause,
  type KnightDuelSelection,
  type DeathSources,
  type GameEvent,
} from "../../../../core/domain/model";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import type { World } from "../../../../core/domain/world";
import { getKnightState, consumeKnightDuel } from "./state";

/** 只提交一次库存和事实并返回死亡提案；真正的生命写入仍由死亡结算器负责。 */
export function commitKnightDuel(
  world: World,
  choice: KnightDuelSelection,
  phase: Phase,
  events: GameEvent[],
): { deaths: number[]; sources: DeathSources; endsDay: boolean } | null {
  if (phase !== Phase.Day || choice.actorId === choice.targetId) return null;
  const actor = world.getComponent(choice.actorId, COMPONENT.Role),
    target = world.getComponent(choice.targetId, COMPONENT.Role);
  const state = actor ? getKnightState(actor) : undefined;
  if (
    actor?.role !== Role.Knight ||
    state?.canDuel !== true ||
    !target ||
    !world.getComponent(choice.actorId, COMPONENT.Alive)?.alive ||
    !world.getComponent(choice.targetId, COMPONENT.Alive)?.alive
  )
    return null;
  const hit = target.camp === Camp.Wolf;
  // 使用本次已读的同一个槽；资源 setter 失败先于发表，发表失败不退还已付资源。
  consumeKnightDuel(state);
  events.push({
    timestamp: Date.now(),
    type: "knight_duel",
    payload: {
      actorId: choice.actorId,
      targetId: choice.targetId,
      result: hit ? "wolf" : "not_wolf",
    },
  });
  return hit
    ? {
        deaths: [choice.targetId],
        sources: { [choice.targetId]: [DeathCause.Duel] },
        endsDay: true,
      }
    : {
        deaths: [choice.actorId],
        sources: { [choice.actorId]: [DeathCause.DuelFailure] },
        endsDay: false,
      };
}

/**
 * 负责骑士白天决斗的完整选择窗口。输入为板子、原 World、请求构造端口、Provider、网关与提交回调；
 * 输出为原选择和是否结束白天，不在本窗口付款、标死或判胜。
 * 捕获演员和目标的存活组件、生命版本及角色／阵营字段，等待后按原顺序复验同一身体和库存。
 * 多骑士并发请求按编号尝试；网关预检两侧均复验，只有有效候选才要求提交回调。
 * 读取、Provider、网关及提交异常原样传播；已写前缀不回滚，缺少回调和明确 rejected 保留原分支。
 */
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { COMPONENT } from "../../../../core/domain/components/names";
import { AliveComponent, aliveLifeVersion } from "../../../../core/domain/components/alive";
import type { RoleComponent } from "../../../../core/domain/components/role";
import {
  Role,
  Phase,
  KnightDuelWindow as DuelWindow,
  type ActionProvider,
  type KnightDuelSelection,
  type KnightDuelCommit,
} from "../../../../core/domain/model";
import type { World } from "../../../../core/domain/world";
import { ToolGateway } from "../../../gateway/tool_gateway";
import type { ActionRequestConstructionPort } from "../../../../core/domain/actions";
import { getKnightState } from "./state";

/** 本次窗口保留原组件引用与当时字段值；不是可序列化玩家资料，也不授予资源或死亡写权。 */
interface DuelParticipantSnapshot {
  // 生命版本记录活跃身体的变化；仅将 alive 改回 true 不恢复旧选择。
  life: AliveComponent;
  version: ReturnType<typeof aliveLifeVersion>;
  role: RoleComponent;
  // 角色与阵营按原读取点捕获，复验时仍检查同一 Role 对象及这两个字段。
  roleId: Role;
  camp: RoleComponent["camp"];
}

/** 决斗收集保留原提交等待点；真实付款、事实和死亡提案仍归回调与后续经理结算。 */
export class KnightDuelWindow {
  constructor(
    private readonly world: World,
    private readonly gateway: ToolGateway,
  ) {}
  async execute(
    config: ReadonlyBoardConfig,
    requests: ActionRequestConstructionPort,
    provider: ActionProvider,
    window: DuelWindow,
    isCurrent: () => boolean,
    commit?: (choice: KnightDuelSelection) => Promise<KnightDuelCommit>,
  ): Promise<{ selection: KnightDuelSelection | null; endsDay: boolean }> {
    // 原空结果在本次调用内共用；先查当前窗口，再按原配置或默认发言后机会筛选。
    const empty = { selection: null, endsDay: false };
    if (
      !isCurrent() ||
      !(config.knight?.enabledWindows ?? [DuelWindow.AfterSpeeches]).includes(window)
    )
      return empty;
    if (
      !this.world.getAliveEntityIds().some((id) => {
        const role = this.world.getComponent(id, COMPONENT.Role);
        return role?.role === Role.Knight && getKnightState(role)?.canDuel === true;
      })
    )
      return empty;
    // 先确认存在可决斗骑士，再完整捕获存活名单；不提前缓存配置、角色或库存。
    const snapshots = new Map<number, DuelParticipantSnapshot>(
      this.world.getAliveEntityIds().map((id) => {
        const life = this.world.getComponent(id, COMPONENT.Alive)!,
          role = this.world.getComponent(id, COMPONENT.Role)!;
        return [
          id,
          { life, version: aliveLifeVersion(life), role, roleId: role?.role, camp: role?.camp },
        ] as const;
      }),
    );
    // 每个演员在请求前读取同一库存，Promise.all 保持快照名单顺序，不以响应先后提交。
    const picks = await Promise.all(
      [...snapshots].map(async ([actorId, actor]) => {
        const state = actor.role?.role === Role.Knight ? getKnightState(actor.role) : undefined;
        if (state?.canDuel !== true) return null;
        const action = await provider.getAction(
          requests.create({
            phase: Phase.Day,
            actorId,
            allowedTools: ["duel"],
            stage: window,
            requiresAction: false,
            summary: { key: "request.summary.knight_duel" },
            context: { duel_window: window },
          }),
        );
        if (action?.name !== "duel") return null;
        return { actorId, actor, state, action, target: snapshots.get(action.args.target_id) };
      }),
    );
    // 原生命、组件、角色及阵营字段都需匹配；此查询不消费库存，也不修改捕获对象。
    const sameLife = (id: number, snapshot: DuelParticipantSnapshot) =>
      this.world.getComponent(id, COMPONENT.Alive) === snapshot.life &&
      snapshot.life.alive &&
      snapshot.version !== undefined &&
      aliveLifeVersion(snapshot.life) === snapshot.version &&
      this.world.getComponent(id, COMPONENT.Role) === snapshot.role &&
      snapshot.role?.role === snapshot.roleId &&
      snapshot.role?.camp === snapshot.camp;
    for (const pick of picks
      .filter((item): item is NonNullable<typeof item> => item !== null)
      .sort((a, b) => a.actorId - b.actorId)) {
      // 按编号排序后的每次尝试，均在网关前后复验阶段、同一库存和目标生命。
      const valid = () =>
        isCurrent() &&
        sameLife(pick.actorId, pick.actor) &&
        getKnightState(pick.actor.role) === pick.state &&
        pick.state.canDuel &&
        pick.target !== undefined &&
        sameLife(pick.action.args.target_id, pick.target);
      if (
        !valid() ||
        !this.gateway.validateAndSanitize(this.world, pick.actorId, pick.action, {
          phase: Phase.Day,
          duelWindow: window,
          allowKnightDuel: true,
        }).ok ||
        !valid()
      )
        continue;
      // 缺回调只在有效候选处报原错误；rejected 继续下一项，提交抛错不回滚已有写入。
      if (!commit) throw new Error("knight_duel_commit_missing");
      const selection = { actorId: pick.actorId, targetId: pick.action.args.target_id },
        outcome = await commit(selection);
      if (outcome === "rejected") continue;
      return { selection, endsDay: outcome === "night" || outcome === "terminal" };
    }
    return empty;
  }
}

/**
 * 负责孤独少女首夜选择、原参与者／生命与独立 Victory 归属，拥有原关系绑定及窗口时序。
 * 输入为原 World 参与者和首夜请求；输出为已接受选择、捕获目标阵营对应的成员关系及原准备结果。
 * 不变量：仅在原身份／资源仍匹配时提交；关闭或替换参与者使 scope 失效，包括期限别名。
 * 选择不改变演员的 Role／Camp，已选成员关系在双方死亡后仍保留；本模块不新增目标死亡结算。
 * 数据写由槽执行，失败窗口审计保留原授权身份，不读取外来 accessor 或恢复已消耗库存。
 * 请求记录及别名传播归独立公共实例；观察请求或原领域失配后许可不复活；付款/取消仍由本族执行，别名自身损坏不毒原请求。
 */
import type { LonelyGirlReadState } from "@ai-werewolf-arena/game-contract";
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { RequestLease } from "../../../../core/domain/request-lease";
import { copyEventData } from "@ai-werewolf-arena/game-contract";
import {
  COMPONENT,
  Camp,
  Role,
  Phase,
  createVictoryComponent,
  type World,
  type ActionRequest,
  type RoleComponent,
  type CampComponent,
  type VictoryComponent,
} from "../../../../core/domain";
import { aliveLifeVersion, type AliveComponent } from "../../../../core/domain/components/alive";
import { freshLonelyGirlState, getLonelyGirlState, LONELY_GIRL_POLICY, lonelyData,
  consumeLonelyGirlState, cancelLonelyGirlState, projectLonelyGirlData } from "./state-slot";
interface Participant {
  id: number;
  life: AliveComponent;
  version: number;
  alive: PropertyDescriptor;
  role: RoleComponent;
  kind: Role;
  roleCamp: Camp;
  state: RoleComponent["privateState"];
  camp: CampComponent;
  campValue: Camp;
  privateSnapshot: Record<string, unknown>;
}
export interface LonelyGirlBinding {
  world: World;
  actorId: number;
  actor: Participant;
  participants: ReadonlyMap<number, Participant>;
  state: LonelyGirlReadState;
  config: ReadonlyBoardConfig;
  configJson: string;
  victory: VictoryComponent;
  affiliations: VictoryComponent["affiliations"];
  status: "pending" | "active" | "complete" | "failed" | "cancelled";
  choice: LonelyGirlReadState["choice"];
  membership: Camp | null;
  isCurrent: (() => boolean) | null;
}
const bindings = new WeakMap<World, LonelyGirlBinding>(),
  nights = new WeakMap<World, Set<number>>(),
  activeNights = new WeakSet<World>();
/** phase 先于 context 身份的原协议独立保留；不复制选择许可；公共 turn 记录已观察的永久撤权。 */
const requestLease = RequestLease.actorPhaseStageDay<World, LonelyGirlBinding>(
  {
    active: (world) => bindings.get(world),
    owner: (binding) => binding.world,
    actorId: (binding) => binding.actorId,
    phase: () => Phase.Night,
    stage: () => "lonely_girl",
    current: (binding) => validLonelyGirlChoice(binding),
  },
  40,
);
function safeJson(value: unknown): string | null {
  try {
    const p = copyEventData(value);
    return p === null ? null : JSON.stringify(p);
  } catch {
    return null;
  }
}
function capture(world: World, id: number): Participant | null {
  const life = world.getComponent(id, COMPONENT.Alive),
    role = world.getComponent(id, COMPONENT.Role),
    camp = world.getComponent(id, COMPONENT.Camp),
    version = life && aliveLifeVersion(life),
    alive = life && Object.getOwnPropertyDescriptor(life, "alive"),
    kind = lonelyData(role, "role"),
    roleCamp = lonelyData(role, "camp"),
    state = lonelyData(role, "privateState"),
    campValue = lonelyData(camp, "camp");
  if (
    !life ||
    version === undefined ||
    !alive ||
    life.alive !== true ||
    !role ||
    !camp ||
    typeof kind !== "string" ||
    !state ||
    typeof state !== "object" ||
    ![Camp.Good, Camp.Wolf].includes(roleCamp as Camp) ||
    campValue !== roleCamp
  )
    return null;
  return {
    id,
    life,
    version,
    alive,
    role,
    kind: kind as Role,
    roleCamp: roleCamp as Camp,
    state: state as RoleComponent["privateState"],
    camp,
    campValue: campValue as Camp,
    privateSnapshot: structuredClone(state) as Record<string, unknown>,
  };
}
function same(world: World, p: Participant): boolean {
  const d = Object.getOwnPropertyDescriptor(p.life, "alive");
  return (
    world.getComponent(p.id, COMPONENT.Alive) === p.life &&
    aliveLifeVersion(p.life) === p.version &&
    !!d &&
    d.get === p.alive.get &&
    d.set === p.alive.set &&
    d.value === p.alive.value &&
    p.life.alive === true &&
    world.getComponent(p.id, COMPONENT.Role) === p.role &&
    lonelyData(p.role, "role") === p.kind &&
    lonelyData(p.role, "camp") === p.roleCamp &&
    lonelyData(p.role, "privateState") === p.state &&
    world.getComponent(p.id, COMPONENT.Camp) === p.camp &&
    lonelyData(p.camp, "camp") === p.campValue
  );
}
export function installLonelyGirl(world: World, config: ReadonlyBoardConfig): void {
  if (bindings.has(world)) throw new Error("lonely_girl_already_installed");
  const actorId = world
    .entityIds()
    .find((id) => lonelyData(world.getComponent(id, COMPONENT.Role), "role") === Role.LonelyGirl);
  if (actorId === undefined) return;
  const participants = new Map(world.entityIds().map((id) => [id, capture(world, id)] as const)),
    actor = participants.get(actorId),
    state = getLonelyGirlState(actor?.role),
    victory = world.getComponent(actorId, COMPONENT.Victory),
    affiliations = lonelyData(victory, "affiliations"),
    configJson = safeJson(config);
  if (
    !actor ||
    !state ||
    !victory ||
    !Array.isArray(affiliations) ||
    safeJson(affiliations) !== "[]" ||
    !configJson ||
    [...participants.values()].some((p) => !p)
  )
    throw new Error("lonely_girl_initial_state_invalid");
  bindings.set(world, {
    world,
    actorId,
    actor,
    participants: participants as Map<number, Participant>,
    state,
    config,
    configJson,
    victory,
    affiliations,
    status: "pending",
    choice: null,
    membership: null,
    isCurrent: null,
  });
}
export function lonelyGirlBinding(world: World): LonelyGirlBinding | undefined {
  return bindings.get(world);
}
function pendingOwner(b: LonelyGirlBinding): boolean {
  const rem = Object.getOwnPropertyDescriptor(b.state, "remaining"),
    choice = Object.getOwnPropertyDescriptor(b.state, "choice");
  return (
    bindings.get(b.world) === b &&
    b.participants.size === b.world.entityIds().length &&
    [...b.participants.values()].every((p) => same(b.world, p)) &&
    b.actor.kind === Role.LonelyGirl &&
    b.actor.roleCamp === Camp.Good &&
    getLonelyGirlState(b.actor.role) === b.state &&
    rem?.value === 1 &&
    rem.writable === true &&
    choice?.value === null &&
    choice.writable === true &&
    b.world.getComponent(b.actorId, COMPONENT.Victory) === b.victory &&
    lonelyData(b.victory, "affiliations") === b.affiliations &&
    safeJson(b.affiliations) === "[]" &&
    safeJson(b.config) === b.configJson
  );
}
export function lonelyGirlReady(world: World): boolean {
  const b = bindings.get(world);
  return b
    ? b.status === "complete"
    : !world
        .entityIds()
        .some(
          (id) => lonelyData(world.getComponent(id, COMPONENT.Role), "role") === Role.LonelyGirl,
        );
}
export function hasActiveLonelyGirl(world: World): boolean {
  return bindings.get(world)?.status === "active" || activeNights.has(world);
}
export function hasLonelyGirlNightCommit(world: World, day: number): boolean {
  return nights.get(world)?.has(day) ?? false;
}
export function openLonelyGirlChoice(b: LonelyGirlBinding, isCurrent: () => boolean): boolean {
  if (b.status !== "pending") throw new Error("lonely_girl_setup_unavailable");
  b.status = "active";
  b.isCurrent = isCurrent;
  return validLonelyGirlChoice(b);
}
export function validLonelyGirlChoice(b: LonelyGirlBinding): boolean {
  return b.status === "active" && b.isCurrent?.() === true && pendingOwner(b);
}
export function authorizedLonelyGirl(
  world: World,
  actorId: number,
  day: number | undefined,
  phase: Phase,
  scope: object | undefined,
): boolean {
  const b = bindings.get(world);
  return (
    !!b &&
    b === scope &&
    b.actorId === actorId &&
    day === 1 &&
    phase === Phase.Night &&
    validLonelyGirlChoice(b)
  );
}
export function bindLonelyGirlRequest(world: World, request: ActionRequest): void {
  requestLease.bind(world, request);
}
export function lonelyGirlRequestScope(
  world: World,
  request: ActionRequest,
): LonelyGirlBinding | undefined {
  return requestLease.scope(world, request);
}
/** 仅本族真实窗口打开交付，原 scope/资源仍由当前生命周期唯一复验。 */
export function openLonelyGirlRequestDelivery(world: World, request: ActionRequest) {
