export const MECHANICAL_WOLF_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    ...ORDINARY_WOLF_CONTRIBUTIONS.metadata,
    role: Role.MechanicalWolf,
    camp: Camp.Wolf,
    maxCount: 1,
    supportedBoardRoles: [
      Role.Wolf,
      Role.Psychic,
      Role.Witch,
      Role.Hunter,
      Role.Guard,
      Role.Villager,
      Role.MechanicalWolf,
    ],
    label: roleName("mechanical_wolf"),
    skillBrief: text("zh-CN", "role.mechanical_wolf.brief"),
  },
  runtime: {
    ...ORDINARY_WOLF_CONTRIBUTIONS.runtime,
    canSelfDestruct: false,
    init: (role) => {
      if (!getMechanicalState(role)) setMechanicalState(role, freshMechanicalState());
    },
    wolfTeam: (role, world) => ({
      recognizedByPack: false,
      recognizes: "none",
      canChat: false,
      canVoteForKill: canMechanicalKnife(role, world),
    }),
    inspectionLabels: (role) => ({
      camp: Camp.Wolf,
      role: getMechanicalState(role)?.learned?.role ?? Role.MechanicalWolf,
    }),
    configuration: {
      schema: z.strictObject({}),
      defaults: {},
      apply: (config) => config,
      serialize: () => ({}),
    },
    toolSpecs: [
      ...ORDINARY_WOLF_CONTRIBUTIONS.runtime.toolSpecs!.filter((spec) => spec.name === "kill_vote"),
      ...MECHANICAL_TOOL_SPECS,
      ...DEATH_SHOT_TOOL_SPECS,
    ],
    nightStages: [...MECHANICAL_NIGHT_STAGES, ...ORDINARY_WOLF_CONTRIBUTIONS.runtime.nightStages!],
    validationRules: {
      ...ORDINARY_WOLF_CONTRIBUTIONS.runtime.validationRules,
      ...MECHANICAL_VALIDATION_RULES,
      shoot: (ctx) => {
        const skill = getMechanicalState(ctx.role)?.learned?.skill;
        return validateDeathShot(
          ctx,
          ctx.role.role === Role.MechanicalWolf &&
            skill?.kind === "hunter" &&
            skill.armed &&
            skill.canShoot,
        );
      },
    },
    deathHook: mechanicalDeathHook,
    llmRepair: {
      coerce: {
        ...ORDINARY_WOLF_CONTRIBUTIONS.runtime.llmRepair?.coerce,
        ...DEATH_SHOT_REPAIR.coerce,
        ...Object.fromEntries(
          [
            "mimic_role",
            "mechanical_inspect",
            "mechanical_poison",
            "mechanical_guard",
            "mechanical_attack",
          ].map((name) => [
            name,
            (args: Record<string, unknown>) => {
              if (
                args.target_id === null &&
                ["mechanical_guard", "mechanical_attack"].includes(name)
              )
                return { target_id: null };
              const target = numberOrNull(args.target_id);
              return target === null ? null : { target_id: target };
            },
          ]),
        ),
      },
    },
    baselineAction: (role, request, pick, byCamp, locale, world) => {
      if (request.allowedTools.includes("mechanical_mode")) {
        const state = getMechanicalState(role);
        return {
          name: "mechanical_mode",
          args: {
            mode:
              state?.hasInheritedKnife &&
              state.firstKnifeNight !== null &&
              state.firstKnifeNight <= request.context.day
                ? "kill"
                : "skill",
          },
        };
      }
      if (request.allowedTools.includes("mimic_role")) {
        const target = pick();
        return target === null ? null : { name: "mimic_role", args: { target_id: target } };
      }
      if (request.allowedTools.includes("mechanical_inspect")) {
        const target = pick();
        return target === null ? null : { name: "mechanical_inspect", args: { target_id: target } };
      }
      if (request.allowedTools.includes("mechanical_poison")) {
        const target = byCamp("good");
        return target === null ? null : { name: "mechanical_poison", args: { target_id: target } };
      }
      if (request.allowedTools.includes("mechanical_guard"))
        return { name: "mechanical_guard", args: { target_id: pick() } };
      if (request.allowedTools.includes("mechanical_attack"))
        return { name: "mechanical_attack", args: { target_id: byCamp("good") } };
      if (request.allowedTools.includes("shoot"))
        return { name: "shoot", args: { target_id: byCamp("good") } };
      return ORDINARY_WOLF_CONTRIBUTIONS.runtime.baselineAction!(role, request, pick, byCamp, locale, world);
    },
  },
  presentation: nativeRolePresentation("mechanical_wolf"),
};

/**
 * 负责机械狼工具的本夜模式与行动资格校验。输入为原工具参数、角色状态及可信上下文，输出原规则拒绝或通过。
 * 预检不等于复制、付款或落效果，原体与能力资源仍由机械机制持有并在提交时复验。
 */
import { MECHANICAL_TOOL_NAMES } from "./tool_names";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { Camp, Role, Phase } from "../../../../core/domain/model";
import type { ToolRule, ToolRuleMap } from "../../validation/contracts";
import { isAliveTarget } from "../../validation/contracts";
import { canMechanicalKnife } from "./inheritance";
import { hasCurrentMechanicalMode } from "./night_scope";
import {
  canMechanicalMimic,
  canSelectMechanicalMode,
  canMechanicalExtraKnife,
  getMechanicalState,
  mechanicalSkillForNight,
} from "./state";

const validateMechanical: ToolRule = ({ world, actorId, role, day, phase, toolCall }) => {
  const state = getMechanicalState(role);
  if (role.role !== Role.MechanicalWolf || role.camp !== Camp.Wolf || !state || day === undefined)
    return { code: RuleError.MechanicalUnavailable };
  if (phase !== Phase.Night) return { code: RuleError.AbilityPhase };
  if (toolCall.name === "mechanical_mode") {
    return canSelectMechanicalMode(state, day) && ["kill", "skill"].includes(toolCall.args.mode)
      ? null
      : { code: RuleError.MechanicalUnavailable };
  }
  if (toolCall.name === "mimic_role") {
    if (!canMechanicalMimic(state, day)) return { code: RuleError.MechanicalUnavailable };
    return toolCall.args.target_id !== actorId && isAliveTarget(world, toolCall.args.target_id)
      ? null
      : { code: RuleError.MechanicalTarget };
  }
  if (toolCall.name === "mechanical_attack") {
    if (!canMechanicalKnife(role, world) || !canMechanicalExtraKnife(state, day))
      return { code: RuleError.MechanicalUnavailable };
    return toolCall.args.target_id === null || isAliveTarget(world, toolCall.args.target_id)
      ? null
      : { code: RuleError.MechanicalTarget };
  }
  const skill = hasCurrentMechanicalMode(world, role, "skill")
    ? mechanicalSkillForNight(state, day)
    : undefined;
  if (toolCall.name === "mechanical_inspect" && skill?.kind === "inspection") {
    return toolCall.args.target_id !== actorId && isAliveTarget(world, toolCall.args.target_id)
      ? null
      : { code: RuleError.MechanicalTarget };
  }
  if (toolCall.name === "mechanical_poison" && skill?.kind === "poison" && skill.remaining > 0) {
    return isAliveTarget(world, toolCall.args.target_id)
      ? null
      : { code: RuleError.MechanicalTarget };
  }
  if (toolCall.name === "mechanical_guard" && skill?.kind === "guard") {
    // 连续守护同编号仍是合法提交；惩罚在黎明生效，不能在预检阶段代付或拒绝。
    return toolCall.args.target_id === null || isAliveTarget(world, toolCall.args.target_id)
      ? null
      : { code: RuleError.MechanicalTarget };
  }
  return { code: RuleError.MechanicalUnavailable };
};

export { MECHANICAL_TOOL_NAMES } from "./tool_names";
export const MECHANICAL_VALIDATION_RULES: ToolRuleMap = Object.fromEntries(
  MECHANICAL_TOOL_NAMES.map((name) => [name, validateMechanical]),
);

/**
 * 负责奇迹商人从实际库存选择赠予。输入为当前原体和已验证的技能／收货选择；
 * 输出为实际拥有的赠予、反噬提案和跳过／提交事实。已付提案保留原生命资格，不转给替换赠予者。
 */
import { closeMerchantTrade, recordMerchantTrade } from "./state";

import type { MiracleSkill } from "@ai-werewolf-arena/game-contract";

import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Camp, Role, Phase, WitchSelfHealRule } from "../../../../core/domain/model";
import { captureNightLife, livingNightLife } from "../../../../core/domain/night_effects";
import type { World } from "../../../../core/domain/world";
import type { NightStageHandler } from "../../stages/night/contracts";
import { grantNightAbility } from "../night-ability-grants";
import { canMerchantTrade, getMerchantState } from "./state";

const committed = new WeakMap<World, Set<number>>();
export function hasMerchantNightCommit(world: World, day: number): boolean {
  return committed.get(world)?.has(day) ?? false;
}
function recordCommit(world: World, day: number): void {
  const days = committed.get(world) ?? new Set<number>();
  days.add(day);
  committed.set(world, days);
}

export const MIRACLE_MERCHANT_STAGE: NightStageHandler = {
  id: "miracle_merchant",
  priority: 125,
  async execute(ctx) {
    const day = ctx.currentDay();
    for (const actorId of ctx.getAliveByRole(Role.MiracleMerchant)) {
      const role = ctx.world.getComponent(actorId, COMPONENT.Role)!,
        state = getMerchantState(role),
        life = captureNightLife(ctx.world, actorId);
      if (!state || !life || role.camp !== Camp.Good) continue;
      const privateState = role.privateState;
      const ownerCurrent = () =>
        ctx.isCurrent() &&
        ctx.world.getComponent(actorId, COMPONENT.Role) === role &&
        role.role === Role.MiracleMerchant &&
        role.camp === Camp.Good &&
        role.privateState === privateState &&
        getMerchantState(role) === state &&
        livingNightLife(ctx.world, life);
      const current = () => ownerCurrent() && canMerchantTrade(state, day);
      if (!current()) continue;
      let completed = false;
      for (let attempt = 0; attempt < 3; attempt++) {
        if (!current()) break;
        const targets = new Map(
          ctx.world
            .getAliveEntityIds()
            .filter((id) => id !== actorId)
            .map((id) => {
              const targetRole = ctx.world.getComponent(id, COMPONENT.Role)!;
              return [
                id,
                {
                  life: captureNightLife(ctx.world, id)!,
                  role: targetRole,
                  kind: targetRole.role,
                  camp: targetRole.camp,
                  privateState: targetRole.privateState,
                },
              ] as const;
            }),
        );
        const action = targets.size
          ? await ctx.actionProvider.getAction(
              ctx.makeRequest(actorId, ["bestow_ability"], {
                stage: "miracle_merchant",
                requiresAction: false,
                ...(attempt ? { retry_attempt: attempt, retry_max: 2 } : {}),
              }),
            )
          : null;
        if (!current()) break;
        if (action === null) {
          closeMerchantTrade(state, day);
          recordCommit(ctx.world, day);
          ctx.events.push({
            timestamp: Date.now(),
            type: "merchant_trade_skipped",
            payload: { actorId, day },
          });
          completed = true;
          break;
        }
        if (action.name !== "bestow_ability") continue;
        const valid = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
          phase: Phase.Night,
          day,
        });
        if (!current() || !valid.ok || valid.sanitizedCall?.name !== "bestow_ability") continue;
        const { target_id: targetId, skill } = valid.sanitizedCall.args,
          target = targets.get(targetId);
        if (
          !target ||
          !livingNightLife(ctx.world, target.life) ||
          ctx.world.getComponent(targetId, COMPONENT.Role) !== target.role ||
          target.role.role !== target.kind ||
          target.role.camp !== target.camp ||
          target.role.privateState !== target.privateState
        )
          continue;
        const failure = target.camp === Camp.Wolf;
        if (!failure) {
          const base = {
            id: "gift:miracle",
            activation: "lucky" as const,
            source: { kind: "gift" as const, actorId },
            sourceDisclosed: false,
            startsOnDay: day,
            maxUses: 1,
          };
          if (skill === "check")
            grantNightAbility(
              ctx.world,
              targetId,
              {
                ...base,
                kind: "seer_check",
                state: { lastTarget: null, lastIsWerewolf: null, lastResult: null, history: [] },
              },
              ctx.events,
            );
          if (skill === "guard")
            grantNightAbility(
              ctx.world,
              targetId,
              { ...base, kind: "guard", state: { lastTarget: null } },
              ctx.events,
            );
          if (skill === "poison")
            grantNightAbility(
              ctx.world,
              targetId,
              {
                ...base,
                kind: "potion",
                state: {
                  heal: 0,
                  poison: 1,
                  selfHealRule: WitchSelfHealRule.Disabled,
                  canSelfHeal: false,
                  healUsedThisNight: false,
                  poisonUsedThisNight: false,
                },
              },
              ctx.events,
            );
        }
        recordMerchantTrade(state, day, targetId, skill as MiracleSkill);
        recordCommit(ctx.world, day);
        if (failure)
          (ctx.state.merchantBacklashes ??= []).push({ target: life, isCurrent: ownerCurrent });
        ctx.events.push({
          timestamp: Date.now(),
          type: "merchant_trade_committed",
          payload: { actorId, day, targetId, skill },
        });
        ctx.events.push({
          timestamp: Date.now(),
          type: "merchant_trade_resolved",
          payload: { actorId, day, targetId, skill, outcome: failure ? "backlash" : "granted" },
        });
        completed = true;
        break;
      }
      if (!completed && current()) throw new Error("merchant_valid_action_missing");
    }
  },
};

/**
 * 负责 奇迹商人 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { z } from "zod";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { text, roleName } from "@ai-werewolf-arena/game-text";
import { Camp, Role, Phase } from "../../../../core/domain/model";
import type { NativeRoleContributions } from "../contracts";
import { isAliveTarget } from "../../validation/contracts";
import { numberOrNull } from "../../llm/helpers";
import {
  getMerchantState,
  freshMerchantState,
  setMerchantState,
  projectMerchantState,
  canMerchantTrade,
} from "./state";
import { MIRACLE_MERCHANT_STAGE } from "./night_stage";
import { LUCKY_ABILITY_STAGE } from "./lucky_stage";

export const MIRACLE_MERCHANT_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    role: Role.MiracleMerchant,
    camp: Camp.Good,
    goodSide: "god",
    maxCount: 1,
    label: roleName("miracle_merchant"),
    skillBrief: text("zh-CN", "role.miracle_merchant.brief"),
    supportedBoardRoles: [
      Role.CursedFox,
      Role.MiracleMerchant,
      Role.Wolf,
      Role.WolfKing,
      Role.HiddenWolf,
      Role.Seer,
      Role.Witch,
      Role.Guard,
      Role.Hunter,
      Role.Dreamer,
      Role.Villager,
    ],
  },
  runtime: {
    init: (role) => {
      if (!getMerchantState(role)) setMerchantState(role, freshMerchantState());
    },
    configuration: {
      schema: z.strictObject({}),
      defaults: {},
      apply: (config) => config,
      serialize: () => ({}),
    },
    nightStages: [MIRACLE_MERCHANT_STAGE, LUCKY_ABILITY_STAGE],
    possibleNightAbilities: ["seer_check", "potion", "guard"],
    toolSpecs: [
      {
        name: "bestow_ability",
        parameters: {
          type: "object",
          properties: {
            target_id: { type: "integer" },
            skill: { type: "string", enum: ["check", "poison", "guard"] },
          },
          required: ["target_id", "skill"],
          additionalProperties: false,
        },
        argHint: 'bestow_ability args: {"target_id":number,"skill":"check"|"poison"|"guard"}',
        userPromptHintKey: "action.bestow_ability.hint",
      },
    ],
    validationRules: {
      bestow_ability: ({ world, actorId, role, day, phase, toolCall }) => {
        const state = getMerchantState(role);
        if (
          role.role !== Role.MiracleMerchant ||
          role.camp !== Camp.Good ||
          !state ||
          day === undefined ||
          !canMerchantTrade(state, day)
        )
          return { code: RuleError.MerchantUnavailable };
        if (phase !== Phase.Night) return { code: RuleError.AbilityPhase };
        if (toolCall.name !== "bestow_ability") return { code: RuleError.ToolMismatch };
        if (!["check", "poison", "guard"].includes(toolCall.args.skill))
          return { code: RuleError.MerchantSkill };
        if (toolCall.args.target_id === actorId || !isAliveTarget(world, toolCall.args.target_id))
          return { code: RuleError.MerchantTarget };
        return null;
      },
    },
    llmRepair: {
      coerce: {
        bestow_ability: (args) => {
          const target = numberOrNull(args.target_id);
          return target === null ? null : { target_id: target, skill: args.skill };
        },
      },
    },
    baselineAction: (_role, request, pick) => {
      if (!request.allowedTools.includes("bestow_ability")) return null;
      const target = pick();
      return target === null
        ? null
        : { name: "bestow_ability", args: { target_id: target, skill: "check" } };
    },
  },
  presentation: nativeRolePresentation("miracle_merchant"),
};

/**
 * 负责炼金魔女／狼鸦之爪的原角色、阵营、身份与生命授权，输入为 World、参与者和夜序。
 * 输出为原当前性检查、脱离知识与经授权的雾／蛇／额外刀提交；资源绑定及槽写入归 state-slot。
 * 不变量：原体、身份或生命撤权后禁止新付款；原首次死亡仅可读取已付款效果／保留知识。
 * 夜初 ravenChecked 先写再转换，后续失败不重开检查；不修补被替换的槽或重复保存库存。
 */
import { types } from "node:util";
import { COMPONENT } from "../../../../core/domain/components/names";
import {
  aliveLifeDescriptor,
  aliveLifeVersion,
  type AliveComponent,
} from "../../../../core/domain/components/alive";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Camp } from "../../../../core/domain/identity";
import type { World } from "../../../../core/domain/world";
import {
  readMistOwnData as own,
  selectMist,
  selectSnake,
  selectRavenKnife,
  unsealRaven,
  type AlchemistState,
  type RavenState,
} from "./state";

import { MistCasterStateSlot, type MistCasterKind as Caster, type MistCasterState as State } from "./state-slot";

/** 外层夜 owner 提供日次、目标与阶段作用域；本授权只保原参与者／生命，状态写权不反向拥有阶段。 */
export class MistCasterAuthority {
  private readonly role: RoleComponent;
  private readonly privateState: RoleComponent["privateState"];
  private readonly identity: unknown;
  private readonly identityFields: unknown[];
  private readonly life: AliveComponent;
  private readonly lifeVersion: number;
  private readonly camp: Camp;
  private readonly campComponent: unknown;
  private readonly key: "alchemist" | "ravenClaw";
  private readonly stateSlot: MistCasterStateSlot;
  private ravenChecked = false;

  constructor(
    private readonly world: World,
    readonly actorId: number,
    readonly day: number,
    readonly caster: Caster,
  ) {
    if (
      !Number.isSafeInteger(day) ||
      day < 1 ||
      day >= Number.MAX_SAFE_INTEGER ||
      !Number.isSafeInteger(actorId) ||
      actorId < 1 ||
      actorId >= Number.MAX_SAFE_INTEGER ||
      (caster !== "alchemist" && caster !== "raven_claw_wolf")
    )
      throw new Error("mist_caster_authority_invalid");
    const role = world.getComponent(actorId, COMPONENT.Role),
      campComponent = world.getComponent(actorId, COMPONENT.Camp),
      identity = world.getComponent(actorId, COMPONENT.Identity),
      life = world.getComponent(actorId, COMPONENT.Alive);
    this.camp = caster === "alchemist" ? Camp.Good : Camp.Wolf;
    this.key = caster === "alchemist" ? "alchemist" : "ravenClaw";
    if (
      !role ||
      own(role, "role") !== caster ||
      own(role, "camp") !== this.camp ||
      own(campComponent, "camp") !== this.camp ||
      !life ||
      !this.factoryLife(life) ||
      !life.alive ||
      aliveLifeVersion(life) === undefined ||
      own(identity, "id") !== actorId ||
      typeof own(identity, "name") !== "string" ||
      typeof own(identity, "sessionId") !== "string" ||
      !Number.isSafeInteger(own(identity, "seat"))
    )
      throw new Error("mist_caster_authority_invalid");
    const privateState = own(role, "privateState");
    if (
      !privateState ||
      typeof privateState !== "object" ||
      types.isProxy(privateState) ||
      Array.isArray(privateState)
    )
      throw new Error("mist_caster_authority_invalid");
    this.role = role;
    this.campComponent = campComponent;
    this.privateState = privateState as RoleComponent["privateState"];
    this.identity = identity;
    this.identityFields = ["id", "seat", "name", "sessionId"].map((k) => own(identity, k));
    this.life = life;
    this.lifeVersion = aliveLifeVersion(life)!;
    // 原字段已赋值后才读取槽并建立绑定；查询 thunk 保持 caster／容器／key 在原调用点晚读。
    this.stateSlot = new MistCasterStateSlot(
      { caster: () => this.caster, privateState: () => this.privateState, key: () => this.key, assertCurrent: () => this.current() },
      own(privateState, this.key),
    );
  }

  private factoryLife(life: AliveComponent): boolean {
    const expected = aliveLifeDescriptor(life);
    if (!expected) return false;
    const d = Object.getOwnPropertyDescriptor(life, "alive");
    return (
      !!d &&
      d.get === expected.get &&
      d.set === expected.set &&
      d.enumerable === expected.enumerable &&
      d.configurable === expected.configurable
