/**
 * 负责原生能力实例在本夜的蚀日抑制；输入原 World／能力／日次，输出同一 marker 与原体复验／关闭方法。
 * marker 只写原实例所属槽，持有运行引用不等于玩家数据或新的行动许可；永久 disabled 仍归原能力所有者。
 * 角色、生命、能力与政策被替换后不重新授权；close 先消费 closed，再核原资源与 marker，失败不恢复无关组件。
 * 允许第一次实际死亡的关闭仍只删除同一 marker，不退款、清空库存或改写原永久禁用字段。
 */
import type { EclipseSuppression } from "@ai-werewolf-arena/game-contract";

import { types } from "node:util";
import { COMPONENT } from "../../../../core/domain/components/names";

import {
  aliveLifeDescriptor,
  type AliveComponent,
  aliveLifeVersion,
} from "../../../../core/domain/components/alive";
import { captureNightLife } from "../../../../core/domain/night_effects";
import type { World } from "../../../../core/domain/world";
import type { NightAbilityReadView } from "../abilities";
import { RADIANT_ECLIPSE_POLICY } from "./state-data";

export type SuppressibleAbility = NightAbilityReadView;
const invalid = Symbol("invalid_eclipse_binding");
function own(value: unknown, key: PropertyKey): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return invalid;
  const field = Object.getOwnPropertyDescriptor(value, key);
  return field && "value" in field ? field.value : field ? invalid : undefined;
}

function plain(value: unknown): value is object {
  if (!value || typeof value !== "object" || types.isProxy(value) || Array.isArray(value))
    return false;
  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
}
function factoryLife(value: AliveComponent | undefined): value is AliveComponent {
  if (!plain(value)) return false;
  const original = aliveLifeDescriptor(value as AliveComponent),
    actual = Object.getOwnPropertyDescriptor(value, "alive");
  return (
    !!original &&
    !!actual &&
    original.get === actual.get &&
    original.set === actual.set &&
    original.enumerable === actual.enumerable &&
    original.configurable === actual.configurable
  );
}
function canonicalSlot(value: object, key: string, expected: unknown): boolean {
  const field = Object.getOwnPropertyDescriptor(value, key);
  return (
    !!field &&
    "value" in field &&
    field.value === expected &&
    field.enumerable === true &&
    field.configurable === true &&
    field.writable === true
  );
}

/** 一个原生实例的临时抑制；永久 disabled 继续由现有能力所有者管理，不在这里改写。 */
export function openEclipseSuppression(
  world: World,
  actorId: number,
  ability: SuppressibleAbility,
  day: number,
) {
  const role = world.getComponent(actorId, COMPONENT.Role);
  const originalLife = world.getComponent(actorId, COMPONENT.Alive);
  if (!factoryLife(originalLife)) throw new Error("eclipse_native_suppression_invalid");
  const life = captureNightLife(world, actorId);
  const privateState = own(role, "privateState"),
    container = own(privateState, "abilities");
  const id = own(ability, "id"),
    kind = own(ability, "kind"),
    state = own(ability, "state"),
    source = own(ability, "source");
  const roleKind = own(role, "role"),
    camp = own(role, "camp");
  const identity = world.getComponent(actorId, COMPONENT.Identity);
  const identityFields = ["id", "seat", "name", "sessionId"] as const;
  const identityValues = identityFields.map((key) => own(identity, key));
  const disabled = own(ability, "disabled");
  if (
    !role ||
    !plain(ability) ||
    !plain(privateState) ||
    !plain(container) ||
    !plain(state) ||
    !plain(source) ||
    !life ||
    !Number.isSafeInteger(day) ||
    day < 2 ||
    typeof id !== "string" ||
    !id.startsWith("native:") ||
    own(container, id) !== ability ||
    own(source, "kind") !== "native" ||
    own(source, "role") !== roleKind ||
    own(ability, "nightSuppression") !== undefined ||
    typeof disabled !== "boolean" ||
    [privateState, container, kind, state, source, roleKind, camp, ...identityValues].includes(
      invalid,
    ) ||
    !identity
  )
    throw new Error("eclipse_native_suppression_invalid");
  const marker: EclipseSuppression = { policy: RADIANT_ECLIPSE_POLICY, day };
  Object.defineProperty(ability, "nightSuppression", {
    value: marker,
    writable: true,
    enumerable: true,
    configurable: true,
  });
  let closed = false;
  const sameResource = (allowFirstDeath = false) => {
    if (
      world.getComponent(actorId, COMPONENT.Role) !== role ||
      own(role, "privateState") !== privateState ||
      own(privateState, "abilities") !== container ||
      own(container, id) !== ability ||
      world.getComponent(actorId, COMPONENT.Alive) !== life.life
    )
      return false;
    const original = aliveLifeDescriptor(life.life),
      current = Object.getOwnPropertyDescriptor(life.life, "alive");
    if (
      !original ||
      !current ||
      current.get !== original.get ||
      current.set !== original.set ||
      current.configurable !== original.configurable ||
      current.enumerable !== original.enumerable
    )
      return false;
    const version = aliveLifeVersion(life.life);
    return (
      (version === life.version && life.life.alive) ||
      (allowFirstDeath && version === life.version + 1 && !life.life.alive)
    );
  };
  const sameInstance = () =>
    sameResource() &&
    plain(ability) &&
    plain(privateState) &&
    plain(container) &&
    plain(state) &&
    plain(source) &&
    own(role, "role") === roleKind &&
    own(role, "camp") === camp &&
    own(ability, "id") === id &&
    own(ability, "kind") === kind &&
    own(ability, "state") === state &&
    own(ability, "source") === source &&
    own(source, "kind") === "native" &&
    own(source, "role") === roleKind &&
    world.getComponent(actorId, COMPONENT.Identity) === identity &&
    identityFields.every((key, index) => own(identity, key) === identityValues[index]);
  return {
    actorId,
    day,
    ability,
    marker: marker as Readonly<EclipseSuppression>,
    isCurrent: () =>
      !closed &&
      sameInstance() &&
      own(ability, "disabled") === disabled &&
      canonicalSlot(ability, "nightSuppression", marker) &&
      Object.getPrototypeOf(marker) === Object.prototype &&
      Reflect.ownKeys(marker).length === 2 &&
      canonicalSlot(marker, "policy", RADIANT_ECLIPSE_POLICY) &&
      canonicalSlot(marker, "day", day),
    close(): boolean {
      if (closed) return false;
      closed = true;
      if (!sameResource(true) || own(ability, "nightSuppression") !== marker) return false;
      delete (ability as { nightSuppression?: Readonly<EclipseSuppression> }).nightSuppression;
      return true;
    },
  };
}

/**
 * 负责赤月使徒的完整数据槽：原初态、五字段校验、同引用读取、玩家投影及三项有序提交。
 * 输入为原角色、原状态和调用方已经捕获的审计数据；输出保留原引用或原 JSON／浅副本，
 * 不改变旧接受集合。属性描述符校验允许原非枚举／只读数据字段，可写资格另由权威核对。
 * 状态提交只写 blastDay、exileDay、expirySettled；后项失败保留前项写入，不回滚或重读角色槽。
 * 内部审计编码函数 保留完整容器字段和 JSON 方法的原查找时点，不是严格档案读器 或复现授权。
 * 原生命、末狼、夜窗口、请求租约和完整容器失效／最终审计写入仍由恶魔猎手权威持有。
 */
import type {
  LastWolfBlastPolicy,
  RedMoonState,
  RedMoonReadState,
} from "@ai-werewolf-arena/game-contract";
import { types } from "node:util";
import type { RoleComponent } from "../../../../core/domain/components/role";
import type { RoleInitializationComponent } from "../contracts";
import { Camp } from "../../../../core/domain/identity";

export const RED_MOON_ROLE = "red_moon_apostle" as const;
export const RED_MOON_POLICY = "awa_red_moon_demon_v1" as const;
function own(value: unknown, key: string): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return undefined;
  const field = Object.getOwnPropertyDescriptor(value, key);
  return field && "value" in field ? field.value : undefined;
}
function day(value: unknown): value is number {
  return (
    typeof value === "number" &&
    Number.isSafeInteger(value) &&
    value > 0 &&
    value < Number.MAX_SAFE_INTEGER
  );
}
export function freshRedMoonState(
  lastWolfBlastPolicy: LastWolfBlastPolicy = "ends_game",
): RedMoonState {
  return {
    policy: RED_MOON_POLICY,
    lastWolfBlastPolicy,
    blastDay: null,
    exileDay: null,
    expirySettled: false,
  };
}
/** 安装的左值先查原 privateState，再在原 fresh callee 后读取政策；初始化不复制或二次校验。 */
export function initializeRedMoonState(
  role: RoleInitializationComponent,
  readPolicy: () => LastWolfBlastPolicy,
): void {
  role.privateState.redMoon = freshRedMoonState(readPolicy());
}

/** 原五字段形状校验 返回输入本体；拒绝代理对象／访问器，不执行它们，也不补默认或加强可写要求。 */
export function readRedMoonPayload(state: unknown): RedMoonReadState | undefined {
  if (!state || typeof state !== "object" || types.isProxy(state)) return undefined;
  const expected = ["policy", "lastWolfBlastPolicy", "blastDay", "exileDay", "expirySettled"];
  const fields = Object.getOwnPropertyDescriptors(state);
  if (
    Reflect.ownKeys(fields).length !== expected.length ||
    !expected.every((key) => fields[key] && "value" in fields[key]!)
  )
    return undefined;
  const policy = own(state, "lastWolfBlastPolicy");
  const blast = own(state, "blastDay"),
    exile = own(state, "exileDay");
  const settled = own(state, "expirySettled");
  if (
    own(state, "policy") !== RED_MOON_POLICY ||
    (policy !== "ends_game" && policy !== "forbidden") ||
    (blast !== null && !day(blast)) ||
    (exile !== null && !day(exile)) ||
    (blast !== null && exile !== null) ||
    typeof settled !== "boolean" ||
    (settled && exile === null)
  )
    return undefined;
  return state as RedMoonReadState;
}

/** 原角色／阵营门槛先于容器与 payload 校验；不以合法副本替换所属 live 状态。 */
export function getRedMoonState(role: RoleComponent | undefined): RedMoonReadState | undefined {
  if (own(role, "role") !== RED_MOON_ROLE || own(role, "camp") !== Camp.Wolf) return undefined;
  const state = own(own(role, "privateState"), "redMoon");
  return readRedMoonPayload(state);
}

/** 机制自己决定玩家字段；校验失败仍为 undefined，不补默认政策或猜测到期结果。 */
export function projectRedMoonState(role: RoleComponent | undefined): RedMoonState | undefined {
  const redMoon = getRedMoonState(role);
  if (redMoon)
    return {
      policy: redMoon.policy,
      lastWolfBlastPolicy: redMoon.lastWolfBlastPolicy,
      blastDay: redMoon.blastDay,
      exileDay: redMoon.exileDay,
      expirySettled: redMoon.expirySettled,
    };
}

/** JSON.parse 的方法查找先于 readJson；只解码原已持有审计字符串，不读取 live 容器。 */
export function readRedMoonShadow(readJson: () => string): Record<string, unknown> {
  return JSON.parse(readJson()) as Record<string, unknown>;
}

/** 在原状态校验后按原 spread 顺序生成候选；这是一次浅副本，不是第二份 live 库存。 */
export function copyRedMoonPayload(state: RedMoonReadState): RedMoonState {
  return { ...state };
}

/** 原完整私有容器保留其余字段；JSON.stringify 查找先于 spread，结果只供原同步审计比较。 */
export function encodeRedMoonShadow(original: Record<string, unknown>, next: RedMoonState): string {
  return JSON.stringify({ ...original, redMoon: next });
}

/** 调用方已完成原可写预检与 kind／夜政策；每次 next 字段读取仍紧邻对应写入，失败不补偿。 */
export function writeRedMoonTransition(state: RedMoonReadState, next: RedMoonState): void {
  (state as Pick<RedMoonState, "blastDay">).blastDay = next.blastDay;
  (state as Pick<RedMoonState, "exileDay">).exileDay = next.exileDay;
  (state as Pick<RedMoonState, "expirySettled">).expirySettled = next.expirySettled;
}

/**
 * 契约引用本族唯一实现；仅冻结声明，不冻结原运行状态。形状校验和失效读取沿用同一原校验，
 * 不新增 id／life／request 租约。checkpoint 是内部审计影子的原编码函数，未替代档案完整读器。
 */
export const RED_MOON_STATE_SLOT = Object.freeze({
  create: freshRedMoonState,
  schema: readRedMoonPayload,
  get: getRedMoonState,
  install: initializeRedMoonState,
  allowedWrites: Object.freeze({ transition: writeRedMoonTransition }),
  checkpoint: Object.freeze({
    read: readRedMoonShadow,
    prepare: copyRedMoonPayload,
    encode: encodeRedMoonShadow,
  }),
  invalidations: Object.freeze({ readCurrent: getRedMoonState }),
});

/**
 * 负责白昼学者／寂夜导师的原 roster、生命／原生能力权威、夜选择许可和已结算加成。
 * 输入为原 World／day、选择与原生目标证据；输出保原 pending／selection、加成回执及有来源冲突死亡。
 * 状态 raw／库存／历史／JSON 绑定及实际数据写归本族 state-slot，有限板免疫与碰撞规则归 rules。
 * 不变量：槽提交成功才删 pending／追加 selection；普通已提交交换可跨一次正常死亡，不可跨复活或换生命。
 * 关闭仍要求原加成全处理，abort 只改原夜窗口；不为替换原体补授库存或复制运行回执。
 */
import type {
  ModifierMode,
  CommittedModifier,
  ModifierResolution,
  ModifierReadState,
} from "@ai-werewolf-arena/game-contract";
import { types } from "node:util";
import { COMPONENT, Camp, type RoleComponent, type World } from "../../../../core";
import {
  aliveLifeDescriptor,
  aliveLifeVersion,
  type AliveComponent,
} from "../../../../core/domain/components/alive";
import type { NightLifeScope } from "../../../../core/domain/night_effects";
import {
  readModifierState,
  selectModifier,
  modifierOwnData as ownData,
  ScholarMentorStateSlot,
} from "./state-slot";
import { resolveModifiers } from "./rules";
// 原体／身份／生命与原生能力查询分开捕获；库存槽内容相同不能补回另一 Role 或生命的授权。
interface OriginalPlayer {
  abilityAuthority: () => boolean;
  id: number;
  role: RoleComponent;
  roleName: RoleComponent["role"];
  camp: RoleComponent["camp"];
  privateState: RoleComponent["privateState"];
  identity: unknown;
  seat: number;
  name: string;
  sessionId: string;
  life: AliveComponent;
  version: number;
}
export type ModifierBonusKind = "check" | "guard" | "poison" | "kill";
// 本夜额外机会不扣施法者槽的另一份库存；used／targetId 在原创建点或复验后的回执 commit 才写。
interface Grant {
  actorId: number;
  kind: ModifierBonusKind;
  used: boolean;
  targetId: number | null;
}
// pending 保未提交选择，selections 仅在槽写与 JSON 更新成功后追加；两者与 bonus grant 生命周期仍归 frame。
interface ModifierNight {
  day: number;
  closed: boolean;
  aborted: boolean;
  living: ReadonlySet<number>;
  pending: Set<number>;
  selections: CommittedModifier[];
  resolution: ModifierResolution | null;
  grants: Map<number, Grant>;
  nativeTargets: Map<string, number | null>;
}
interface Board {
  players: ReadonlyMap<number, OriginalPlayer>;
  casters: ReadonlyMap<number, ScholarMentorStateSlot>;
  night: ModifierNight | null;
}
const boards = new WeakMap<World, Board>();


const missingAbilityField = Symbol("missing_ability_field");
function boundAbilityData(value: unknown, key: PropertyKey): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value))
    throw new Error("scholar_mentor_original_abilities_invalid");
  const descriptor = Object.getOwnPropertyDescriptor(value, key);
  if (!descriptor) {
    if (key in value) throw new Error("scholar_mentor_original_abilities_invalid");
    return missingAbilityField;
  }
  if (!("value" in descriptor)) throw new Error("scholar_mentor_original_abilities_invalid");
  return descriptor.value;
}
function bindAbilities(role: RoleComponent): () => boolean {
  const container = boundAbilityData(role.privateState, "abilities");
  const prototype = Object.getPrototypeOf(role.privateState);
  if (container === missingAbilityField || container === undefined)
    return () =>
      Object.getPrototypeOf(role.privateState) === prototype &&
      boundAbilityData(role.privateState, "abilities") === container;
  if (
    !container ||
    typeof container !== "object" ||
    types.isProxy(container) ||
    Array.isArray(container)
  )
    throw new Error("scholar_mentor_original_abilities_invalid");
  const names = Reflect.ownKeys(container);
  const bindings = names.map((key) => {
    const ability = ownData(container, key);
    if (!ability || typeof ability !== "object" || types.isProxy(ability))
      throw new Error("scholar_mentor_original_abilities_invalid");
    const fields = [
      "id",
      "kind",
      "activation",
      "source",
      "state",
      "startsOnDay",
      "expiresAfterDay",
      "maxUses",
      "disabled",
      "deathExpired",
      "sourceDisclosed",
    ] as const;
    const values = fields.map((k) => boundAbilityData(ability, k)),
      source = ownData(ability, "source"),
      state = ownData(ability, "state");
    const sourceFields = ["kind", "role", "actorId", "abilityId"] as const,
      sourceValues = sourceFields.map((k) => boundAbilityData(source, k));
    const policyFields = [
        "targetPolicy",
        "actionPolicy",
        "selfHealRule",
        "knifeVisibility",
        "potionPolicy",
        "repeatPolicy",
      ] as const,
      policies = policyFields.map((k) => boundAbilityData(state, k));
    return () =>
      ownData(container, key) === ability &&
      fields.every((k, i) => boundAbilityData(ability, k) === values[i]) &&
      sourceFields.every((k, i) => boundAbilityData(source, k) === sourceValues[i]) &&
      policyFields.every((k, i) => boundAbilityData(state, k) === policies[i]);
  });
  return () =>
    Object.getPrototypeOf(role.privateState) === prototype &&
    boundAbilityData(role.privateState, "abilities") === container &&
    Reflect.ownKeys(container).length === names.length &&
    bindings.every((fn) => fn());
}

function originalPlayer(world: World, p: OriginalPlayer): boolean {
  if (
    !p.abilityAuthority() ||
    world.getComponent(p.id, COMPONENT.Role) !== p.role ||
    ownData(p.role, "role") !== p.roleName ||
    ownData(p.role, "camp") !== p.camp ||
    ownData(p.role, "privateState") !== p.privateState ||
    world.getComponent(p.id, COMPONENT.Identity) !== p.identity ||
    ownData(p.identity, "id") !== p.id ||
    ownData(p.identity, "seat") !== p.seat ||
    ownData(p.identity, "name") !== p.name ||
    ownData(p.identity, "sessionId") !== p.sessionId ||
    world.getComponent(p.id, COMPONENT.Alive) !== p.life
  )
    return false;
  const expected = aliveLifeDescriptor(p.life);
  const current = Object.getOwnPropertyDescriptor(p.life, "alive");
  if (
    !expected ||
    !current ||
    current.get !== expected.get ||
    current.set !== expected.set ||
    current.enumerable !== expected.enumerable ||
    current.configurable !== expected.configurable
  )
    return false;
  const version = aliveLifeVersion(p.life);
  // 已提交交换可跨一次普通死亡；复活或换生命仍撤权。
  return p.life.alive ? version === p.version : version === p.version + 1;
}

function requireBoard(world: World): Board {
  const b = boards.get(world);
  if (!b) throw new Error("scholar_mentor_board_missing");
  const ids = world.entityIds();
  if (
    ids.length !== b.players.size ||
    ids.some((id) => !b.players.has(id)) ||
    [...b.players.values()].some((p) => !originalPlayer(world, p))
  )
    throw new Error("scholar_mentor_original_state_revoked");
  for (const [id, c] of b.casters) {
    if (
      !c.matches(ownData(b.players.get(id)!.privateState, "scholarMentor"))
    )
      throw new Error("scholar_mentor_original_state_revoked");
  }
  return b;
}
export function installScholarMentorBoard(world: World): void {
  if (boards.has(world)) throw new Error("scholar_mentor_board_already_installed");
  const players = new Map<number, OriginalPlayer>(),
    seats = new Set<number>();
  const casters = new Map<number, ScholarMentorStateSlot>();
  for (const id of world.entityIds()) {
    const role = world.getComponent(id, COMPONENT.Role);
    const life = world.getComponent(id, COMPONENT.Alive);
    const version = life && aliveLifeVersion(life);
    if (
      !role ||
      !life ||
      types.isProxy(life) ||
      version === undefined ||
      (role.camp !== Camp.Wolf && role.camp !== Camp.Good)
    )
      throw new Error("scholar_mentor_original_roster_invalid");
    const expected = aliveLifeDescriptor(life);
    const descriptor = Object.getOwnPropertyDescriptor(life, "alive");
    if (
      !expected ||
      !descriptor ||
      expected.get !== descriptor.get ||
      expected.set !== descriptor.set ||
      expected.enumerable !== descriptor.enumerable ||
      expected.configurable !== descriptor.configurable ||
      !life.alive
    )
      throw new Error("scholar_mentor_original_roster_invalid");
    if (
      ownData(role, "role") === undefined ||
      ownData(role, "camp") === undefined ||
      ownData(role, "privateState") === undefined
    )
      throw new Error("scholar_mentor_original_roster_invalid");
    const identity = world.getComponent(id, COMPONENT.Identity);
    const seat = ownData(identity, "seat"),
      name = ownData(identity, "name"),
      sessionId = ownData(identity, "sessionId");
    if (
      ownData(identity, "id") !== id ||
      typeof seat !== "number" ||
      !Number.isSafeInteger(seat) ||
      seat <= 0 ||
      seats.has(seat) ||
      typeof name !== "string" ||
      typeof sessionId !== "string"
    )
      throw new Error("scholar_mentor_original_roster_invalid");
    seats.add(seat);
    players.set(id, {
      abilityAuthority: bindAbilities(role),
      id,
      role,
      roleName: role.role,
      camp: role.camp,
      privateState: role.privateState,
      identity,
      seat,
      name,
      sessionId,
      life,
      version,
    });

    if (String(role.role) === "day_scholar" || String(role.role) === "night_mentor") {
      const raw = ownData(role.privateState, "scholarMentor");
      const state = readModifierState(raw);
      if (!state || state.caster !== String(role.role) || state.history.length !== 0)
        throw new Error("scholar_mentor_original_roster_invalid");
      const original = raw as ModifierReadState;
      casters.set(id, new ScholarMentorStateSlot(original));
    }
  }
  resolveModifiers(
    [...players.values()].map((p) => ({
      id: p.id,
      role: String(p.roleName),
      camp: p.camp === Camp.Wolf ? "wolf" : "good",
      alive: true,
    })),
    [],
  );
  if (casters.size !== 2) throw new Error("scholar_mentor_original_roster_invalid");
  boards.set(world, { players, casters, night: null });
}
export function isScholarMentorBoard(world: World): boolean {
  if (!boards.has(world)) return false;
  requireBoard(world);
  return true;
}
export function assertScholarMentorRosterCurrent(world: World): void {
  if (boards.has(world)) requireBoard(world);
}
function night(world: World, day: number): { b: Board; n: ModifierNight } {
  const b = requireBoard(world),
    n = b.night;
  if (!n || n.day !== day || n.closed || n.aborted)
    throw new Error("scholar_mentor_night_unavailable");
  return { b, n };
}
function resolved(
  world: World,
  day: number,
): { b: Board; n: ModifierNight; r: ModifierResolution } {
  const { b, n } = night(world, day);
  if (!n.resolution) throw new Error("scholar_mentor_night_unsettled");
  return { b, n, r: n.resolution };
}
export function beginScholarMentorNight(world: World, day: number): number[] {
  const b = requireBoard(world);
  if (
    !Number.isSafeInteger(day) ||
    day < 1 ||
    day >= Number.MAX_SAFE_INTEGER ||
    (!b.night && day !== 1) ||
    (b.night && (!b.night.closed || b.night.aborted || day !== b.night.day + 1))
  )
    throw new Error("scholar_mentor_night_invalid");
  const living = new Set([...b.players.values()].filter((p) => p.life.alive).map((p) => p.id));
  const pending = new Set(
    [...b.casters]
      .filter(
        ([id, c]) =>
          day >= 2 && living.has(id) && c.state.remaining.enhance + c.state.remaining.weaken > 0,
      )
      .map(([id]) => id),
  );
  b.night = {
    day,
    closed: false,
    aborted: false,
    living,
    pending,
    selections: [],
    resolution: null,
    grants: new Map(),
    nativeTargets: new Map(),
  };
  return [...pending];
}
export function scholarMentorChoicePending(world: World, day: number, actorId: number): boolean {
  const { b, n } = night(world, day);
  return n.pending.has(actorId) && b.players.get(actorId)!.life.alive;
}
export function scholarMentorChoiceTargets(world: World, day: number, actorId: number): number[] {
  const { b, n } = night(world, day);
  return n.pending.has(actorId) ? [...n.living].filter((id) => b.players.get(id)!.life.alive) : [];
}
export function commitScholarMentorChoice(
  world: World,
  day: number,
  actorId: number,
  mode: ModifierMode | null,
  targetId: number | null,
): void {
  const { b, n } = night(world, day),
    c = b.casters.get(actorId);
  if (!c || !n.pending.has(actorId) || !b.players.get(actorId)!.life.alive || n.resolution)
    throw new Error("scholar_mentor_choice_scope_invalid");
  const next = selectModifier(
    c.state,
    day,
    mode,
    targetId,
    scholarMentorChoiceTargets(world, day, actorId),
  );
  c.commit(next);
  n.pending.delete(actorId);
  if (mode !== null)
    n.selections.push({ actorId, caster: c.state.caster, mode, targetId: targetId! });
}
export function settleScholarMentorChoices(world: World, day: number): ModifierResolution {
  const { b, n } = night(world, day);
  if (n.pending.size || n.resolution) throw new Error("scholar_mentor_choices_unsettled");
  const r = resolveModifiers(
    [...b.players.values()].map((p) => ({
      id: p.id,
      role: String(p.roleName),
      camp: p.camp === Camp.Wolf ? "wolf" : "good",
      alive: n.living.has(p.id),
    })),
    n.selections,
  );
  n.resolution = r;
  for (const effect of r.goodEffects)
    if (effect.mode === "enhance")
      n.grants.set(effect.targetId, {
        actorId: effect.targetId,
        kind: effect.role === "seer" ? "check" : effect.role === "witch" ? "poison" : "guard",
        used: false,
        targetId: null,
      });
  if (r.bonusKnifeActorId !== null)
    n.grants.set(r.bonusKnifeActorId, {
      actorId: r.bonusKnifeActorId,
      kind: "kill",
      used: false,
      targetId: null,
    });
  return structuredClone(r);
}
export function scholarMentorBlocks(
  world: World,
  day: number,
  actorId: number,
  kind: ModifierBonusKind,
): boolean {
  if (!boards.has(world)) return false;
  const { r } = resolved(world, day);
  if (kind === "kill") return r.blockWolfKnife;
  return r.goodEffects.some(
    (e) =>
      e.targetId === actorId &&
      e.mode === "weaken" &&
      ((e.role === "seer" && kind === "check") ||
        (e.role === "guard" && kind === "guard") ||
        (e.role === "witch" && kind === "poison")),
  );
}
export function scholarMentorKnifeEligible(world: World, day: number, actorId: number): boolean {
  const { b, n } = night(world, day),
    p = b.players.get(actorId);
  if (!p || !n.living.has(actorId) || !p.life.alive || p.camp !== Camp.Wolf) return false;
  if (String(p.roleName) === "wolf") return true;
  return (
    String(p.roleName) === "night_mentor" &&
    [...n.living].filter((id) => b.players.get(id)!.camp === Camp.Wolf).length === 1
  );
}
function nativeKey(actorId: number, kind: ModifierBonusKind): string {
  return kind === "kill" ? "pack:kill" : actorId + ":" + kind;
}
export function recordScholarMentorNativeTarget(
  world: World,
  day: number,
  actorId: number,
  kind: ModifierBonusKind,
  targetId: number | null,
): void {
  const { b, n } = resolved(world, day),
    key = nativeKey(actorId, kind),
    p = b.players.get(actorId);
  if (
    !p ||
    !n.living.has(actorId) ||
    !p.life.alive ||
    n.nativeTargets.has(key) ||
    (targetId !== null && (!n.living.has(targetId) || !b.players.get(targetId)?.life.alive))
  )
    throw new Error("scholar_mentor_native_target_invalid");
  const expected =
    kind === "check" ? "seer" : kind === "guard" ? "guard" : kind === "poison" ? "witch" : null;
  if (expected ? String(p.roleName) !== expected : !scholarMentorKnifeEligible(world, day, actorId))
    throw new Error("scholar_mentor_native_actor_invalid");
  n.nativeTargets.set(key, targetId);
}
export function scholarMentorBonusActors(
  world: World,
  day: number,
  kind: ModifierBonusKind,
): number[] {
  const { n } = resolved(world, day);
  return [...n.grants.values()].filter((g) => g.kind === kind && !g.used).map((g) => g.actorId);
}
export function scholarMentorBonusTargets(
  world: World,
  day: number,
  actorId: number,
  kind: ModifierBonusKind,
): number[] {
  const { b, n } = resolved(world, day),
    g = n.grants.get(actorId),
    key = nativeKey(actorId, kind);
  if (
    !g ||
    g.kind !== kind ||
    g.used ||
    !b.players.get(actorId)!.life.alive ||
    !n.nativeTargets.has(key)
  )
    return [];
  const native = n.nativeTargets.get(key);
  return [...n.living].filter((id) => id !== native && b.players.get(id)!.life.alive);
}
export interface ModifierBonusReceipt {
  readonly target: NightLifeScope | null;
  readonly source: NightLifeScope;
  readonly isCurrent: () => boolean;
  readonly effectCurrent: () => boolean;
  readonly commit: () => void;
}
export function captureScholarMentorBonus(
  world: World,
  day: number,
  actorId: number,
  kind: ModifierBonusKind,
  targetId: number | null,
): ModifierBonusReceipt {
  const { b, n } = resolved(world, day),
    g = n.grants.get(actorId),
    p = b.players.get(actorId),
    key = nativeKey(actorId, kind);
  if (
    !g ||
    g.kind !== kind ||
    g.used ||
    !p?.life.alive ||
    !n.nativeTargets.has(key) ||
    (targetId !== null && !scholarMentorBonusTargets(world, day, actorId, kind).includes(targetId))
  )
    throw new Error("scholar_mentor_bonus_unavailable");
  const source: NightLifeScope = Object.freeze({
    id: actorId,
    life: p.life,
    version: aliveLifeVersion(p.life)!,
  });
  const t = targetId === null ? null : b.players.get(targetId)!;
  const target: NightLifeScope | null = t
    ? Object.freeze({ id: t.id, life: t.life, version: aliveLifeVersion(t.life)! })
    : null;
  let committed = false;
  const live = () => {
    try {
      return (
        requireBoard(world) === b &&
        b.night === n &&
        !n.closed &&
        !n.aborted &&
        n.grants.get(actorId) === g &&
