/**
 * 负责狼术师原生换位、夜目标映射回执及原体生命／窗口撤权。输入为原参与者与成对选择，
 * 输出为当前映射、狼队就绪和关闭／中止结果；只有原绑定参与者共享交换，不替换来源。
 * 原状态与历史写入／身份编码归本族槽，frame 保原引用和 expectedState，并唯一拥有夜关系。
 * 历史先写、身份再刷新、pair／committed 最后提交；后续失败不退款、修复或覆盖已写前缀。
 */
import type { WolfSorcererReadState } from "@ai-werewolf-arena/game-contract";
import { resolveOrderedSeatTarget } from "./seat_mapping";
import { types } from "node:util";
import { COMPONENT, type RoleComponent, type World } from "../../../../core";
import {
  aliveLifeDescriptor,
  aliveLifeVersion,
  type AliveComponent,
} from "../../../../core/domain/components/alive";
import type { NightLifeScope } from "../../../../core/domain/night_effects";
import { getWolfSorcererState, projectWolfSorcererState, WOLF_SORCERER_ROLE, WOLF_SORCERER_STATE_SLOT } from "./state-slot";

interface OriginalPlayer {
  id: number;
  role: RoleComponent;
  roleName: RoleComponent["role"];
  camp: RoleComponent["camp"];
  privateState: RoleComponent["privateState"];
  identity: unknown;
  seat: number;
  name: string;
  sessionId: string;
  life: AliveComponent;
  version: number;
}
interface ExchangeNight {
  day: number;
  closed: boolean;
  committed: boolean;
  pair: readonly [number, number] | null;
  targets: ReadonlyMap<number, OriginalPlayer>;
}
interface Board {
  actorId: number;
  state: WolfSorcererReadState;
  /** 原知识 JSON 检查点与同引用状态一起复验；不是库存副本或档案授权。 */
  expectedState: string;
  players: ReadonlyMap<number, OriginalPlayer>;
  night: ExchangeNight | null;
}
const boards = new WeakMap<World, Board>();
function ownData(value: unknown, key: PropertyKey): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return undefined;
  const d = Object.getOwnPropertyDescriptor(value, key);
  return d && "value" in d ? d.value : undefined;
}
function originalPlayer(world: World, p: OriginalPlayer): boolean {
  if (
    world.getComponent(p.id, COMPONENT.Role) !== p.role ||
    ownData(p.role, "role") !== p.roleName ||
    ownData(p.role, "camp") !== p.camp ||
    ownData(p.role, "privateState") !== p.privateState ||
    world.getComponent(p.id, COMPONENT.Identity) !== p.identity ||
    ownData(p.identity, "id") !== p.id ||
    ownData(p.identity, "seat") !== p.seat ||
    ownData(p.identity, "name") !== p.name ||
    ownData(p.identity, "sessionId") !== p.sessionId ||
    world.getComponent(p.id, COMPONENT.Alive) !== p.life
  )
    return false;
  const expected = aliveLifeDescriptor(p.life);
  const current = Object.getOwnPropertyDescriptor(p.life, "alive");
  if (
    !expected ||
    !current ||
    current.get !== expected.get ||
    current.set !== expected.set ||
    current.enumerable !== expected.enumerable ||
    current.configurable !== expected.configurable
  )
    return false;
  const version = aliveLifeVersion(p.life);
  // 已提交换位保留原一次普通死亡效果；复活、换生命或原数据字段改为访问器仍撤权。
  return p.life.alive ? version === p.version : version === p.version + 1;
}
function requireBoard(world: World): Board {
  const b = boards.get(world);
  if (!b) throw new Error("wolf_sorcerer_board_missing");
  const ids = world.entityIds();
  if (
    ids.length !== b.players.size ||
    ids.some((id) => !b.players.has(id)) ||
    [...b.players.values()].some((p) => !originalPlayer(world, p))
  )
    throw new Error("wolf_sorcerer_original_state_revoked");
  const actor = b.players.get(b.actorId)!;
  if (getWolfSorcererState(actor.role) !== b.state || WOLF_SORCERER_STATE_SLOT.checkpoint.identity(actor.role) !== b.expectedState)
    throw new Error("wolf_sorcerer_original_state_revoked");
  return b;
}
export function installWolfSorcererBoard(world: World): void {
  if (boards.has(world)) throw new Error("wolf_sorcerer_board_already_installed");
  const players = new Map<number, OriginalPlayer>();
  const seats = new Set<number>();
  let actorId: number | null = null;
  let state: WolfSorcererReadState | undefined;
  for (const id of world.entityIds()) {
    const role = world.getComponent(id, COMPONENT.Role);
    const life = world.getComponent(id, COMPONENT.Alive);
    const version = life && aliveLifeVersion(life);
    if (!role || !life || types.isProxy(life) || version === undefined)
      throw new Error("wolf_sorcerer_original_roster_invalid");
    const expected = aliveLifeDescriptor(life);
    const descriptor = Object.getOwnPropertyDescriptor(life, "alive");
    if (
      !expected ||
      !descriptor ||
      expected.get !== descriptor.get ||
      expected.set !== descriptor.set ||
      expected.enumerable !== descriptor.enumerable ||
      expected.configurable !== descriptor.configurable ||
      !life.alive
    )
      throw new Error("wolf_sorcerer_original_roster_invalid");
    if (
      ownData(role, "role") === undefined ||
      ownData(role, "camp") === undefined ||
      ownData(role, "privateState") === undefined
    )
      throw new Error("wolf_sorcerer_original_roster_invalid");
    const identity = world.getComponent(id, COMPONENT.Identity);
    const seat = ownData(identity, "seat"),
      name = ownData(identity, "name"),
      sessionId = ownData(identity, "sessionId");
    if (
      ownData(identity, "id") !== id ||
      typeof seat !== "number" ||
      !Number.isSafeInteger(seat) ||
      seat <= 0 ||
      seats.has(seat) ||
      typeof name !== "string" ||
      typeof sessionId !== "string"
    )
      throw new Error("wolf_sorcerer_original_roster_invalid");
    seats.add(seat);
    players.set(id, {
      id,
      role,
      roleName: role.role,
      camp: role.camp,
      privateState: role.privateState,
      identity,
      seat,
      name,
      sessionId,
      life,
      version,
    });
    if (String(role.role) === WOLF_SORCERER_ROLE) {
      if (actorId !== null) throw new Error("wolf_sorcerer_original_roster_invalid");
      actorId = id;
      state = getWolfSorcererState(role);
    }
  }
  if (actorId === null || !state || state.history.length !== 0)
    throw new Error("wolf_sorcerer_original_roster_invalid");
  boards.set(world, {
    actorId,
    state,
    expectedState: WOLF_SORCERER_STATE_SLOT.checkpoint.identity(players.get(actorId)!.role),
    players,
    night: null,
  });
}
export function isWolfSorcererBoard(world: World): boolean {
  if (!boards.has(world)) return false;
  requireBoard(world);
  return true;
}
export function beginWolfSorcererNight(world: World, day: number): number | null {
  const b = requireBoard(world);
  if (
    !Number.isSafeInteger(day) ||
    day <= 0 ||
    day >= Number.MAX_SAFE_INTEGER ||
    (!b.night && day !== 1) ||
    (b.night && (!b.night.closed || day !== b.night.day + 1))
  )
    throw new Error("wolf_sorcerer_night_invalid");
  const used = new Set<number>();
  for (const choice of projectWolfSorcererState(b.players.get(b.actorId)!.role)!.history)
    if (choice.pair) {
      used.add(choice.pair[0]);
      used.add(choice.pair[1]);
    }
  const targets = new Map([...b.players].filter(([id, p]) => p.life.alive && !used.has(id)));
  const eligible =
    day >= b.state.firstNight && b.players.get(b.actorId)!.life.alive && targets.size >= 2;
  b.night = { day, closed: false, committed: !eligible, pair: null, targets };
  return eligible ? b.actorId : null;
}
export function wolfSorcererChoiceTargets(world: World, day: number): number[] {
  const b = requireBoard(world),
    n = b.night;
  if (!n || n.day !== day || n.closed || n.committed) return [];
  return [...n.targets.values()].filter((p) => p.life.alive).map((p) => p.id);
}
export function commitWolfSorcererExchange(
  world: World,
  actorId: number,
  day: number,
  pair: readonly [number, number] | null,
): void {
  const b = requireBoard(world),
    n = b.night;
  if (
    !n ||
    n.day !== day ||
    n.closed ||
    n.committed ||
    b.actorId !== actorId ||
    !b.players.get(actorId)!.life.alive
  )
    throw new Error("wolf_sorcerer_choice_scope_invalid");
  let chosen: [number, number] | null = null;
  if (pair !== null) {
    if (types.isProxy(pair) || !Array.isArray(pair))
      throw new Error("wolf_sorcerer_choice_target_invalid");
    const descriptors: Record<string, PropertyDescriptor> = Object.getOwnPropertyDescriptors(
      pair as object,
    );
    const a = descriptors["0"]?.value,
      z = descriptors["1"]?.value;
    if (
      Reflect.ownKeys(descriptors).length !== 3 ||
      descriptors.length?.value !== 2 ||
      !Number.isSafeInteger(a) ||
      !Number.isSafeInteger(z) ||
      a <= 0 ||
      z <= 0
    )
      throw new Error("wolf_sorcerer_choice_target_invalid");
    if (a === z || !n.targets.get(a)?.life.alive || !n.targets.get(z)?.life.alive)
      throw new Error("wolf_sorcerer_choice_target_invalid");
    chosen = a < z ? [a, z] : [z, a];
  }
  WOLF_SORCERER_STATE_SLOT.allowedWrites.appendHistory(() => b.state, day, chosen);
  b.expectedState = WOLF_SORCERER_STATE_SLOT.checkpoint.identity(b.players.get(actorId)!.role);
  n.pair = chosen && Object.freeze([chosen[0], chosen[1]] as [number, number]);
  n.committed = true;
}
export interface WolfSorcererResolvedTarget {
  readonly requestedId: number;
  readonly effectiveId: number;
  readonly scope: NightLifeScope;
  readonly isCurrent: () => boolean;
}
export function resolveWolfSorcererNightTarget(
  world: World,
  day: number,
  requestedId: number,
  kind: "night_action" | "death_shot" | "original" | "intermediate" = "night_action",
): WolfSorcererResolvedTarget {
  const b = requireBoard(world),
    n = b.night;
  if (!n || n.day !== day || n.closed || !n.committed)
    throw new Error("wolf_sorcerer_night_unsettled");
  const original = b.players.get(requestedId);
  if (!original || !original.life.alive) throw new Error("wolf_sorcerer_target_invalid");
  const pair = kind === "original" ? null : n.pair;
  const effectiveId = resolveOrderedSeatTarget(requestedId, null, pair);
  const effective = b.players.get(effectiveId)!;
  if (kind === "night_action" && !effective.life.alive)
    throw new Error("wolf_sorcerer_target_invalid");
  const nightPair = n.pair;
  const requestedVersion = aliveLifeVersion(original.life)!;
  const scope: NightLifeScope = Object.freeze({
    id: effectiveId,
    life: effective.life,
    version: aliveLifeVersion(effective.life)!,
  });
  return Object.freeze({
    requestedId,
    effectiveId,
    scope,
    isCurrent: () => {
      try {
        return (
          requireBoard(world) === b &&
          b.night === n &&
          n.pair === nightPair &&
          !n.closed &&
          originalPlayer(world, original) &&
          originalPlayer(world, effective) &&
          original.life.alive &&
          aliveLifeVersion(original.life) === requestedVersion &&
          aliveLifeVersion(effective.life) === scope.version
        );
      } catch {
        return false;
      }
    },
  });
}
export function closeWolfSorcererNight(world: World, day: number): void {
  const b = requireBoard(world),
    n = b.night;
  if (!n || n.day !== day || n.closed || !n.committed)
    throw new Error("wolf_sorcerer_night_unsettled");
  n.closed = true;
}

export function assertWolfSorcererRosterCurrent(world: World): void {
  requireBoard(world);
}
export function wolfSorcererChoicePending(world: World, actorId: number, day: number): boolean {
  const b = requireBoard(world),
    n = b.night;
  return (
    b.actorId === actorId &&
    !!n &&
    n.day === day &&
    !n.closed &&
    !n.committed &&
    b.players.get(actorId)!.life.alive
  );
}

/** 仅清理原夜窗口；不校验／修复已撤权名单，不追加选择或重新取得资源。 */
export function abortWolfSorcererNight(world: World): void {
  const n = boards.get(world)?.night;
  if (n) n.closed = true;
}

/** 首次可行动的夜选择结算之前不公开初始狼队知识；知识就绪本身不授新请求许可。 */
export function wolfSorcererPackReady(world: World): boolean {
  const b = requireBoard(world),
    n = b.night;
  return !!n && n.day >= b.state.firstNight && n.committed;
}

export function wolfSorcererActorId(world: World): number {
  return requireBoard(world).actorId;
}

/**
 * 负责在目标已映射的原生行动之前推进狼术师换位机会。输入为原 frame、日次及通过校验的成对选择；
 * 输出原换位提交和私有事实，狼队知识就绪、目标回执与生命撤权仍由 frame 负责。
 * Provider／工具校验之后保原名单与阶段复验；commit 先于发布，发布失败不撤销已付选择。
 */
import type { AliveComponent } from "../../../../core/domain/components/alive";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Phase } from "../../../../core/domain/identity";
import type { NightStageHandler } from "../../stages/night/contracts";
import { getWolfSorcererState } from "./state-slot";
import {
  wolfSorcererActorId,
  assertWolfSorcererRosterCurrent,
  beginWolfSorcererNight,
  commitWolfSorcererExchange,
  wolfSorcererChoiceTargets,
} from "./night_frame";
/** 按原配置角色集合运行，狼术师死亡之后仍开启本族阶段并按原理由记录跳过。 */
export const WOLF_SORCERER_EXCHANGE_STAGE: NightStageHandler = {
  id: "wolf_sorcerer_exchange",
  priority: 100,
  async execute(ctx) {
    const day = ctx.currentDay(),
      actorId = beginWolfSorcererNight(ctx.world, day);
    if (actorId === null) {
      const id = wolfSorcererActorId(ctx.world),
        own = ctx.world.getComponent(id, COMPONENT.Role);
      const state = getWolfSorcererState(own)!;
      const reason =
        day < state.firstNight
          ? "not_started"
          : ctx.world.getComponent(id, COMPONENT.Alive)!.alive
            ? "exhausted"
            : "dead";
      ctx.events.push({
        timestamp: Date.now(),
        type: "wolf_sorcerer_exchange_skipped",
        payload: { actorId: id, day, reason },
        audience: Object.freeze([id]),
      });
      return;
    }
    const role = ctx.world.getComponent(actorId, COMPONENT.Role);
    if (!getWolfSorcererState(role)) throw new Error("wolf_sorcerer_actor_invalid");
    const request = ctx.makeRequest(actorId, ["swap_night_seats"], {
      stage: "wolf_sorcerer_exchange",
      requiresAction: true,
      action_failure_policy: "error",
      allow_fallback: false,
      sorcerer_candidates: wolfSorcererChoiceTargets(ctx.world, day),
    });
    assertWolfSorcererRosterCurrent(ctx.world);
    const action = await ctx.actionProvider.getAction(request);
    assertWolfSorcererRosterCurrent(ctx.world);
    if (!ctx.isCurrent() || ctx.currentDay() !== day)
      throw new Error("wolf_sorcerer_exchange_stale");
    if (action?.name !== "swap_night_seats")
      throw new Error("wolf_sorcerer_exchange_action_missing");
    const validated = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
      phase: Phase.Night,
      day,
    });
    assertWolfSorcererRosterCurrent(ctx.world);
    if (!ctx.isCurrent() || ctx.currentDay() !== day)
      throw new Error("wolf_sorcerer_exchange_stale");
    if (!validated.ok || validated.sanitizedCall?.name !== "swap_night_seats")
      throw new Error("wolf_sorcerer_exchange_action_invalid");
    const args = validated.sanitizedCall.args;
    const pair: [number, number] | null = args.abstain ? null : [args.first_id!, args.second_id!];
    commitWolfSorcererExchange(ctx.world, actorId, day, pair);
    ctx.events.push({
      timestamp: Date.now(),
      type: "wolf_sorcerer_exchange_committed",
      payload: {
        actorId,
        day,
        pair: pair && [Math.min(pair[0], pair[1]), Math.max(pair[0], pair[1])],
      },
      audience: Object.freeze([actorId]),
    });
  },
};

/**
 * 提供狼术师具体耦合清理、原生名单查询及玩家状态投影入口。
 * 输入为原 World／日期与魔术师只读移交视图；输出保留清理单元、经理终结端口与名单断言。
 * 开启仍由优先级 100 的阶段拥有，出口不授予目标或库存写者；原 frame 错误在原时点传播。
 * 查询不渲染、不记录，也不为共享移交值建立第二个所有者。
 * 单元的关闭终态与失败前缀仍由夜间生命周期维护，出口不重开已结束的夜间窗口。
 */
export { WolfSorcererNightUnit, wolfSorcererNightTerminal } from "./night-lifecycle";
export type { WolfSorcererNightRuntime } from "./night-lifecycle";
export { assertWolfSorcererRosterCurrent } from "./night_frame";

/** 同绑定 live 读取保原引用，知识投影脱离；两者均不授库存／交换提交或阶段许可。 */
export { getWolfSorcererState, projectWolfSorcererState } from "./state-slot";

/**
 * 负责 狼术师 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { ORDINARY_WOLF_CONTRIBUTIONS } from "../wolf/ability-ports";
import { z } from "zod";
import { roleName, text } from "@ai-werewolf-arena/game-text";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { Role, Camp, WinCondition, Phase } from "../../../../core/domain/identity";
import type { NativeRoleContributions } from "../contracts";
import { WOLF_SORCERER_POLICY, WOLF_SORCERER_STATE_SLOT, getWolfSorcererState } from "./state-slot";
import {
  wolfSorcererChoicePending,
  wolfSorcererChoiceTargets,
  wolfSorcererPackReady,
} from "./night_frame";
import { WOLF_SORCERER_EXCHANGE_STAGE } from "./night_stages";
const parameters = z.strictObject({
  policy: z.literal(WOLF_SORCERER_POLICY).default(WOLF_SORCERER_POLICY),
  firstNight: z.union([z.literal(1), z.literal(2)]).default(2),
});
export const WOLF_SORCERER_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    ...ORDINARY_WOLF_CONTRIBUTIONS.metadata,
    role: Role.WolfSorcerer,
    camp: Camp.Wolf,
    maxCount: 1,
    supportedWinConditions: [WinCondition.SlaughterSide],
    supportedBoardRoles: [
      Role.Wolf,
      Role.Villager,
      Role.Psychic,
      Role.Witch,
      Role.Magician,
      Role.Hunter,
      Role.WolfSorcerer,
    ],
    label: roleName("wolf_sorcerer"),
    skillBrief: text("zh-CN", "role.wolf_sorcerer.brief"),
  },
  runtime: {
    ...ORDINARY_WOLF_CONTRIBUTIONS.runtime,
    wolfTeam: (role, world) => {
      const known = !!getWolfSorcererState(role)?.history.length;
      const active = known && (!world || wolfSorcererPackReady(world));
      return {
        recognizedByPack: known,
        recognizes: known ? "pack" : "none",
        canChat: active,
        canVoteForKill: active,
      };
    },
    init: (role, ctx) => {
      const value = parameters.parse(ctx.boardConfig?.wolfSorcerer ?? {});
      WOLF_SORCERER_STATE_SLOT.install(() => role.privateState, value);
    },
    configuration: {
      schema: parameters,
      defaults: parameters.parse({}),
      apply: (config, value) => ({ ...config, wolfSorcerer: parameters.parse(value) }),
      serialize: (config) => parameters.parse(config.wolfSorcerer ?? {}),
    },
    toolSpecs: [
      ...(ORDINARY_WOLF_CONTRIBUTIONS.runtime.toolSpecs ?? []),
      {
        name: "swap_night_seats",
        parameters: {
          type: "object",
          properties: {
            first_id: { type: ["integer", "null"], minimum: 1 },
            second_id: { type: ["integer", "null"], minimum: 1 },
            abstain: { type: "boolean" },
          },
          required: ["first_id", "second_id", "abstain"],
          additionalProperties: false,
        },
        argHint:
          'swap_night_seats args: {"first_id":number|null,"second_id":number|null,"abstain":true|false}',
        userPromptHintKey: "action.swap_night_seats.hint",
      },
    ],
    stageDirectives: [
      ...(ORDINARY_WOLF_CONTRIBUTIONS.runtime.stageDirectives ?? []),
      {
        match: (tools) => tools.length === 1 && tools[0] === "swap_night_seats",
        messageKey: "action.swap_night_seats.directive",
        text: text("zh-CN", "action.swap_night_seats.directive"),
      },
    ],
    validationRules: {
      ...ORDINARY_WOLF_CONTRIBUTIONS.runtime.validationRules,
      swap_night_seats: ({ world, role, actorId, day, phase, toolCall }) => {
        if (
          !getWolfSorcererState(role) ||
          day === undefined ||
          phase !== Phase.Night ||
          toolCall.name !== "swap_night_seats" ||
          !wolfSorcererChoicePending(world, actorId, day)
        )
          return { code: RuleError.WolfSorcererUnavailable };
        const { first_id, second_id, abstain } = toolCall.args;
        if (abstain)
          return first_id === null && second_id === null
            ? null
            : { code: RuleError.WolfSorcererTarget };
        const targets = wolfSorcererChoiceTargets(world, day);
        return first_id !== null &&
          second_id !== null &&
          first_id !== second_id &&
          targets.includes(first_id) &&
          targets.includes(second_id)
          ? null
          : { code: RuleError.WolfSorcererTarget };
      },
    },
    nightStages: [WOLF_SORCERER_EXCHANGE_STAGE, ...(ORDINARY_WOLF_CONTRIBUTIONS.runtime.nightStages ?? [])],
    baselineAction: (role, request, pick, pickCamp, locale, world) => {
      if (
        !request.allowedTools.includes("swap_night_seats") ||
        !world ||
        !getWolfSorcererState(role)
      )
        return (
          ORDINARY_WOLF_CONTRIBUTIONS.runtime.baselineAction?.(
            role,
            request,
            pick,
            pickCamp,
            locale,
            world,
          ) ?? null
        );
      const targets = wolfSorcererChoiceTargets(world, request.context.day);
      return targets.length >= 2
        ? {
            name: "swap_night_seats",
            args: { first_id: targets[0]!, second_id: targets[1]!, abstain: false },
          }
        : { name: "swap_night_seats", args: { first_id: null, second_id: null, abstain: true } };
    },
  },
  presentation: nativeRolePresentation("wolf_sorcerer"),
};

/**
 * 负责狼术师唯一状态槽的创建、完整 live 校验、同引用读取、原初始化／历史写入及身份编码。
 * 输入为原角色、参数和晚读容器；输出原状态引用、脱离知识副本或原明确拒绝。原 descriptor、
 * 日期、排序与一次性号码规则保持，写入失败保留原已写前缀，不回滚或付新资源。
 * frame 仍拥有原体生命、夜窗口、映射关系和 expectedState；此槽不另存 shadow、
 * 授予行动许可、关闭或标死。身份 JSON 仅为原运行比对，档案格式与独立核验仍归原 owner。
 */
import type {
  WolfSorcererChoice,
  WolfSorcererState,
  WolfSorcererReadState,
} from "@ai-werewolf-arena/game-contract";
import { types } from "node:util";
import { Camp, type RoleComponent } from "../../../../core";
export const WOLF_SORCERER_ROLE = "wolf_sorcerer" as const;
export const WOLF_SORCERER_POLICY = "awa_wolf_sorcerer_seats_v1" as const;
function field(value: unknown, key: PropertyKey): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return undefined;
  const d = Object.getOwnPropertyDescriptor(value, key);
  return d && "value" in d ? d.value : undefined;
}
function exact(value: unknown, keys: readonly string[]): boolean {
  if (!value || typeof value !== "object" || types.isProxy(value) || Array.isArray(value))
    return false;
  const descriptors = Object.getOwnPropertyDescriptors(value);
  return (
    Reflect.ownKeys(descriptors).length === keys.length &&
    keys.every((k) => descriptors[k] && "value" in descriptors[k]!)
  );
}
function integer(value: unknown): value is number {
  return (
    typeof value === "number" &&
    Number.isSafeInteger(value) &&
    value > 0 &&
    value < Number.MAX_SAFE_INTEGER
  );
}
function arrayItems(value: unknown): unknown[] | null {
  if (types.isProxy(value) || !Array.isArray(value)) return null;
  const length = field(value, "length");
  if (typeof length !== "number" || !Number.isSafeInteger(length) || length < 0) return null;
  const descriptors = Object.getOwnPropertyDescriptors(value);
  if (Reflect.ownKeys(descriptors).length !== length + 1) return null;
  const result: unknown[] = [];
  for (let i = 0; i < length; i++) {
    const d = descriptors[String(i)];
    if (!d || !("value" in d)) return null;
    result.push(d.value);
  }
  return result;
}
/** 完整原 live 校验先拒绝 Proxy，再仅读自身数据 descriptor；不调用 caller getter、迭代器或数组方法。
 * 合法时返回原状态／历史引用，不克隆或冻结；readonly 是读方类型，原体与夜窗口授权仍由 frame 复验。 */
export function getWolfSorcererState(
  role: RoleComponent | undefined,
): WolfSorcererReadState | undefined {
  if (field(role, "role") !== WOLF_SORCERER_ROLE || field(role, "camp") !== Camp.Wolf)
    return undefined;
  const state = field(field(role, "privateState"), "wolfSorcerer");
  if (!exact(state, ["policy", "firstNight", "history"])) return undefined;
  const firstNight = field(state, "firstNight");
  if (field(state, "policy") !== WOLF_SORCERER_POLICY || (firstNight !== 1 && firstNight !== 2))
    return undefined;
  const history = arrayItems(field(state, "history"));
  if (!history) return undefined;
  // 历史日期严格递增；非空二人组保原升序／全局号码一次使用，null 不消耗号码。
  let previous = 0;
  const used = new Set<number>();
  for (const entry of history) {
    if (!exact(entry, ["day", "pair"])) return undefined;
    const day = field(entry, "day"),
      rawPair = field(entry, "pair");
    if (!integer(day) || day < firstNight || day <= previous) return undefined;
    previous = day;
    if (rawPair === null) continue;
    const pair = arrayItems(rawPair);
    if (
      !pair ||
      pair.length !== 2 ||
      !integer(pair[0]) ||
      !integer(pair[1]) ||
      pair[0] >= pair[1] ||
      used.has(pair[0]) ||
      used.has(pair[1])
    )
      return undefined;
    used.add(pair[0]);
    used.add(pair[1]);
  }
  return state as WolfSorcererReadState;
}
export function createWolfSorcererState(firstNight: 1 | 2): WolfSorcererState {
  return { policy: WOLF_SORCERER_POLICY, firstNight, history: [] };
}
/** 复制原知识历史和非空 pair；可写副本不含运行窗口，也不经投影授予交换写权。 */
export function projectWolfSorcererState(
  role: RoleComponent | undefined,
): WolfSorcererState | undefined {
  const state = getWolfSorcererState(role);
  if (!state) return undefined;
  const history: WolfSorcererChoice[] = [];
  for (const row of arrayItems(field(state, "history"))!) {
    const rawPair = field(row, "pair");
    const values = rawPair === null ? null : arrayItems(rawPair)!;
    history.push({
      day: field(row, "day") as number,
      pair: values ? [values[0] as number, values[1] as number] : null,
    });
  }
  return {
    policy: WOLF_SORCERER_POLICY,
    firstNight: field(state, "firstNight") as 1 | 2,
    history,
  };
}

/** 原初始化先读左值容器，再读 firstNight 并创建／赋值；创建或 setter 失败不补写、回滚。 */
function installWolfSorcererState(
  privateState: () => Record<string, unknown>,
  value: { firstNight: 1 | 2 },
): void {
  privateState().wolfSorcerer = createWolfSorcererState(value.firstNight);
}

/** 准入仍由 frame 负责；先取 defineProperty callee，再两次晚读原 state/history，保 index 与 descriptor。 */
function appendWolfSorcererHistory(
  state: () => WolfSorcererReadState,
  day: number,
  chosen: [number, number] | null,
): void {
  Object.defineProperty(state().history, String(state().history.length), {
    value: { day, pair: chosen },
    writable: true,
    enumerable: true,
    configurable: true,
  });
}

/** 原 frame 身份编码：先 project／拒绝，再找 JSON.stringify；不是严格档案 decoder 或权限。 */
function encodeWolfSorcererStateIdentity(role: RoleComponent): string {
  const view = projectWolfSorcererState(role);
  if (!view) throw new Error("wolf_sorcerer_original_state_revoked");
  return JSON.stringify(view);
}

/**
 * 本族唯一数据槽：schema/get 是同一个原完整 live 校验，不新增严格接受政策或第二份状态。
 * install 收走原赋值，allowedWrites 只收走历史 descriptor 追加；expectedState／pair／committed
 * 仍由 frame 在原顺序更新。checkpoint 仅提供原 JSON 比较，方法表冻结不冻结输入状态／知识副本。
 */
export const WOLF_SORCERER_STATE_SLOT = Object.freeze({
  create: createWolfSorcererState,
  schema: getWolfSorcererState,
  get: getWolfSorcererState,
  project: projectWolfSorcererState,
  install: installWolfSorcererState,
  allowedWrites: Object.freeze({ appendHistory: appendWolfSorcererHistory }),
  checkpoint: Object.freeze({ identity: encodeWolfSorcererStateIdentity }),
});

/**
 * 负责分别推导狼队知识、聊天参与和刀权。输入为当前 World 角色及明确运行政策；输出保留队友、狼聊、狼刀名单和事件受众。狼阵营本身不等于拥有全部狼队权限，不据历史知识授予当前刀权。身份安装失败的退休仅关闭狼聊／刀执行，不抹已知队友或改写历史受众。
 */
import { scholarMentorPackBlocked } from "./scholar_mentor/night_frame";
import { animalPackKnifeBlocked } from "./animal_dream/authority";
import { nightmareKnifeBlocked } from "./nightmare_shadow/night_frame";
import { weddingMember, ghostBrideReady, weddingSetup } from "./ghost_bride/authority";
import { initialIdentitySetupReady } from "./initial_identity/deal";
import { COMPONENT } from "../../../core/domain/components/names";
import type { RoleComponent } from "../../../core/domain/components/role";
import { isRoleExecutionRetired } from "../../../core/domain/role-execution-authority";
import {
  Camp,
  type EntityId,
  type GameEvent,
  type WolfTeamEventType,
} from "../../../core/domain/model";
import type { World } from "../../../core/domain/world";
import type { RoleCatalog } from "./catalog";
import type { WolfTeamPermissions } from "./contracts";

const NO_ACCESS: WolfTeamPermissions = Object.freeze({
  recognizedByPack: false,
  recognizes: "none",
  canChat: false,
  canVoteForKill: false,
});

/** 只查询角色当前的明确权限；不依赖全局目录，也不写入角色或库存。 */
export function wolfTeamPermissions(
  role: RoleComponent | undefined,
  catalog: RoleCatalog,
  world?: World,
): WolfTeamPermissions {
  if (world && !initialIdentitySetupReady(world)) return NO_ACCESS;
  if (!role || role.camp !== Camp.Wolf) return NO_ACCESS;
  if (world && weddingSetup(world) && (!ghostBrideReady(world) || weddingMember(world, role)))
    return NO_ACCESS;
  const permissions = catalog.runtime(role.role)?.wolfTeam;
  const result =
    typeof permissions === "function" ? permissions(role, world) : (permissions ?? NO_ACCESS);
  const current = world &&
    (nightmareKnifeBlocked(world) ||
      scholarMentorPackBlocked(world) ||
      animalPackKnifeBlocked(world))
    ? { ...result, canVoteForKill: false }
    : result;
  // 原拒绝单例仍保身份，避免知识查询把它当新权限对象而继续读取。
  if (current === NO_ACCESS) return current;
  // 原资格和阻断查询先行；退休只拒演员执行，recognized／recognizes 仍供原知识查询使用。
  return isRoleExecutionRetired(role)
    ? { ...current, canChat: false, canVoteForKill: false }
    : current;
}

export function knownWolfTeammates(
  world: World,
  actorId: EntityId,
  catalog: RoleCatalog,
): EntityId[] {
  const viewer = wolfTeamPermissions(world.getComponent(actorId, COMPONENT.Role), catalog, world);
  if (viewer === NO_ACCESS) return [];
  const role = world.getComponent(actorId, COMPONENT.Role);
  const snapshot = role?.camp === Camp.Wolf && catalog.runtime(role.role)?.knownTeammates;
  if (snapshot)
    return [...new Set(snapshot(role!, world))]
      .filter((id) => id !== actorId && world.getComponent(id, COMPONENT.Role)?.camp === Camp.Wolf)
      .sort((a, b) => a - b);
  if (viewer.recognizes === "none") return [];
  // 身份知识独立于尚未公告的死亡，不能按真实存活状态重写已知队友。
  return world
    .entityIds()
    .filter((id) => {
      if (id === actorId) return false;
      const target = world.getComponent(id, COMPONENT.Role);
      if (target?.camp !== Camp.Wolf) return false;
      if (viewer.recognizes === "all") return true;
      if (viewer.recognizes === "pack")
        return wolfTeamPermissions(target, catalog, world).recognizedByPack;
      return viewer.recognizes.includes(target.role);
    })
    .sort((a, b) => a - b);
}

export function wolfChatParticipants(world: World, catalog: RoleCatalog): EntityId[] {
  return world
    .getAliveEntityIds()
    .filter(
      (id) => wolfTeamPermissions(world.getComponent(id, COMPONENT.Role), catalog, world).canChat,
    )
    .sort((a, b) => a - b);
}

export function wolfKnifeHolders(world: World, catalog: RoleCatalog): EntityId[] {
  return world
    .getAliveEntityIds()
    .filter(
      (id) =>
        wolfTeamPermissions(world.getComponent(id, COMPONENT.Role), catalog, world).canVoteForKill,
    )
    .sort((a, b) => a - b);
}

/** 在事实发布时捕获一次受众；此受众包只用于引擎／Tape，不随后续阵营变化补发历史。 */
export function wolfTeamEvent<K extends WolfTeamEventType>(
  world: World,
  catalog: RoleCatalog,
  event: Omit<Extract<GameEvent, { type: K }>, "audience">,
): Extract<GameEvent, { type: K }> {
  const recipients = wolfChatParticipants(world, catalog);
  if (event.type === "wolf_kill_vote_cast") recipients.push(...wolfKnifeHolders(world, catalog));
  return {
    ...event,
    audience: Object.freeze([...new Set(recipients)].sort((a, b) => a - b)),
  } as Extract<GameEvent, { type: K }>;
}

/**
 * 负责提交普通狼／赤月和白狼王的已选自爆。输入为捕获玩家、已校验选择和当前窗口；输出为原资源、事件与死亡提案。退休仅拒演员执行，目标和已付前缀仍保原规则；不执行真实标死或阶段／胜负封盘。
 */
import { RED_MOON_ROLE } from "../roles/red_moon_apostle/ports";
import { commitDemonRedMoonBlast } from "../roles/demon_hunter/authority";
import { canRoleSelfDestruct } from "../roles/self_destruct_capability";
import {
  weddingMember,
  weddingSetup,
  ghostBrideReady,
  swallowWeddingBadges,
} from "../roles/ghost_bride/authority";
import {
  ActionWindow,
  Phase,
  Role,
  DeathCause,
  type SelfDestructSelection,
  type DeathSources,
  type GameEvent,
} from "../../../core/domain/model";
import { COMPONENT } from "../../../core/domain/components/names";
import type { RoleComponent } from "../../../core/domain/components/role";
import { isRoleExecutionRetired } from "../../../core/domain/role-execution-authority";
import type { World } from "../../../core/domain/world";
import { getWhiteWolfKingState, consumeWhiteWolfDetonation } from "../roles/white_wolf_king/ports";
import { getDefaultRoleCatalog } from "../roles/role-catalog-assembly";

/** 仅提交本自爆能力的资源、事件和事实，返回死亡提案；实际死亡写入由结算器负责。 */
export function commitSelfDestructSelection(
  world: World,
  choice: SelfDestructSelection,
  window: ActionWindow,
  phase: Phase,
  events: GameEvent[],
): { deaths: number[]; sources: DeathSources } | null {
  if (
    !Object.values(ActionWindow).includes(window) ||
    phase !== (window === ActionWindow.OnPreVote ? Phase.Voting : Phase.Day)
  )
    return null;
  const role = world.getComponent(choice.actorId, COMPONENT.Role);
  if (!role || !world.getComponent(choice.actorId, COMPONENT.Alive)?.alive) return null;
  const ownsWedding = weddingSetup(world) !== null;
  if (
    ownsWedding &&
    (!ghostBrideReady(world) ||
      role.role !== Role.Wolf ||
      weddingMember(world, role) ||
      ![ActionWindow.OnPreElection, ActionWindow.OnPreVote].includes(window))
  )
    return null;
  const deaths = [choice.actorId],
    sources: DeathSources = { [choice.actorId]: [DeathCause.SelfDestruct] };
  if (choice.kind === "ordinary") {
    const redMoon = String(role.role) === RED_MOON_ROLE;
    if (
      choice.targetId !== null ||
      (redMoon
        ? ![ActionWindow.OnPreElection, ActionWindow.OnPreVote].includes(window)
        : !canRoleSelfDestruct(role, getDefaultRoleCatalog()))
    )
      return null;
    // 原普通能力／赤月窗口资格已经读取；直接赤月旁路也须在实际权威付款前拒退休演员。
    if (isRoleExecutionRetired(role)) return null;
    const moon = redMoon ? commitDemonRedMoonBlast(world, choice.actorId) : null;
    if (redMoon && !moon) return null;
    if (ownsWedding) swallowWeddingBadges(world, events);
    events.push({
      timestamp: Date.now(),
      type: "wolf_self_destruct",
      payload: { wolfId: choice.actorId, window },
    });
    if (moon?.sealsNight)
      events.push({
        timestamp: Date.now(),
        type: "red_moon_night_sealed",
        payload: { actorId: choice.actorId, day: moon.day, night: moon.day + 1 },
      });
  } else if (choice.kind === "white_wolf_king") {
    const state = getWhiteWolfKingState(role);
    if (role.role !== Role.WhiteWolfKing || state?.canDetonate !== true) return null;
    if (choice.targetId !== null) {
      if (
        choice.targetId === choice.actorId ||
        !world.getComponent(choice.targetId, COMPONENT.Alive)?.alive
      )
        return null;
      deaths.push(choice.targetId);
      sources[choice.targetId] = [DeathCause.WhiteWolfBlast];
    }
    // 同一库存和原目标预检在先；退休不消费库存，不取消目标身体或回滚任何已付前缀。
    if (isRoleExecutionRetired(role)) return null;
    consumeWhiteWolfDetonation(state);
    events.push({
      timestamp: Date.now(),
      type: "white_wolf_king_self_destruct",
      payload: { actorId: choice.actorId, targetId: choice.targetId, window },
    });
  } else return null;
  return { deaths, sources };
}

/**
 * 负责按真实存活阵营统计定义配置的淘汰条件。输入为 World 与胜负配置；输出为屠城、屠边和狼半条件的候选结果。不封盘或执行特殊关系胜利；判胜时点及唯一终态仍由引擎维护。
 */
import { ELIMINATION_PRIORITIES, type EliminationPriority } from "../../../core/domain/board";
import { demonHunterIsGod } from "../roles/demon_hunter/authority";
import { weddingFactionResult } from "../roles/ghost_bride/authority";
/** 文件说明：内置胜利条件规格实现。 */
import { cupidCityDecision } from "../roles/cupid/victory";
import { COMPONENT } from "../../../core/domain/components/names";
import { RoleComponent } from "../../../core/domain/components/role";
import { Camp, type WinDecision, WinCondition } from "../../../core/domain/model";
import { World } from "../../../core/domain/world";
import { getDefaultRoleCatalog } from "../roles/role-catalog-assembly";
import { WinConditionSpec } from "./contracts";
import { victoryDecision } from "./results";

interface AliveStat {
  wolves: number;
  gods: number;
  villagers: number;
  good: number;
}

function statAlive(world: World): AliveStat {
  const stat: AliveStat = {
    wolves: 0,
    gods: 0,
    villagers: 0,
    good: 0,
  };

  for (const id of world.getAliveEntityIds()) {
    const roleComp = world.getComponent(id, COMPONENT.Role);
    if (!roleComp) {
      continue;
    }

    if (roleComp.camp === Camp.Wolf) {
      stat.wolves += 1;
      continue;
    }

    if (roleComp.camp === Camp.Good) {
      stat.good += 1;
      const profile = getDefaultRoleCatalog().metadata(roleComp.role);
      if (profile?.goodSide === "god" || demonHunterIsGod(world, roleComp)) stat.gods += 1;
      else if (profile?.goodSide === "villager") stat.villagers += 1;
    }
  }

  return stat;
}

function evaluateSlaughterCity(
  world: World,
  priority: EliminationPriority = "awa_good_priority_v1",
): WinDecision | null {
  const cupid = cupidCityDecision(world);
  if (cupid) return cupid.decision;
  const stat = statAlive(world);
  if (priority === "awa_wolf_priority_v1" && stat.good === 0) {
    return victoryDecision(world, { kind: "faction", faction: Camp.Wolf }, "all_good_eliminated");
  }
  if (stat.wolves === 0) {
    return victoryDecision(world, { kind: "faction", faction: Camp.Good }, "all_wolves_eliminated");
  }
  if (stat.good === 0) {
    return victoryDecision(world, { kind: "faction", faction: Camp.Wolf }, "all_good_eliminated");
  }
  return null;
}

function evaluateSlaughterSide(
  world: World,
  priority: EliminationPriority = "awa_good_priority_v1",
): WinDecision | null {
  const stat = statAlive(world);
  if (priority === "awa_wolf_priority_v1" && (stat.gods === 0 || stat.villagers === 0)) {
    return victoryDecision(
      world,
      { kind: "faction", faction: Camp.Wolf },
      "slaughter_side_completed",
    );
  }
  if (stat.wolves === 0) {
    return victoryDecision(world, { kind: "faction", faction: Camp.Good }, "all_wolves_eliminated");
  }
  if (stat.gods === 0 || stat.villagers === 0) {
    return victoryDecision(
      world,
      { kind: "faction", faction: Camp.Wolf },
      "slaughter_side_completed",
    );
  }
  return null;
}

function evaluateWolfReachHalf(world: World): WinDecision | null {
  const stat = statAlive(world);
  if (stat.wolves === 0) {
    return victoryDecision(world, { kind: "faction", faction: Camp.Good }, "all_wolves_eliminated");
  }
  if (stat.wolves >= stat.good && stat.good > 0) {
    return victoryDecision(world, { kind: "faction", faction: Camp.Wolf }, "wolves_reach_half");
  }
  return null;
}

/** 默认胜利条件规格集合。 */
export const DEFAULT_WIN_CONDITION_SPECS: WinConditionSpec[] = [
  {
    id: WinCondition.ThreeFactionsElimination,
    checkpoints: ["night_settled", "exile_settled", "day_interrupted"],
    evaluate: (world) => {
      const result = weddingFactionResult(world);
      if (!result) return null;
      return result.faction === null
        ? { winner: null, reason: "three_factions_all_dead", outcome: { kind: "no_winner" } }
        : victoryDecision(
            world,
            { kind: "faction", faction: result.faction },
            "three_factions_eliminated",
          );
    },
  },
  {
    id: WinCondition.SlaughterCity,
    evaluate: (world) => evaluateSlaughterCity(world),
  },
  {
    id: WinCondition.SlaughterSide,
    evaluate: (world) => evaluateSlaughterSide(world),
  },
  {
    id: WinCondition.WolfReachHalf,
    evaluate: evaluateWolfReachHalf,
  },
];

/** Build immutable per-game choices without changing the cached legacy registry. */
export function createEliminationWinConditionSpecs(
  priority: EliminationPriority,
): WinConditionSpec[] {
  if (!ELIMINATION_PRIORITIES.includes(priority)) throw new Error("elimination_priority_invalid");
  return DEFAULT_WIN_CONDITION_SPECS.map((spec) => {
    if (spec.id === WinCondition.SlaughterCity)
      return { ...spec, evaluate: (world: World) => evaluateSlaughterCity(world, priority) };
    if (spec.id === WinCondition.SlaughterSide)
      return { ...spec, evaluate: (world: World) => evaluateSlaughterSide(world, priority) };
    return spec;
  });
}

