/** 查询只在原表达式处执行；尤其队友方法先查找原 callee，再读取 actorId。 */
export interface PlayerPromptDirectiveQueries {
  world(): World;
  locale(): Locale;
  catalog(): RoleCatalog;
  boardConfig(): ReadonlyBoardConfig | undefined;
  wolfTeammates(actorId: () => EntityId): EntityId[];
}

/** 映射的是提示所使用的规则角色，不启用技能、刷新库存或重检生命资格。 */
export function resolvePlayerPromptAbility(request: ActionRequest, role?: RoleComponent) {
  const bound = request.context.ability_id
    ? allNightAbilities(role).find((ability) => ability.id === request.context.ability_id)
    : undefined;
  const targetRuleRole =
    bound?.kind === "shelter"
      ? Role.RadiantCount
      : bound?.kind === "role_check"
        ? ROLE_INSPECTION_POLICY_ROLES[roleInspectionPolicy(bound.state)]
        : bound?.kind === "guard"
          ? Role.Guard
          : bound?.kind === "potion"
            ? Role.Witch
            : bound?.kind === "seer_check"
              ? Role.Seer
              : bound?.kind === "dream"
                ? Role.Dreamer
                : role?.role;
  return { bound, targetRuleRole };
}

/** 原角色技能简介只对动物板子的熊使用晨报说明；其它简介依当前 Catalog 与语言读取。 */
export function playerPromptRoleSkillBrief(
  role: Role,
  queries: Pick<PlayerPromptDirectiveQueries, "world" | "locale" | "catalog">,
): string {
  return role === Role.Bear && isAnimalDreamBoard(queries.world())
    ? text(queries.locale(), "role.bear.dawn_brief")
    : queries.catalog().skillBrief(role, queries.locale());
}

/** N+2 身份说明仍在模板／政策附注之后查询，不把构造时的公开配比当作当前库存。 */
export function appendPlayerPromptInitialIdentity(
  info: string,
  queries: Pick<PlayerPromptDirectiveQueries, "world" | "locale">,
): string {
  return initialIdentityCandidateCounts(queries.world())
    ? info +
        "\n" +
        text(
          queries.locale(),
          initialIdentityKind(queries.world()) === "shapeshifter"
            ? "prompt.board.shapeshifter"
            : "prompt.board.thief",
        )
    : info;
}

/** 各机制给出的已知视图分别读取，库存摘要保原来源，不能为缩短流程合并成真实全局状态。 */
export function buildPlayerStatusDirective(
  request: ActionRequest,
  role: RoleComponent | undefined,
  queries: Pick<PlayerPromptDirectiveQueries, "world" | "locale" | "catalog" | "wolfTeammates">,
): string | undefined {
  const lines: string[] = [];
  // 动物与专属板子读取已发表的玩家知识；不能用当前真实库存补造尚未通知的结果。
  if (isAnimalDreamBoard(queries.world())) {
    const state =
      role?.role === Role.FoxCub
        ? animalFoxKnowledge(queries.world(), request.actorId)
        : role?.role === Role.Pufferfish
          ? animalPufferKnowledge(queries.world(), request.actorId)
          : role?.role === Role.WhiteCat
            ? animalCatKnowledge(queries.world(), request.actorId)
            : null;
    if (state)
      lines.push(text(queries.locale(), "prompt.status.animal", { state: JSON.stringify(state) }));
  }
  if (role?.role === Role.FragrantPhantom && isFragrantPairBoard(queries.world())) {
    const known = fragrantPlayerKnowledge(queries.world(), request.phase, request.context.day);
    if (known.actorId === request.actorId)
      lines.push(
        text(queries.locale(), "prompt.status.fragrant", { state: JSON.stringify(known) }),
      );
  }
  if (isNobleBodyBoard(queries.world())) {
    const known = getNobleBodyPlayerState(queries.world(), request.actorId, request.phase);
    if (known)
      lines.push(
        text(
          queries.locale(),
          known.kind === "night_noble" ? "prompt.status.noble" : "prompt.status.secret_body",
          { state: JSON.stringify(known.state) },
        ),
      );
  }
  if (role?.role === Role.EclipseMaid) {
    const state = projectEclipseState(role);
    if (state)
      lines.push(text(queries.locale(), "prompt.status.eclipse", { state: JSON.stringify(state) }));
  }
  const alchemist = projectAlchemist(role),
    raven = projectRaven(role);
  if (alchemist)
    lines.push(
      text(queries.locale(), "prompt.status.alchemist", { state: JSON.stringify(alchemist) }),
    );
  if (raven)
    lines.push(text(queries.locale(), "prompt.status.raven", { state: JSON.stringify(raven) }));
  const weddingView = weddingActorView(queries.world(), request.actorId);
  if (weddingView)
    lines.push(
      text(queries.locale(), "prompt.status.wedding", { state: JSON.stringify(weddingView) }),
    );
  if (role?.role === Role.LonelyGirl)
    lines.push(
      text(queries.locale(), "prompt.status.lonely_girl", {
        state: JSON.stringify(projectLonelyGirl(queries.world(), role)),
      }),
    );
  if (role?.role === Role.WildChild)
    lines.push(
      text(queries.locale(), "prompt.status.wild_child", {
        state: JSON.stringify(projectWildChild(queries.world(), role)),
      }),
    );
  const thief = projectThiefState(role, queries.world()),
    choices = projectThiefChoices(queries.world(), request.actorId);
  const shape = projectShapeshifterState(role, queries.world()),
    shapeChoices = projectShapeshifterChoices(queries.world(), request.actorId);
  if (shape)
    lines.push(
      text(queries.locale(), "prompt.status.shapeshifter", {
        state: JSON.stringify({ ...shape, ...(shapeChoices ?? {}) }),
      }),
    );
  if (thief)
    lines.push(
      text(queries.locale(), "prompt.status.thief", {
        state: JSON.stringify({ ...thief, ...(choices ?? {}) }),
      }),
    );
  const wallNote = projectWallNote(queries.world(), request.actorId);
  if (wallNote)
    lines.push(
      text(queries.locale(), "prompt.status.wall_note", { state: JSON.stringify(wallNote) }),
    );
  lines.push(text(queries.locale(), "prompt.status.day", { day: getActionRequestDay(request) }));
  lines.push(
    text(queries.locale(), "prompt.status.wolf_teammates", {
      teammates:
        queries.wolfTeammates(() => request.actorId).join(", ") ||
        text(queries.locale(), "common.none"),
    }),
  );
  if (role)
    lines.push(
      text(queries.locale(), "ability.identity", {
        role: queries.catalog().label(role.role, queries.locale()),
        camp: term("camp", role.camp, queries.locale()),
      }),
    );
  // 自持能力仍用原实例／日期计算摘要；库存可见不等于本次行动可提交。
  for (const ability of allNightAbilities(role)) {
    const status = text(
      queries.locale(),
      `ability.status.${abilityStatus(ability, request.context.day)}`,
    );
    const state = projectNightState(ability);
    lines.push(
      text(queries.locale(), "ability.summary", {
        id: ability.id,
        kind: text(queries.locale(), `ability.kind.${ability.kind}`),
        status,
        uses:
          ability.maxUses === null
            ? text(queries.locale(), "ability.unlimited")
            : ability.maxUses - ability.uses,
        state: JSON.stringify(state),
      }),
    );
  }
  if (request.context.ability_id)
    lines.push(text(queries.locale(), "ability.bound_turn", { id: request.context.ability_id }));
  for (const gun of allDeathGuns(role)) {
    const projected = projectDeathGun(gun);
    lines.push(
      text(queries.locale(), "ability.death_gun.summary", {
        id: projected.id,
        status: text(queries.locale(), `ability.status.${projected.status}`),
        remaining: projected.remaining,
        granted: projected.grantedNight,
        armed: projected.armedOnNight ?? text(queries.locale(), "common.none"),
      }),
    );
  }
  // 历史及两次当前库存查询各保原位置，不能缓存一份清单来掩盖 caller getter 或生命周期变化。
  const history = ownNightActions(queries.world(), request.actorId, request.context.day);
  const hasLucky =
    allNightAbilities(role).some((ability) => ability.activation === "lucky") ||
    history.some((row) => row.lucky && (row.recipientPolicy ?? "lucky") === "lucky");
  const hasBlack =
    allNightAbilities(role).some((ability) => ability.activation === "black_market") ||
    history.some((row) => row.recipientPolicy === "black_market");
  if (hasLucky) lines.push(text(queries.locale(), "ability.lucky.rules"));
  if (hasBlack) lines.push(text(queries.locale(), "ability.black_market.rules"));
  if (hasLucky || hasBlack)
    lines.push(
      text(queries.locale(), "ability.lucky.history", { actions: JSON.stringify(history) }),
    );
  if (
    request.allowedTools.includes("dream") &&
    allNightAbilities(role).some((ability) => ability.kind === "dream")
  ) {
    lines.push(text(queries.locale(), "ability.dream.rules"));
    const state = getDreamerState(role!, request.context.ability_id);
    lines.push(
      text(
        queries.locale(),
        state?.protectionPolicy === "netease_2026_night_immunity_v1"
          ? "role.dreamer.protection_netease"
          : "role.dreamer.protection_awa",
      ),
    );
  }
  if (role && request.allowedTools.includes("inspect_role")) {
    const inspection = getRoleInspectionState(role, request.context.ability_id);
    if (inspection)
      lines.push(
        inspection.inspectionPolicy
          ? renderInspectionPolicy(inspection, queries.locale())
          : text(
              queries.locale(),
              roleInspectionPolicy(inspection) === "psychic"
                ? "ability.role_check.psychic_rules"
                : roleInspectionPolicy(inspection) === "mirror"
                  ? "ability.role_check.mirror_rules"
                  : "ability.role_check.rules",
            ),
      );
  }
  if (debateVoteBlocked(queries.world(), request.actorId, request.context.day))
    lines.push(text(queries.locale(), "prompt.status.debate_penalty"));
  const lover = projectLover(queries.world(), request.actorId);
  if (lover) {
    lines.push(text(queries.locale(), "prompt.status.lover", { partner: lover.partnerId }));
    if (lover.mayNotVotePartner) lines.push(text(queries.locale(), "prompt.status.lovers_vote"));
  }
  // 原文最后调用；optional-call 在没有 renderer 时不读取语言，不提前捕获自定义回调结果。
  const privateState = rolePresentationRenderer(role)?.(queries.locale()).trim();
  if (privateState)
    lines.push(text(queries.locale(), "prompt.status.private", { state: privateState }));
  if (role?.role === Role.Idiot && getIdiotState(role)?.revealed) {
    lines.push(text(queries.locale(), "prompt.status.idiot"));
  }
  return lines.length ? lines.join(" ") : undefined;
}

/** 说明原请求候选与首日警长时序；这里不重新推导合法目标、不授予窗口或改变失败政策。 */
export function buildPlayerStageContextHint(
  request: ActionRequest,
  queries: Pick<PlayerPromptDirectiveQueries, "locale" | "boardConfig">,
): string | undefined {
  // 按原字段优先级展示请求已带来的候选，不据这些文字重新授权目标。
  if (request.context.fox_candidates)
    return text(queries.locale(), "prompt.stage.fox_candidates", {
      ids: request.context.fox_candidates.join(", "),
    });
  const pairCandidates =
    request.context.fragrant_pair_candidates ?? request.context.pair_check_candidates;
  if (pairCandidates)
    return text(queries.locale(), "prompt.stage.fragrant_pair_candidates", {
      ids: pairCandidates.join(", "),
    });
  if (request.context.wolf_kill_candidates !== undefined)
    return text(queries.locale(), "prompt.stage.wolf_kill_candidates", {
      candidates:
        request.context.wolf_kill_candidates.join(", ") || text(queries.locale(), "common.none"),
    });
  if (request.context.stage === "alchemist_snake")
    return text(queries.locale(), "prompt.stage.snake", {
      target: request.context.snake_target ?? text(queries.locale(), "common.none"),
      candidates:
        (request.context.snake_candidates ?? []).join(", ") ||
        text(queries.locale(), "common.none"),
    });
  if (request.context.stage === "alchemist_mist")
    return text(queries.locale(), "prompt.stage.mist", {
      candidates: (request.context.mist_candidates ?? []).join(", "),
    });
  if (request.context.stage === "raven_knife")
    return text(queries.locale(), "prompt.stage.raven_knife", {
      candidates: (request.context.raven_candidates ?? []).join(", "),
    });
  const stage = getActionRequestStage(request);
  const day = getActionRequestDay(request);
  // 板子 getter 在原两个表达式分别读取；! 仅消除类型缩窄丢失，不缓存或新增运行时拒绝。
  const firstDaySheriffTiming =
    day === 1 &&
    queries.boardConfig()?.enableSheriff === true &&
    !settlesNightBeforeDay(queries.boardConfig()!) &&
    ["sheriff_nomination", "sheriff_campaign_speech", "sheriff_withdraw", "sheriff_vote"].includes(
      stage,
    )
      ? text(queries.locale(), "prompt.stage.sheriff_timing")
      : undefined;
  if (stage === "sheriff_nomination") {
    return [text(queries.locale(), "prompt.stage.sheriff_nomination"), firstDaySheriffTiming]
      .filter(Boolean)
      .join(" ");
  }
  if (stage === "sheriff_campaign_speech") {
    return firstDaySheriffTiming;
  }
  if (stage === "sheriff_withdraw") {
    return [text(queries.locale(), "prompt.stage.sheriff_withdraw"), firstDaySheriffTiming]
      .filter(Boolean)
      .join(" ");
  }
  if (stage === "sheriff_vote") {
    return [text(queries.locale(), "prompt.stage.sheriff_vote"), firstDaySheriffTiming]
      .filter(Boolean)
      .join(" ");
  }
  if (stage === "scholar_mentor_choice")
    return text(queries.locale(), "prompt.stage.modifier_choice", {
      modes: (request.context.modifier_modes ?? []).join(", "),
    });
  if (stage === "scholar_mentor_bonus")
    return text(queries.locale(), "prompt.stage.modifier_bonus", {
      kind: request.context.modifier_bonus_kind ?? "",
    });
  if (stage !== "witch") {
    const onlySelfDestruct =
      Object.values(ActionWindow).includes(stage as ActionWindow) &&
      request.allowedTools.every(
        (tool) =>
          tool === "self_destruct" || tool === "self_destruct_with_target" || tool === "report_bug",
      );
    return onlySelfDestruct
      ? text(queries.locale(), "prompt.stage.blast_only", {
          tool: request.allowedTools.includes("self_destruct_with_target")
            ? "self_destruct_with_target"
            : "self_destruct",
        })
      : undefined;
  }
  if (request.context.wolf_targets !== undefined)
    return request.context.wolf_targets.length
      ? text(queries.locale(), "prompt.stage.wolf_targets", {
          targets: request.context.wolf_targets.join(", "),
        })
      : text(queries.locale(), "prompt.stage.no_wolf_target");
  if (typeof request.context.wolf_target === "number") {
    return text(queries.locale(), "prompt.stage.wolf_target", {
      target: request.context.wolf_target,
    });
  }
  return request.context.wolf_target === null
    ? text(queries.locale(), "prompt.stage.no_wolf_target")
    : text(queries.locale(), "prompt.stage.unknown_wolf_target");
}

/**
 * 负责角色展示的实际创建与运行绑定。输入是原角色、阵营、默认语言或 Catalog 安装的
 * 展示闭包；输出保持同一角色对象、当前 role 标签和晚调用的提示。绑定仅保存旧闭包的
 * 展示元数据，不复制 privateState、World 或库存，不授予行动或编码归档。
 * 未 applyRuntime 的角色只展示 component.role；只有实际初始化后才消费内建／自定义贡献。
 */
import type { Locale } from "@ai-werewolf-arena/game-contract";
import { roleName, text } from "@ai-werewolf-arena/game-text";
import { Camp, Role } from "@ai-werewolf-arena/game-contract";
import {
  createRoleComponent as createDomainRoleComponent,
  type RoleComponent,
} from "../../core/domain/components/role";

// 唯一展示绑定保存原闭包引用；角色状态仍只在 World 中的原组件。
const presentations = new WeakMap<RoleComponent, (locale?: Locale) => string>();

export function createRoleComponent(
  role: Role,
  camp: Camp,
  locale: Locale = "zh-CN",
): RoleComponent {
  const component = createDomainRoleComponent(role, camp);
  bindRolePresentation(component, (displayLocale: Locale = locale) =>
    text(displayLocale, "component.role", { role: roleName(component.role, displayLocale) }),
  );
  return component;
}

/** 初始化所有者安装闭包；调用方不能据此获得角色私有状态写权限。 */
export function bindRolePresentation(
  role: RoleComponent,
  renderer: (locale?: Locale) => string,
): void {
  presentations.set(role, renderer);
}

/** 保留原可选 render 方法的存在性语义，调用时才执行已绑定的具体贡献。 */
export function rolePresentationRenderer(
  role: RoleComponent | undefined,
): ((locale?: Locale) => string) | undefined {
  return role && presentations.get(role);
}

export function renderRolePrompt(role: RoleComponent, locale?: Locale): string {
  const renderer = rolePresentationRenderer(role);
  if (!renderer) throw new Error("role_presentation_not_bound");
  return renderer(locale);
}

/**
 * 负责 checkpoint 玩家记录的有序编码。输入为同一 World、完整／失败模式和最初动物审计快照；
 * 输出保留恶魔原体优先；私有状态由数据 owner 在原字段位置编码，其余完整字段和顺序仍归本装配。
 * 原体 descriptor、JSON、重复组件读取和 fallback 克隆各在原表达式处执行；不修改 live 状态。
 * 壁上便签、恋人、处罚、胜利、投票、警徽和印记贡献只编码，不推导新规则或授予行动权限。
 */
import {
  COMPONENT,
  type BadgeComponent,
  type IdentityComponent,
  type RoleComponent,
  type StatusMarksComponent,
  type VotingRightComponent,
  type VictoryComponent,
  type World,
} from "../../core";
import type { RecordedCheckpoint } from "../reproduction";
import type { prepareAnimalCheckpoint } from "./authority-snapshots";
import { auditData } from "./animal-audit";
import { encodeCheckpointPrivateState } from "./private-state-codec";
import { aliveLifeDescriptor } from "../../core/domain/components/alive";
import {
  animalOriginalAuditPlayer,
  animalOriginalAuditIds,
} from "../../game/mechanisms/roles/animal_dream/roster";
import { demonHunterCheckpointPlayers } from "../../game/mechanisms/roles/demon_hunter/authority";
import { weddingAuditPlayer } from "../../game/mechanisms/roles/ghost_bride/authority";
import {
  projectLonelyGirlVictory,
  projectLonelyGirlAuditPlayer,
} from "../../game/mechanisms/roles/lonely_girl/lifecycle";
import { projectWallNote } from "../../game/mechanisms/events/wall_notes/authority";

/** 同一调用按原权威优先级编码；数据可供归档核验，不能替代运行时原体或库存许可。 */
export function capturePlayerContributions(
  world: World,
  complete: boolean,
  animal: ReturnType<typeof prepareAnimalCheckpoint>,
): RecordedCheckpoint["players"] {
  return (
    // 恶魔板的完整原参与者快照优先返回；非 null 时不读取后面的席位名单或其它贡献。
    demonHunterCheckpointPlayers(world, complete) ??
    (animalOriginalAuditIds(world) ?? world.entityIds()).map((id) => {
      // 动物失败审计保留最初授权身体；身份／票权／警徽从捕获数据解码，普通路径才读取当前组件。
      const original = animal ? animalOriginalAuditPlayer(world, id) : null;
      const identity = original
        ? (JSON.parse(original.identityJson) as IdentityComponent)
        : world.getComponent(id, COMPONENT.Identity)!;
      const role = original?.scope.role ?? world.getComponent(id, COMPONENT.Role)!;
      const badge = original
        ? (auditData(original.audit.badge, [
            "isSheriff",
            "destroyed",
            "voteWeight",
            "handoffPolicy",
          ]) as BadgeComponent)
        : world.getComponent(id, COMPONENT.Badge)!;
      const vote = original
        ? (auditData(original.audit.vote, ["weight", "canVote"]) as VotingRightComponent)
        : world.getComponent(id, COMPONENT.VotingRight)!;
      const weddingAudit = weddingAuditPlayer(world, id, !complete);
      // 婚约审计优先于孤女审计；此处覆盖的是记录字段，不改角色真实阵营或独立胜利成员。
      const audit = weddingAudit ?? projectLonelyGirlAuditPlayer(world, id);
      const wall = projectWallNote(world, id);
      const wallNote = wall
        ? {
            instanceId: wall.instanceId,
            source: { ...wall.source },
            remaining: wall.remaining,
            expired: wall.expired,
          }
        : undefined;
      return {
        id,
        seat: identity.seat,
        name: identity.name,
        role: (original?.scope.roleId as RoleComponent["role"]) ?? audit?.role ?? role.role,
        camp: original?.scope.campValue ?? audit?.camp ?? role.camp,
        alive: original
          ? aliveLifeDescriptor(original.scope.life)!.get!.call(original.scope.life)
          : (audit?.alive ?? world.getComponent(id, COMPONENT.Alive)!.alive),
        // 原特殊审计优先级与整容器克隆归数据 owner；这里只在原字段位置传入已求出的引用。
        privateState: encodeCheckpointPrivateState(world, id, complete, animal, original, role, audit),
        ...(wallNote ? { wallNote } : {}),
        // 可选组件先判断、再现场读取并克隆；getter／克隆失败仍从原表达式传播，不补空记录。
        ...(world.getComponent(id, COMPONENT.DebatePenalty)
          ? {
              debatePenalty: structuredClone(world.getComponent(id, COMPONENT.DebatePenalty)!),
            }
          : {}),
        ...(world.getComponent(id, COMPONENT.Lovers)
          ? {
              lovers: structuredClone(world.getComponent(id, COMPONENT.Lovers)!),
            }
          : {}),
        // 原动物、婚约及孤女胜利记录先于普通组件克隆；失败审计和当前成功记录不可互换来源。
        victory:
          (original ? (JSON.parse(original.victoryJson) as VictoryComponent) : null) ??
          (weddingAudit ? { affiliations: weddingAudit.victory } : null) ??
          projectLonelyGirlVictory(world, id) ??
          structuredClone(world.getComponent(id, COMPONENT.Victory)!),
        vote: { weight: vote.weight, canVote: vote.canVote },
        badge: {
          isSheriff: badge.isSheriff,
          destroyed: badge.destroyed,
          voteWeight: badge.voteWeight,
          ...(badge.handoffPolicy ? { handoffPolicy: badge.handoffPolicy } : {}),
        },
        marks: (
          (original?.audit.marks as StatusMarksComponent | undefined) ??
          world.getComponent(id, COMPONENT.StatusMarks)!
        ).values(),
      };
    })
  );
}

/**
 * 负责狼美人放逐定案的候选捕获、整侧完成核对及屠边覆盖数据，保留两个同步业务时点。
 * 输入为原有效放逐结果、晚读 World 和同一魅惑绑定；输出为原目标、可写候选或真实 Victory 成员判定。
 * 普通板在死亡波前捕获末狼和目标侧；波后仍需 applied、原体当前性及目标实际死亡，不能靠提案提前获胜。
 * 覆盖只供 exile_settled 的 slaughter_side 项，配置首命中顺序和唯一封盘仍归经理／条件注册表。
 * 本模块不持第二份关系、不领取牵连、不退款、不标死、不推进阶段；查询异常保留已提交死亡前缀。
 * 规则见 docs/rules/awa-wolf-beauty-v1.md；候选不进入玩家知识或档案，不授予行动权限。
 */
import { Camp, Role, WinCondition, type EntityId, type VotingSummary, type WinDecision } from "../core/domain/model";
import { COMPONENT } from "../core/domain/components/names";
import type { World } from "../core/domain/world";
import { activeCharm, isCharmBindingCurrent, type CharmBinding } from "../game/mechanisms/roles/wolf_beauty/ports";
import { getDefaultRoleCatalog } from "../game/mechanisms/roles/role-catalog-assembly";
import { victoryDecision } from "../game/mechanisms/win_conditions/results";

/** 仅读原结果字段；readonly 不冻结原数组，也不证明目标已经死亡或取得死亡许可。 */
export interface BeautyExileSelection {
  readonly summary: Pick<VotingSummary, "target" | "effectiveTarget">;
  readonly removed: readonly EntityId[];
}

/** 仍为原可写候选，绑定保同一运行引用；目标侧只在死亡波前捕获，不在波后重新推断。 */
export interface BeautyExileCandidate {
  actorId: EntityId;
  targetId: EntityId;
  side: "god" | "villager";
  binding: CharmBinding;
}
/**
 * 只在经理原普通放逐分支调用；effectiveTarget 有定义时保留原两次 getter 读取。
 * 先核非 null 和真实移除名单，之后才取得 World；不合格目标不捕获关系或查询隐藏狼数。
 */
export function prepareBeautyExileVictory(
  selection: BeautyExileSelection,
  world: () => World,
): { target: EntityId | null; candidate: BeautyExileCandidate | null } {
  const target =
    selection.summary.effectiveTarget === undefined
      ? selection.summary.target
      : selection.summary.effectiveTarget;
  const candidate = target !== null && selection.removed.includes(target)
    ? captureBeautyExile(world(), target)
    : null;
  return { target, candidate };
}

/** 仅在真实放逐已确定、完整死亡波尚未执行时捕获候选，不提前封盘。 */
function captureBeautyExile(world: World, actorId: EntityId): BeautyExileCandidate | null {
  const actor = world.getComponent(actorId, COMPONENT.Role),
    binding = activeCharm(world, actorId);
  if (
    actor?.role !== Role.WolfBeauty ||
    actor.camp !== Camp.Wolf ||
    !binding ||
    !binding.targetLife.alive
  )
    return null;
  if (
    world
      .getAliveEntityIds()
      .some((id) => id !== actorId && world.getComponent(id, COMPONENT.Role)?.camp === Camp.Wolf)
  )
    return null;
  const target = world.getComponent(binding.targetId, COMPONENT.Role),
    side = target ? getDefaultRoleCatalog().metadata(target.role)?.goodSide : undefined;
  return target?.camp === Camp.Good && side
    ? { actorId, targetId: binding.targetId, side, binding }
    : null;
}
/**
 * 调用方已完成死亡波并通过原当前性守卫；已领取／被阻断仍不等于 applied。
 * 原绑定校验继续归 relation，同侧存活扫描之后才由共同结果 owner 捕获真实 Victory 成员。
 */
export function resolveBeautyExileVictory(
  world: World,
  candidate: BeautyExileCandidate | null,
): WinDecision | null {
  if (
    !candidate ||
    !candidate.binding.applied ||
    !isCharmBindingCurrent(world, candidate.binding) ||
    candidate.binding.targetLife.alive
  )
    return null;
  const sideAlive = world.getAliveEntityIds().some((id) => {
    const role = world.getComponent(id, COMPONENT.Role);
    return (
      role?.camp === Camp.Good &&
      getDefaultRoleCatalog().metadata(role.role)?.goodSide === candidate.side
    );
  });
  return sideAlive
    ? null
    : victoryDecision(world, { kind: "faction", faction: Camp.Wolf }, "wolf_beauty_last_exile");
}

/**
 * 在经理 checkAndSealResult 的第二实参位置生成覆盖，不能提前到 callee 或 checkpoint 读取之前。
 * 空结果仍返回原空对象；只覆盖屠边项，不绕过配置中排在前面的其它胜利条件。
 */
export function beautyExileVictoryOverrides(
  result: WinDecision | null,
): Partial<Record<WinCondition, WinDecision>> {
  return result ? { [WinCondition.SlaughterSide]: result } : {};
}

/**
 * 负责白天自爆的有限规则组合：婚礼禁用、红月资格、普通自爆与白狼王库存共同约束选择。
 * 输入为原 World、角色工具表、请求构造端口、Provider、网关及窗口回调；输出为首个未被拒绝的选择或 null。
 * 并发请求保原 Promise.all 顺序；等待后按原体／生命版本／库存与目标复验，再按玩家编号尝试提交。
 * 捕获的存活组件和资源引用仅服务本次窗口；阶段 current、库存付款、死亡与最终判胜各归原 owner。安装失败的退休只拒演员，目标和纯数据仍保原查询。
 * commit 返回 false 只跳过该选择；读取、Provider 或提交失败沿原异常传播，不补提交或回滚已写前缀。
 */
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { RED_MOON_ROLE } from "../game/mechanisms/roles/red_moon_apostle/ports";
import { demonRedMoonCanBlast } from "../game/mechanisms/roles/demon_hunter/ports";
import { canRoleSelfDestruct } from "../game/mechanisms/roles/self_destruct_capability";
import { getDefaultRoleCatalog } from "../game/mechanisms/roles/role-catalog-assembly";
import {
  weddingMember,
  weddingSetup,
  ghostBrideReady,
} from "../game/mechanisms/roles/ghost_bride/ports";
import { AliveComponent, aliveLifeVersion } from "../core/domain/components/alive";
import { COMPONENT } from "../core/domain/components/names";
import { RoleComponent } from "../core/domain/components/role";
import { isRoleExecutionRetired } from "../core/domain/role-execution-authority";
import {
  ActionProvider,
  ActionWindow,
  Phase,
  type SelfDestructSelection,
} from "../core/domain/model";
import { RoleRegistry } from "../core/domain/registries/role_registry";
import { World } from "../core/domain/world";
import { ToolGateway } from "../game/gateway/tool_gateway";
import type { ActionRequestConstructionPort } from "../core/domain/actions";
import { getWhiteWolfKingState } from "../game/mechanisms/roles/white_wolf_king/ports";

/** 并发收集选项，按编号升序复验并尝试提交；回调明确返回 false 时跳过该选项，返回首个未被拒绝的选择。 */
export class SelfDestructWindow {
  constructor(
    private readonly world: World,
    private readonly roleRegistry: RoleRegistry,
    private readonly toolGateway: ToolGateway,
  ) {}

  async execute(
    requests: ActionRequestConstructionPort,
    provider: ActionProvider,
    window: ActionWindow,
    phase: Phase,
    isCurrent: () => boolean = () => true,
    commit?: (choice: SelfDestructSelection) => Promise<void | boolean>,
  ): Promise<SelfDestructSelection | null> {
    if (!isCurrent()) return null;
    // 先捕获所有原存活身体和生命版本；后续目标死后复活或换组件不能复用旧选择。
    const targets = new Map(
      this.world.getAliveEntityIds().map((id) => {
        const alive = this.world.getComponent(id, COMPONENT.Alive)!;
        return [id, { alive, version: aliveLifeVersion(alive) }] as const;
      }),
    );
    // 各玩家请求并发，结果排列仍由原存活名单决定；不以最早响应决定谁自爆。
    const picks = await Promise.all(
      this.world.getAliveEntityIds().map(async (actorId) => {
        const role = this.world.getComponent(actorId, COMPONENT.Role);
        if (!role) return null;
        if (
          weddingSetup(this.world) &&
          (!ghostBrideReady(this.world) || weddingMember(this.world, role))
        )
          return null;
        const tools = this.roleRegistry.getAllowedTools(role.role);
        const tool = tools.includes("self_destruct_with_target")
          ? "self_destruct_with_target"
          : tools.includes("self_destruct")
            ? "self_destruct"
            : null;
        if (!tool) return null;
        if (
          tool === "self_destruct" &&
          (String(role.role) === RED_MOON_ROLE
            ? !demonRedMoonCanBlast(this.world, actorId)
            : !canRoleSelfDestruct(role, getDefaultRoleCatalog()))
        )
          return null;
        // 白狼王复验同一库存对象；这里不消费，实际消耗仍归提交函数。
        const resource =
          tool === "self_destruct_with_target" ? getWhiteWolfKingState(role) : undefined;
        if (tool === "self_destruct_with_target" && resource?.canDetonate !== true) return null;
        // 原特殊资格和库存读取先行，保其首错误；已退休演员不再建立新请求。
        if (isRoleExecutionRetired(role)) return null;
        const life = targets.get(actorId)!;
        const request = requests.create({
          phase,
          actionWindow: window,
          actorId,
          allowedTools: [tool],
          stage: window,
          requiresAction: false,
          summary: {
            key:
              phase === Phase.Voting
                ? "request.summary.self_destruct_pre_vote"
                : "request.summary.self_destruct",
          },
          context: {},
        });
        const action = await provider.getAction(request);
        if (
          action?.name !== tool ||
          (action.name !== "self_destruct" && action.name !== "self_destruct_with_target")
        )
          return null;
        const choice: SelfDestructSelection =
          action.name === "self_destruct"
            ? { kind: "ordinary", actorId, targetId: null }
            : { kind: "white_wolf_king", actorId, targetId: action.args.target_id };
        return { choice, action, role, resource, life };
      }),
    );
    if (!isCurrent()) return null;
    // 提交前重复检查原玩家、目标、生命版本及特殊规则；字段恢复不抹去生命版本变化。
    const stillCurrent = (pick: NonNullable<(typeof picks)[number]>) => {
      const { actorId, targetId } = pick.choice;
      if (
        !isCurrent() ||
        (weddingSetup(this.world) &&
          (!ghostBrideReady(this.world) || weddingMember(this.world, pick.role))) ||
        this.world.getComponent(actorId, COMPONENT.Role) !== pick.role ||
        this.world.getComponent(actorId, COMPONENT.Alive) !== pick.life.alive ||
        !pick.life.alive.alive ||
        pick.life.version === undefined ||
        aliveLifeVersion(pick.life.alive) !== pick.life.version
      )
        return false;
      if (String(pick.role.role) === RED_MOON_ROLE && !demonRedMoonCanBlast(this.world, actorId))
        return false;
      if (
        pick.choice.kind === "white_wolf_king" &&
        (getWhiteWolfKingState(pick.role) !== pick.resource || pick.resource?.canDetonate !== true)
      )
        return false;
      if (targetId !== null) {
        const target = targets.get(targetId);
        if (
          !target ||
          this.world.getComponent(targetId, COMPONENT.Alive) !== target.alive ||
          !target.alive.alive ||
          target.version === undefined ||
          aliveLifeVersion(target.alive) !== target.version
        )
          return false;
      }
      // 等待后先完成原特殊权威、库存与目标复验；字段恢复不复活这个失败演员。
      return !isRoleExecutionRetired(pick.role);
    };
    // 网关预检前后均复验；预检成功只产生候选，不意味着库存付款或死亡已生效。
    const valid = picks.filter(
      (pick): pick is NonNullable<typeof pick> =>
        pick !== null &&
        stillCurrent(pick) &&
        this.toolGateway.validateAndSanitize(this.world, pick.choice.actorId, pick.action, {
          phase,
          actionWindow: window,
          allowSelfDestruct: true,
        }).ok &&
        stillCurrent(pick),
    );
    // 按玩家编号串行调用可选提交；false 跳过，异常停止并保留此前提交的前缀。
    for (const pick of valid.sort((a, b) => a.choice.actorId - b.choice.actorId)) {
      if (!isCurrent()) return null;
      if (!stillCurrent(pick)) continue;
      if ((await commit?.(pick.choice)) === false) continue;
      return pick.choice;
    }
    return null;
  }
}

/** 显式空窗口列表禁用全部机会；只有未配置列表才回退到原投票前默认窗口。 */
export function isSelfDestructWindowEnabled(
  config: ReadonlyBoardConfig,
  window: ActionWindow,
): boolean {
  return config.selfDestruct?.enabledWindows === undefined
    ? window === ActionWindow.OnPreVote
    : config.selfDestruct.enabledWindows.includes(window);
}

/**
 * 负责普通狼狼聊、狼刀和自爆的完整工具准入组合，供共享普通狼装配及派生角色引用。
 * 输入为当前角色运行政策、原 World、阶段／窗口和工具上下文；输出为原首个拒绝或 null。
 * 婚礼狼刀先由鬼魂新娘原权威复验，否则依次检查狼队刀权、阶段、工具、pass 与只读目标贡献。
 * 同一可写规则表保留 callback 引用；派生展开与晚读取仍发生在原 profile／Registry 调用点。
 * 准入不执行工具、付款、开启窗口或授予租约；候选允许结果不能代替真正提交时的权限复验。
 */
import { canRoleSelfDestruct } from "../game/mechanisms/roles/self_destruct_capability";
import { bindWolfKnifeTargetQuery } from "../game/mechanisms/roles/wolf/ports";
import {
  weddingMember,
  weddingSetup,
  ghostBrideReady,
  canSubmitWeddingTool,
} from "../game/mechanisms/roles/ghost_bride/ports";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { ActionWindow, Phase } from "../core/domain/model";
import type { ToolRuleMap } from "../game/mechanisms/validation/contracts";
import { wolfTeamPermissions } from "../game/mechanisms/roles/wolf_team";

/** 三工具保持各自完整首失败顺序；不把婚礼刀权、普通候选或自爆窗口统一成新授权策略。 */
export const WOLF_VALIDATION_RULES: ToolRuleMap = {
  speak_to_wolves: ({ world, role, roleCatalog, phase }) => {
    if (!wolfTeamPermissions(role, roleCatalog, world).canChat) {
      return { code: RuleError.WolfChatPermission };
    }
    if (phase !== Phase.Night) return { code: RuleError.WolfChatPhase };
    return null;
  },
  kill_vote: ({ world, actorId, day, ghostBrideScope, role, roleCatalog, toolCall, phase }) => {
    // 婚礼分支优先；缺省日次仍为 0，不继续读取普通狼队政策或候选。
    if (weddingSetup(world))
      return canSubmitWeddingTool(world, actorId, phase, day ?? 0, ghostBrideScope, toolCall)
        ? null
        : { code: RuleError.GhostBrideUnavailable };
    if (!wolfTeamPermissions(role, roleCatalog, world).canVoteForKill) {
      return { code: RuleError.WolfKillPermission };
    }
    if (phase !== Phase.Night) return { code: RuleError.WolfKillPhase };
    if (toolCall.name !== "kill_vote") {
      return { code: RuleError.ToolMismatch };
    }
    // 原 pass 先于目标查询；非 pass 且首个目标非 null 时，保留三次 args 与两次 target_id 的现场读取。
    if (toolCall.args.abstain) {
      return null;
    }
    if (
      toolCall.args.target_id === null ||
      !bindWolfKnifeTargetQuery(world).allows(toolCall.args.target_id)
    ) {
      return { code: RuleError.KillTarget };
    }
    return null;
  },
  self_destruct: ({
    world,
    role,
    roleCatalog,
    phase,
    actionWindow,
    allowSelfDestruct,
    toolCall,
  }) => {
    // 原婚礼成员排除先于角色自爆能力；阶段与窗口关系通过后检查已取出的 allowSelfDestruct，再读工具名／confirm。
    if (weddingSetup(world) && (!ghostBrideReady(world) || weddingMember(world, role)))
      return { code: RuleError.WolfBlastOnly };
    if (!canRoleSelfDestruct(role, roleCatalog)) {
      return { code: RuleError.WolfBlastOnly };
    }
    if (phase !== Phase.Day && phase !== Phase.Voting) {
      return { code: RuleError.BlastPhase };
    }
    if (actionWindow === undefined || !Object.values(ActionWindow).includes(actionWindow)) {
      return { code: RuleError.BlastWindow };
    }
    if (phase !== (actionWindow === ActionWindow.OnPreVote ? Phase.Voting : Phase.Day))
      return { code: RuleError.BlastPhase };
    if (!allowSelfDestruct) {
      return { code: RuleError.BlastDisabled };
    }
    if (toolCall.name !== "self_destruct" || toolCall.args.confirm !== true) {
      return { code: RuleError.BlastConfirm };
    }
    return null;
  },
};

/**
 * 负责把新增领域事件与当时获授权的玩家视图交给会话记录器，返回完成处理的展示增量。
 * 输入为本局原 World 和事件序列；输出为 God／玩家记录，最终落盘归会话记录器。
 * 本模块拥有事件游标、记录日期／阶段和玩家局部序号，不推进游戏阶段或选择行动。
 * 记录失败向调用方传播并保留已追加前缀；领域提交与受众授权仍由各自所有者负责。
 * 游标不是跨失败重放的事务保证，不能把一次中途异常当成整条事件从未记录。
 */
import type { World } from "../core/domain/world";
import type { GameEvent } from "@ai-werewolf-arena/game-contract/events";
import { COMPONENT, RoleComponent } from "../core";
import { buildAgentVisibleEvent } from "../game/engine/agent_visible_event_feed";
import { getDefaultScriptEventRenderRegistry } from "../game";
import type { SessionRecordManager } from "../recording/session_recorder";

/** 持有同一局的领域读取入口与记录入口，不创建第二份状态或自行管理记录器关闭。 */
export interface GameEventRecorderOptions {
  world: World;
  replayManager: SessionRecordManager;
}

export class GameEventRecorder {
  private recordedEventIndex = 0;
  // 每位玩家只为可见事件递增序号，不能用 God 事件索引泄漏隐藏行动数量。
  private readonly playerVisibleEventSeq = new Map<number, number>();
  // 这是复盘记录的标签游标；只随 phase_changed 更新，不写回领域阶段。
  private replayDayCursor = 1;
  private replayPhaseCursor: string;

  constructor(
    private readonly options: GameEventRecorderOptions,
    initialPhase: string,
  ) {
    this.replayPhaseCursor = initialPhase;
  }

  /** 从事件游标处理新增事实；只有当前事件全部处理完成后才推进该游标。 */
  flush(events: readonly GameEvent[]): GameEvent[] {
    const delta: GameEvent[] = [];
    const stageRegistry = getDefaultScriptEventRenderRegistry();
    for (let i = this.recordedEventIndex; i < events.length; i += 1) {
      const event = events[i];
      const stage = stageRegistry.toReplayStage(event);
      if (event.type === "phase_changed") {
        this.replayDayCursor = Number(event.payload.day ?? this.replayDayCursor);
        this.replayPhaseCursor = String(event.payload.phase ?? this.replayPhaseCursor);
      }
      // God 记录先追加，随后逐玩家投影；后续失败不撤销先前已追加的记录。
      this.options.replayManager.recordPublicEvent({
        type: event.type,
        timestampMs: event.timestamp,
        day: this.replayDayCursor,
        phase: this.replayPhaseCursor,
        stage,
        payload: { ...event.payload },
      });
      for (const playerId of this.options.world.entityIds()) {
        const nextVisibleSeq = (this.playerVisibleEventSeq.get(playerId) ?? 0) + 1;
        const visibleEvent = buildAgentVisibleEvent(
          this.options.world,
          event,
          playerId,
          nextVisibleSeq,
        );
        if (!visibleEvent) continue;
        // 按原顺序先占用局部序号再追加玩家记录；写入抛错时序号与前缀不会回滚。
        this.playerVisibleEventSeq.set(playerId, nextVisibleSeq);
        const roleComp = this.options.world.getComponent(playerId, COMPONENT.Role);
        this.options.replayManager.recordPlayerEvent({
          playerId,
          role: roleComp?.role ?? "unknown",
          camp: roleComp?.camp ?? "unknown",
          day: this.replayDayCursor,
          phase: this.replayPhaseCursor,
          stage: visibleEvent.type === "player_shot" ? "death_shot" : stage,
          requestId: `${this.replayDayCursor}-${this.replayPhaseCursor}-${playerId}-event-${nextVisibleSeq}`,
          timestampMs: event.timestamp,
          // 玩家来源序号属于自己的视图；全局索引会暴露隐藏 God 事件的数量。
          sourceEventSeq: nextVisibleSeq,
          event: visibleEvent,
        });
      }
      // 全部玩家视图处理完才推进主游标；中途失败不伪造原子提交或自动去重。
      this.recordedEventIndex = i + 1;
      delta.push(event);
    }
    return delta;
  }
}

/**
 * 负责装配一局游戏、收缩绝对期限、关闭运行资源并汇总失败。
 * 输入为已解析的对局设置与本次执行依赖；输出为记录结果和可选审计摘要。
 * 请求别名与原体权限仍由机制所有者校验；本模块保留停止、关闭、等待与落盘的顺序，
 * 后续失败不回滚已提交的动作，也不把可选摘要失败升级为对局失败。
 * Agent 与复现记录共用本局板子来源；maxDays 在原元数据读取处捕获，循环复用该值。
 */
