/** 仅返回最终运行快照与领域事件总数；完整回放由会话记录器持久化。 */
export interface GameRunResult {
  snapshot: RuntimeSnapshot;
  eventCount: number;
}
/**
 * 每局独立的执行依赖，不进入玩家 DTO 或 JSON 配置。
 * 期限选择回调返回绝对时间，只参与取最小值；关闭观察回调接收脱离副本，异常归清理失败。
 */
export interface GameRunDependencies {
  selectRequestDeadline?: (
    request: Readonly<{
      actorId: number;
      day: number;
      stage: ActionRequest["context"]["stage"];
      ordinal: number;
      actorOrdinal: number;
      retryAttempt: number;
      nowMs: number;
    }>,
  ) => number | undefined;
  onRuntimeClosed?: (state: PlayerAgentRuntime["runtimeState"]) => void;
}

class DeadlineAwareActionProvider implements ActionProvider {
  private ordinal = 0;
  private readonly actors = new Map<number, number>();
  // 同一玩家／日期／stage 的重试沿用已记录预算；新尝试仍受全局与原请求期限限制。
  private readonly budgets = new Map<string, number>();
  constructor(
    private readonly delegate: ActionProvider,
    private readonly deadlineAtMs: number,
    private readonly timeoutMs: number,
    private readonly selectDeadline?: GameRunDependencies["selectRequestDeadline"],
  ) {}

  getAction(request: ActionRequest): Promise<ToolCall | null> {
    const nowMs = Date.now(),
      actorOrdinal = (this.actors.get(request.actorId) ?? 0) + 1;
    this.actors.set(request.actorId, actorOrdinal);
    const ordinal = ++this.ordinal;
    const retryAttempt = request.context.retry_attempt ?? 0;
    const selected = this.selectDeadline?.({
      actorId: request.actorId,
      day: request.context.day,
      stage: request.context.stage,
      ordinal,
      actorOrdinal,
      retryAttempt,
      nowMs,
    });
    if (selected !== undefined && !Number.isFinite(selected))
      throw new RangeError("game_request_deadline_invalid");
    const key = `${request.actorId}/${request.context.day}/${request.context.stage}`;
    // 期限只取最早绝对时间，重试不重置整份超时；运行时授权随原请求一起派生。
    const deadline = Math.min(
      this.deadlineAtMs,
      request.deadlineAtMs ?? Infinity,
      nowMs + this.timeoutMs,
      selected ?? Infinity,
      retryAttempt > 0 ? (this.budgets.get(key) ?? Infinity) : Infinity,
    );
    this.budgets.set(key, deadline);
    const timed = deriveBoundedRequest(request, deadline);
    return this.delegate.getAction(timed);
  }
}

/** 调用方先完成设置解析；这里装配并执行对局，不读取配置来源文件。 */
export async function runGame(
  setup: ResolvedGameSetup,
  dependencies: GameRunDependencies = {},
): Promise<GameRunResult> {
  const context = bootstrapGame(setup.boardConfig, {
    random: createRandom(setup.context.seed),
    locale: setup.context.locale,
    playerNames: Object.fromEntries(
      Object.entries(setup.players).flatMap(([seat, entry]) =>
        entry.name !== undefined ? [[seat, entry.name]] : [],
      ),
    ),
  });
  const profilesByActor = selectPlayerProfiles(context.world, setup);
  const sessionId = buildSessionId();
  const recordRoot = setup.options.recordRootDir ?? resolveDefaultRecordRoot();
  const replayManager = await SessionRecordManager.create(
    {
      sessionId,
      locale: setup.context.locale,
      board: setup.options.board,
      startedAtIso: new Date().toISOString(),
      random: context.random.metadata,
    },
    recordRoot,
    setup.context.displayLocale,
  );

  return runWithSessionRecorder(replayManager, async () => {
    const { options } = setup;
    const log = createConsoleLog(options.color);
    const startedAt = Date.now();
    const deadlineAtMs = startedAt + options.maxRuntimeMs;
    // 对局／记录失败统一汇总；并发动作和关闭失败暂存，收尾时按原顺序补入。
    const failures: unknown[] = [];
    const eventRecorder = new GameEventRecorder(
      {
        world: context.world,
        replayManager,
      },
      context.phaseManager.getSnapshot().phase,
    );
    const flushEvents = () => {
      const delta = eventRecorder.flush(context.phaseManager.getEvents());
      if (options.streamEvents)
        presentStreamEvents(delta, options.printPrivateEvents, log, setup.context.displayLocale);
    };
    let agentRuntime: PlayerAgentRuntime | undefined;
    let heartbeat: NodeJS.Timeout | undefined;
    let streamTimer: NodeJS.Timeout | undefined;
    let timedOut = false;
    // stopping 立即拒绝新动作和迟到回复；closing 合并关闭调用，inFlight 单独负责等待结算。
    let stopping = false;
    let closing: Promise<void> | undefined;
    const stopReason = new DOMException("game_actions_stopped", "AbortError");
    const inFlight = new Set<Promise<ToolCall | null>>();
    const actionFailures: unknown[] = [];
    const cleanupFailures: unknown[] = [];
    let maxDays: number;
    // 先撤运行入口，再异步关闭 Agent；关闭异常暂存，不能覆盖触发停止的原始失败。
    const closeRuntime = (): Promise<void> => {
      stopping = true;
      closing ??= Promise.resolve()
        .then(() => agentRuntime?.close())
        .catch((error) => {
          cleanupFailures.push(error);
        });
      return closing;
    };
    const drainActions = async () => {
      while (inFlight.size) await Promise.allSettled([...inFlight]);
    };

    try {
      const reproduction = beginGameReproduction(replayManager, context, {
        engine: await currentEngineVersion(),
        boardId: options.board,
        locale: context.world.locale,
        maxDays: (maxDays = options.maxDays),
        profiles: profilesByActor,
      });
      agentRuntime = await createPlayerAgentRuntime({
        world: context.world,
        boardConfig: context.boardConfig,
        profilesByActor,
        acpWorkspaceRoot: path.join(recordRoot, sessionId, "acp-workspaces"),
        llmTimeoutMs: options.llmTimeoutMs,
        trace: options.trace,
        displayLocale: setup.context.displayLocale,
        colorizeLogs: options.color,
        printLlmIo: options.printLlmIo,
        printThinking: options.printThinking,
        createAcpUpdateObserver:
          options.printThinking || options.printLlmIo
            ? (actorId) =>
                createAcpConsoleLogger(actorId, log, setup.context.displayLocale, {
                  printThinking: options.printThinking,
                  printLlmIo: options.printLlmIo,
                })
            : undefined,
      });
      const selectedProvider: ActionProvider = {
        async getAction(request) {
          if (stopping) throw stopReason;
          const action = await agentRuntime!.provider.getAction(request);
          if (stopping) throw stopReason;
          return action;
        },
      };
      const decisionProvider: ActionProvider = {
        getAction: (request) => {
          const decision = reproduction.decide(request, selectedProvider);
          let tracked!: Promise<ToolCall | null>;
          tracked = decision.then(
            (action) => {
              inFlight.delete(tracked);
              return action;
            },
            (error) => {
              inFlight.delete(tracked);
              if (error !== stopReason) actionFailures.push(error);
              // 保留记录器已写的决策前缀，再开始取消其它动作，保留原异常的因果先后。
              void closeRuntime();
              throw error;
            },
          );
          inFlight.add(tracked);
          return tracked;
        },
      };
      const provider = new DeadlineAwareActionProvider(
        decisionProvider,
        deadlineAtMs,
        options.llmTimeoutMs,
        dependencies.selectRequestDeadline,
      );
      log(
        `[run_game] start board=${options.board} replay_session_id=${sessionId} record_dir=${replayManager.sessionDir} · ${text(setup.context.displayLocale, "runtime.start")}`,
        "info",
      );

      if (options.trace) {
        heartbeat = setInterval(() => {
          const snapshot = context.phaseManager.getSnapshot();
          log(
            `[run_game] heartbeat day=${snapshot.day} phase=${snapshot.phase} gameOver=${snapshot.gameOver} elapsed_ms=${Date.now() - startedAt} · ${text(setup.context.displayLocale, "runtime.heartbeat")}`,
            "muted",
          );
        }, 5000);
      }
      streamTimer = setInterval(() => {
        try {
          flushEvents();
        } catch (error) {
          failures.push(error);
          replayManager.noteReproductionFailure("recording", error);
          void closeRuntime();
          if (streamTimer) clearInterval(streamTimer);
        }
      }, 1000);

      let cycle = 0;
      while (!context.phaseManager.getSnapshot().gameOver && failures.length === 0) {
        const elapsed = Date.now() - startedAt;
        if (elapsed >= options.maxRuntimeMs) {
          timedOut = true;
          log(
            `[run_game] runtime_timeout elapsed_ms=${elapsed} · ${text(setup.context.displayLocale, "runtime.timeout")}`,
            "warn",
          );
          break;
        }
        cycle++;
        let complete = false;
        let cycleFailure: unknown;
        try {
          await context.phaseManager.runSingleCycle(provider, maxDays);
          complete = true;
        } catch (error) {
          cycleFailure = error;
          if (error !== stopReason) failures.push(error);
          replayManager.noteReproductionFailure("cycle", error);
          await closeRuntime();
          await drainActions();
        }
        // 无论周期成功或失败都保存实际结算前缀；失败周期先关闭并等待已在途动作。
        try {
          reproduction.checkpoint(
            captureCheckpoint(
              context.world,
              context.phaseManager.getSnapshot(),
              cycle,
              complete,
              context.phaseManager.getEvents().length,
              cycleFailure,
            ),
            context.phaseManager.getEvents(),
          );
        } catch (error) {
          failures.push(error);
          reproduction.invalidate();
          replayManager.noteReproductionFailure("recording", error);
        }
        if (failures.length) break;
        const snapshot = context.phaseManager.getSnapshot();
        log(
          `[run_game] cycle day=${snapshot.day} phase=${snapshot.phase} gameOver=${snapshot.gameOver} elapsed_ms=${Date.now() - startedAt} · ${text(setup.context.displayLocale, "runtime.cycle")}`,
          "info",
        );
      }
    } catch (error) {
      failures.push(error);
      replayManager.noteReproductionFailure("initialization", error);
    } finally {
      // 先停定时任务并补事件，再关闭／等待动作；最终记录只在这些原收尾步骤之后发布。
      if (heartbeat) clearInterval(heartbeat);
      if (streamTimer) clearInterval(streamTimer);
      try {
        flushEvents();
      } catch (error) {
        failures.push(error);
        replayManager.noteReproductionFailure("recording", error);
      }
      await closeRuntime();
      await drainActions();
      if (agentRuntime && dependencies.onRuntimeClosed) {
        try {
          dependencies.onRuntimeClosed(structuredClone(agentRuntime.runtimeState));
        } catch (error) {
          cleanupFailures.push(error);
        }
      }
      // 取消标记不列为独立动作错误；原异常按引用去重，清理失败仍按发生顺序追加。
      for (const error of actionFailures)
        if (!failures.includes(error)) {
          failures.push(error);
          replayManager.noteReproductionFailure("controller", error);
        }
      for (const error of cleanupFailures) {
        failures.push(error);
        replayManager.noteReproductionFailure("cleanup", error);
      }
      try {
        const snapshot = context.phaseManager.getSnapshot();
        const summaryInput = await replayManager.finalize({
          endedAtIso: new Date().toISOString(),
          winner: snapshot.result?.winner ?? null,
          ...(snapshot.result ? { gameResult: snapshot.result } : {}),
          finishReason: failures.length
            ? "runtime_error"
            : (snapshot.result?.reason ?? (timedOut ? "runtime_timeout" : "completed")),
          players: replayPlayers(context.world),
        });
        // 核心终档失败进入汇总；诊断摘要为可选输出，其异常只写日志。
        try {
          await replayManager.writeDebugSummary(
            await buildDebugSummaryMarkdown(
              {
                ...summaryInput,
                locale: setup.context.locale,
                displayLocale: setup.context.displayLocale,
              },
              setup.audit,
            ),
          );
        } catch (error) {
          log(
            `[audit] debug_summary_failed err=${formatErrorDiagnostic(error, setup.context.displayLocale)}`,
            "warn",
          );
        }
      } catch (error) {
        failures.push(error);
      }
    }

    if (failures.length === 1) throw failures[0];
    if (failures.length > 1) throw new AggregateError(failures, "game_run_failed");
    const snapshot = context.phaseManager.getSnapshot();
    const events = context.phaseManager.getEvents();
    presentGameResult({
      locale: setup.context.displayLocale,
      board: options.board,
      snapshot,
      events,
      timedOut,
      printAllEvents: options.printAllEvents,
      printChat: options.printChat,
      streamEvents: options.streamEvents,
      log,
    });
    return { snapshot, eventCount: events.length };
  });
}

function selectPlayerProfiles(
  world: World,
  setup: ResolvedGameSetup,
): Map<number, ResolvedAgentRuntimeProfile> {
  const profiles = new Map<number, ResolvedAgentRuntimeProfile>();
  for (const id of world.entityIds()) {
    const role = world.getComponent(id, COMPONENT.Role)?.role;
    profiles.set(id, resolvePlayerProfile(setup, id, role));
  }
  return profiles;
}

/**
 * 构造 God 终档的身份记录，不复用玩家观察视图。
 * 动物梦境读取已捕获的原名单／身份与原生命；初始身份机制保留原发牌，普通局使用当前组件。
 */
function replayPlayers(world: World) {
  const originalIds = animalOriginalAuditIds(world);
  if (originalIds)
    return originalIds.map((id) => {
      const original = animalOriginalAuditPlayer(world, id)!,
        identity = JSON.parse(original.identityJson);
      return {
        player_id: id,
        role: original.scope.roleId,
        camp: original.scope.campValue,
        alive: aliveLifeDescriptor(original.scope.life)!.get!.call(original.scope.life),
        name: identity.name,
      };
    });
  const initial = initialIdentityDeal(world);
  return world.entityIds().map((id, index) => {
    const role = world.getComponent(id, COMPONENT.Role);
    return {
      player_id: id,
      role: initialPlayerIdentity(world, id)?.role ?? initial?.[index] ?? role?.role ?? "unknown",
      camp:
        initialPlayerIdentity(world, id)?.camp ??
        (initial ? (initial[index] === "wolf" ? "wolf" : "good") : (role?.camp ?? "unknown")),
      alive: world.getComponent(id, COMPONENT.Alive)?.alive === true,
      name: world.getComponent(id, COMPONENT.Identity)?.name,
    };
  });
}

/**
 * 负责用明确种子与 provider 装配执行模拟批次。输入为板子／运行选项和各独立对局，输出原报告、分支计数与录制证据。
 * 特权 baseline 不是玩家知识 oracle，也不作为独立规则预期；每局 RNG 顺序保持，受限观察与录制使用同一绑定规则。
 */
import { isLocale, type Locale } from "@ai-werewolf-arena/game-contract";
import { bootstrapGame } from "../../app/bootstrap";
import {
  DEATH_SHOT_STAGES,
  createRandom,
  randomDraws,
  type ActionProvider,
  type GameEvent,
  type RuntimeSnapshot,
} from "../../core";
import { readFile } from "node:fs/promises";
import { ObservedBot, type BotStyle } from "../../ai/agents/providers/observed_bot";
import { ObservedPlayersActionProvider } from "../../app/observed-players-action-provider";
import type { ResolvedBoardDefinition } from "../config/board_definition";
import { SessionRecordManager } from "../../recording/session_recorder";
import { runWithSessionRecorder } from "../../recording/recording_context";
import { GameEventRecorder } from "../game_event_recorder";
import { COMPONENT, type RoleComponent } from "../../core";
import { getWitchState } from "../../game/mechanisms/roles/witch/ports";
import {
  beginGameReproduction,
  captureCheckpoint,
  currentEngineVersion,
} from "./reproduction_context";

export interface SimulationOptions {
  locale?: Locale;
  displayLocale?: Locale;
  seeds: readonly string[];
  recordRoot: string;
  maxDays?: number;
  styles?: readonly BotStyle[];
}

export interface SimulationReport {
  board: string;
  games: Array<{
    seed: string;
    recordDir: string;
    result: RuntimeSnapshot["result"];
    natural: boolean;
    branches: Record<string, number>;
    rejects: number;
    fallbacks: number;
  }>;
  branches: Record<string, number>;
  naturallyFinished: number;
  rejects: number;
  fallbacks: number;
}

/** 统计实际执行的技能结果，不仅按牌堆有某角色就算命中分支。 */
function branchCounts(events: readonly GameEvent[]): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const event of events) {
    const key =
      event.type === "witch_potion_used"
        ? `${event.type}.${event.payload.potionType}`
        : event.type === "guard_applied"
          ? `${event.type}.${event.payload.abstain ? "skip" : "protect"}`
          : event.type;
    counts[key] = (counts[key] ?? 0) + 1;
    if (event.type === "noble_servant_chosen" || event.type === "secret_body_chosen") {
      const choice = `${event.type}.${event.payload.targetId === null ? "pass" : "select"}`;
      counts[choice] = (counts[choice] ?? 0) + 1;
    }
    if (event.type === "noble_contract_closed") {
      const terminal = `${event.type}.${event.payload.status}`;
      counts[terminal] = (counts[terminal] ?? 0) + 1;
    }
    if (event.type === "secret_body_blocked") {
      const cause = `${event.type}.${event.payload.cause}`;
      counts[cause] = (counts[cause] ?? 0) + 1;
    }
    if (
      event.type === "radiant_shelter_chosen" ||
      event.type === "eclipse_swallowed" ||
      event.type === "alchemist_mist_chosen" ||
      event.type === "alchemist_snake_chosen" ||
      event.type === "raven_knife_chosen"
    ) {
      const spent =
        event.type === "alchemist_mist_chosen"
          ? event.payload.targetIds !== null
          : event.payload.targetId !== null;
      const outcome = `${event.type}.${spent ? "spend" : "pass"}`;
      counts[outcome] = (counts[outcome] ?? 0) + 1;
      if (spent && event.payload.day > 1) {
        const delayed = `${event.type}.later_spend`;
        counts[delayed] = (counts[delayed] ?? 0) + 1;
      }
    }
  }
  return counts;
}

/** 只有 controller 为断言／录制读取真值，受限策略消费 DTO；特权基线另有明确入口。 */
export async function simulateGames(
  board: ResolvedBoardDefinition,
  options: SimulationOptions,
): Promise<SimulationReport> {
  if (!options.seeds.length || new Set(options.seeds).size !== options.seeds.length)
    throw new Error("simulation_seeds_invalid");
  const locale = options.locale ?? "zh-CN";
  if (!isLocale(locale)) throw new Error("simulation_locale_invalid");
  const maxDays = options.maxDays ?? 30;
  if (!Number.isSafeInteger(maxDays) || maxDays < 1) throw new Error("simulation_max_days_invalid");
  const styles = options.styles ?? ["active", "conservative", "competitive", "random"];
  if (
    !styles.length ||
    styles.some((style) => !["active", "conservative", "competitive", "random"].includes(style))
  )
    throw new Error("simulation_styles_invalid");
  const report: SimulationReport = {
    board: board.definition.id,
    games: [],
    branches: {},
    naturallyFinished: 0,
    rejects: 0,
    fallbacks: 0,
  };
  const batchId = crypto.randomUUID();
  const engine = await currentEngineVersion();
  for (const [index, seed] of options.seeds.entries()) {
    const random = createRandom(seed);
    const context = bootstrapGame(board.config, { random, locale });
    const strategies = new Map(
      context.playerIds.map((id) => [
        id,
        new ObservedBot(
          randomDraws(random.fork("players").fork(`id:${id}`)),
          styles[Math.floor(random.fork("styles").fork(`id:${id}`).next() * styles.length)],
        ),
      ]),
    );
    const observed = new ObservedPlayersActionProvider(
      context.world,
      strategies,
    );
    const provider: ActionProvider = {
      async getAction(request) {
        if (context.phaseManager.getSnapshot().gameOver)
          throw new Error("simulation_action_after_game_over");
        if (
          !context.world.getAliveEntityIds().includes(request.actorId) &&
          request.context.stage !== "last_words" &&
          !DEATH_SHOT_STAGES.includes(request.context.stage) &&
          !(
            request.context.stage === "sheriff_badge_choice" &&
            request.allowedTools.includes("choose_badge_successor") &&
            context.world.hasDeathAction(
              request.actorId,
              "choose_badge_successor",
              request.phase,
              request.context.day,
              request.context.death_action_id,
            )
          )
        )
          throw new Error("simulation_unauthorized_dead_action");
        return observed.getAction(request);
      },
    };
    const manager = await SessionRecordManager.create(
      {
        sessionId: `simulation-${batchId}-${index}`,
        board: board.definition.id,
        locale: context.world.locale,
        startedAtIso: new Date().toISOString(),
        random: random.metadata,
      },
      options.recordRoot,
      options.displayLocale ?? locale,
    );
    const recorder = new GameEventRecorder(
      { world: context.world, replayManager: manager },
      context.phaseManager.getSnapshot().phase,
    );
    const summary = await runWithSessionRecorder(manager, async () => {
      const failures: unknown[] = [];
      const reproduction = beginGameReproduction(manager, context, {
        engine,
        boardId: board.definition.id,
        locale: context.world.locale,
        maxDays,
      });
      const recordedProvider: ActionProvider = {
        getAction: (request) => reproduction.decide(request, provider),
      };
      let cycle = 0;
      let priorAlive = context.world.getAliveEntityIds();
      const priorResources = new Map<number, { heal: number; poison: number }>();
      try {
        while (!context.phaseManager.getSnapshot().gameOver) {
          cycle++;
          let complete = false;
          let cycleFailure: unknown;
          try {
            await context.phaseManager.runSingleCycle(recordedProvider, maxDays);
            complete = true;
          } catch (error) {
            cycleFailure = error;
            failures.push(error);
            manager.noteReproductionFailure("cycle", error);
          }
          try {
            reproduction.checkpoint(
              captureCheckpoint(
                context.world,
                context.phaseManager.getSnapshot(),
                cycle,
                complete,
                context.phaseManager.getEvents().length,
                cycleFailure,
              ),
              context.phaseManager.getEvents(),
            );
          } catch (error) {
            failures.push(error);
            reproduction.invalidate();
            manager.noteReproductionFailure("recording", error);
          }
          if (failures.length) break;
          recorder.flush(context.phaseManager.getEvents());
          // 公开 controller 不变量不把隐藏真值反馈给决策。
          const alive = context.world.getAliveEntityIds();
          if (alive.some((id) => !priorAlive.includes(id)))
            throw new Error("simulation_unexpected_revival");
          priorAlive = alive;
          for (const id of context.world.entityIds()) {
            const role = context.world.getComponent(id, COMPONENT.Role);
            if (!role) throw new Error("simulation_missing_role");
            const witch = getWitchState(role);
            if (witch) {
              const prior = priorResources.get(id) ?? { heal: 1, poison: 1 };
              if (
                witch.heal < 0 ||
                witch.poison < 0 ||
                witch.heal > prior.heal ||
                witch.poison > prior.poison
              )
                throw new Error("simulation_invalid_resource_transition");
              priorResources.set(id, { heal: witch.heal, poison: witch.poison });
            }
          }
        }
      } catch (error) {
        failures.push(error);
        manager.noteReproductionFailure("controller", error);
      } finally {
        try {
          recorder.flush(context.phaseManager.getEvents());
        } catch (error) {
          failures.push(error);
        }
        try {
          const snapshot = context.phaseManager.getSnapshot();
          await manager.finalize({
            endedAtIso: new Date().toISOString(),
            winner: snapshot.result?.winner ?? null,
            ...(snapshot.result ? { gameResult: snapshot.result } : {}),
            finishReason: failures.length
              ? "runtime_error"
              : (snapshot.result?.reason ?? "incomplete"),
            players: context.playerIds.map((id) => {
              const role = context.world.getComponent(id, COMPONENT.Role)!;
              return {
                player_id: id,
                role: role.role,
                camp: role.camp,
                alive: context.world.getAliveEntityIds().includes(id),
              };
            }),
          });
        } catch (error) {
          failures.push(error);
        }
      }
      if (failures.length === 1) throw failures[0];
      if (failures.length) throw new AggregateError(failures, "simulation_game_failed");
      return manager;
    });
    // 落盘操作反映实际执行接受，不将策略的尝试冒充提交。
    const operations = JSON.parse(
      await readFile(`${summary.sessionDir}/logic_ops.json`, "utf8"),
    ) as { ops: Array<{ status: string }> };
    const branches = branchCounts(context.phaseManager.getEvents());
    const result = context.phaseManager.getSnapshot().result;
    const natural = result !== null && result.reason !== "max_days_reached";
    const rejects = operations.ops.filter((op) => op.status === "rejected").length;
    const fallbacks = operations.ops.filter((op) => op.status === "fallback").length;
    report.games.push({
      seed,
      recordDir: summary.sessionDir,
      result,
      natural,
      branches,
      rejects,
      fallbacks,
    });
    report.naturallyFinished += Number(natural);
    report.rejects += rejects;
    report.fallbacks += fallbacks;
    for (const [branch, count] of Object.entries(branches))
      report.branches[branch] = (report.branches[branch] ?? 0) + count;
  }
  return report;
}

